#------------------Database Connection------------------------------------------ 

get_db_con <- function() {
  con <- DBI::dbConnect(
    RPostgres::Postgres(),
    dbname   = Sys.getenv("DB_NAME"),
    host     = Sys.getenv("DB_HOST"),
    port     = as.integer(Sys.getenv("PGPORT", "5433")),  
    user     = Sys.getenv("DB_USER"),
    password = Sys.getenv("DB_PASSWORD"),
    sslmode  = "disable"
  )
  

  DBI::dbExecute(con, "SET timezone = 'Europe/Berlin'")
  
  return(con)
}


