#------------------------------ UI generation-----------------------------------
make_ui <- function(question_list, score_prefix = "Freitext", text_prefix = "Freitext_text") {
  ui_elements <- lapply(question_list, function(q) {
    btn_id <- paste0("info_", q$id)
    
    list(
      div(
        style = "margin-bottom: 20px;",
        tags$h5(
          style = "text-align: left;",
          strong(paste0(q$number, ". ", q$label)),
          " ",
          bsButton(
            btn_id,
            label = "",
            icon = icon("info-circle"),
            style = "info",
            size = "extra-small"
          )
        ),
        radioButtons(
          paste0(score_prefix, q$id),
          label = NULL,
          choices = c("N/A", 1:5),
          selected = "N/A",
          inline = TRUE
        ),
        textAreaInput(
          paste0(text_prefix, q$id),
          label = NULL,
          placeholder = "Text eingeben...",
          height = "100px",
          width = "100%"
        )
      ),
      bsPopover(
        id = btn_id,
        title = paste("Info zu Frage", q$number),
        content = q$info,
        placement = "right",
        trigger = "hover",
        options = list(container = "body")
      )
    )
  })
  
  # Flatten the list
  do.call(tagList, unlist(ui_elements, recursive = FALSE))
}


