    .dashboard-row:hover { background-color: #f8f9fa; }
    .dashboard-table td { padding: 10px 8px; vertical-align: top; border: 1px solid #dee2e6; }
    .dashboard-col-question { font-size: 13px; line-height: 1.4; color: #212529; }
