#---------------------------- Server Logic -------------------------------------



server <- function(input, output, session) {
  
  must_reset_trigger <- reactiveVal(FALSE)
  
  # Core session state (define ONCE, at the top!)
  user_logged_in <- reactiveVal(FALSE)
  user_id <- reactiveVal(NULL)
  user_role <- reactiveVal(NULL)
  current_username <- reactiveVal(NULL)
  current_project_id <- reactiveVal(NULL)
  current_project_name <- reactiveVal(NULL)
  current_submission_id <- reactiveVal(NULL)
  redeemed_code_info <- reactiveVal(NULL)
  project_data_changed <- reactiveVal(0)
  responses_data_changed <- reactiveVal(0)
  invitation_data_changed <- reactiveVal(0)
  project_title_val <- reactiveVal("")
  consent_given <- reactiveVal(FALSE)
  
  draft_loaded <- reactiveVal(FALSE)
  fragebogen_ui_ready <- reactiveVal(FALSE)
  last_tab <- reactiveVal(NULL)
  
  # Output options
  output$userRole <- reactive({ user_role() })
  outputOptions(output, "userRole", suspendWhenHidden = FALSE)
  output$isAdmin <- reactive({ user_role() == "admin" })
  output$isLeiter <- reactive({ user_role() == "laborleitung" })
  output$isLeadingPeer <- reactive({ user_role() == "leading_peer" })
  output$isColleague <- reactive({ user_role() == "colleague" })
  output$isCoPeer <- reactive({ user_role() == "co_peer" })
  outputOptions(output, "isAdmin", suspendWhenHidden = FALSE)
  outputOptions(output, "isLeiter", suspendWhenHidden = FALSE)
  outputOptions(output, "isLeadingPeer", suspendWhenHidden = FALSE)
  outputOptions(output, "isColleague", suspendWhenHidden = FALSE)
  outputOptions(output, "isCoPeer", suspendWhenHidden = FALSE)
  
  is_co_peer <- reactive({
    user_role() == "co_peer"
  })
  
  is_leading_peer <- function() {
    !is.null(user_role()) && user_role() == "leading_peer"
  }
  
  # Logout function
  do_logout <- function() {
    user_logged_in(FALSE)
    user_id(NULL)
    user_role(NULL)
    current_username(NULL)
    current_project_id(NULL)
    current_submission_id(NULL)
    redeemed_code_info(NULL)
    session$userData$user_id <- NULL
    session$userData$username <- NULL
    session$userData$invitation_code <- NULL
    showNotification("Erfolgreich abgemeldet.", type = "message")
    updateTabItems(session, "sidebar_menu", selected = "start")
  }
  
  
  # Helper functions
  safe_equal <- function(a, b) {
    if (is.na(a) || is.na(b)) return(FALSE)
    isTRUE(a == b)
  }
  
  force_reset_db <- function(con, username) {
    DBI::dbExecute(
      con,
      "UPDATE users SET must_reset = TRUE WHERE username = $1",
      params = list(username)
    )
  }
  
 # demo-mode reactive flag 
  is_demo_mode <- reactive({
    user_logged_in() &&
      identical(user_role(), "power_user") &&
      identical(input$poweruser_tabs, "Demo-Selbstbewertung")
  })
  
  #------------------------ FREMDBEWERTUNG ADMIN -------------------------------
  
  # Load projects for dropdown
  observe({
    req(user_logged_in())
    req(user_role() == "admin")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    projects <- DBI::dbGetQuery(con, "
    SELECT id, title FROM projects 
    WHERE status = 'active'
    ORDER BY created_at DESC
  ")
    
    choices <- setNames(projects$id, projects$title)
    
    updateSelectInput(session, "admin_fremd_project", choices = choices)
  })
  
  # Load reviewers for filter
  observe({
    req(input$admin_fremd_project)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    reviewers <- DBI::dbGetQuery(con, "
    SELECT DISTINCT u.username
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
    ORDER BY u.username
  ", params = list(as.character(input$admin_fremd_project)))
    
    choices <- c("Alle" = "", setNames(reviewers$username, reviewers$username))
    
    updateSelectInput(session, "admin_fremd_filter_user", choices = choices)
  })
  
  # Summary statistics
  output$fremdbewertung_summary <- renderUI({
    req(input$admin_fremd_project)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Count submissions
    stats <- DBI::dbGetQuery(con, "
    SELECT 
      COUNT(DISTINCT r.user_id) as total_reviewers,
      COUNT(DISTINCT r.submission_id) as total_submissions,
      COUNT(*) as total_responses,
      MIN(r.created_at) as first_submission,
      MAX(r.created_at) as last_submission
    FROM responses r
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
  ", params = list(as.character(input$admin_fremd_project)))
    
    # Get reviewer details
    reviewers <- DBI::dbGetQuery(con, "
    SELECT DISTINCT
      u.username,
      u.role,
      COUNT(r.question_id) as answer_count,
      MAX(r.created_at) as submitted_at
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
    GROUP BY u.username, u.role
    ORDER BY submitted_at DESC
  ", params = list(as.character(input$admin_fremd_project)))
    
    tagList(
      fluidRow(
        column(3,
               div(class = "info-box bg-aqua",
                   style = "padding: 15px; border-radius: 5px; color: white; background: #00c0ef;",
                   div(style = "font-size: 14px; font-weight: 600;", "Anzahl Reviewer"),
                   div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", 
                       stats$total_reviewers)
               )
        ),
        column(3,
               div(class = "info-box bg-green",
                   style = "padding: 15px; border-radius: 5px; color: white; background: #00a65a;",
                   div(style = "font-size: 14px; font-weight: 600;", "Eingereichte Bewertungen"),
                   div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", 
                       stats$total_submissions)
               )
        ),
        column(3,
               div(class = "info-box bg-yellow",
                   style = "padding: 15px; border-radius: 5px; color: white; background: #f39c12;",
                   div(style = "font-size: 14px; font-weight: 600;", "Gesamte Antworten"),
                   div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", 
                       stats$total_responses)
               )
        ),
        column(3,
               div(class = "info-box bg-red",
                   style = "padding: 15px; border-radius: 5px; color: white; background: #dd4b39;",
                   div(style = "font-size: 14px; font-weight: 600;", "Letzte Einreichung"),
                   div(style = "font-size: 16px; font-weight: bold; margin-top: 10px;", 
                       if (!is.na(stats$last_submission)) {
                         format(as.POSIXct(stats$last_submission), "%d.%m.%Y %H:%M")
                       } else {
                         "—"
                       })
               )
        )
      ),
      
      br(),
      
      if (nrow(reviewers) > 0) {
        tagList(
          h5(icon("users"), " Reviewer Details:"),
          tags$table(
            class = "table table-striped table-condensed",
            style = "font-size: 13px;",
            tags$thead(
              tags$tr(
                tags$th("Reviewer"),
                tags$th("Rolle"),
                tags$th("Anzahl Antworten"),
                tags$th("Eingereicht am")
              )
            ),
            tags$tbody(
              lapply(1:nrow(reviewers), function(i) {
                tags$tr(
                  tags$td(tags$strong(reviewers$username[i])),
                  tags$td(
                    tags$span(
                      class = if (reviewers$role[i] == "leading_peer") "label label-primary" else "label label-info",
                      if (reviewers$role[i] == "leading_peer") "Leading Peer" else "Co-Peer"
                    )
                  ),
                  tags$td(reviewers$answer_count[i]),
                  tags$td(format(as.POSIXct(reviewers$submitted_at[i]), "%d.%m.%Y %H:%M"))
                )
              })
            )
          )
        )
      }
    )
  })
  
  # Detailed table (reactive data)
  fremdbewertung_data <- reactive({
    req(input$admin_fremd_project)
    
    # Trigger refresh
    input$admin_fremd_refresh
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Build query with filters
    query <- "
    SELECT 
      u.username as Reviewer,
      u.role as Rolle,
      r.question_id as Frage_ID,
      r.response_value as Bewertung,
      r.text_value as Kommentar,
      r.created_at as Eingereicht_am,
      r.submission_id
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
  "
    
    params <- list(as.character(input$admin_fremd_project))
    
    # Add user filter
    if (!is.null(input$admin_fremd_filter_user) && input$admin_fremd_filter_user != "") {
      query <- paste(query, "AND u.username = $2")
      params <- c(params, list(input$admin_fremd_filter_user))
    }
    
    # Add section filter
    if (!is.null(input$admin_fremd_filter_section) && input$admin_fremd_filter_section != "") {
      if (length(params) == 1) {
        query <- paste(query, "AND r.question_id LIKE $2")
        params <- c(params, list(paste0(input$admin_fremd_filter_section, "%")))
      } else {
        query <- paste(query, "AND r.question_id LIKE $3")
        params <- c(params, list(paste0(input$admin_fremd_filter_section, "%")))
      }
    }
    
    query <- paste(query, "ORDER BY r.created_at DESC, r.question_id")
    
    responses <- DBI::dbGetQuery(con, query, params = params)
    
    if (nrow(responses) > 0) {
      responses$Eingereicht_am <- format(
        as.POSIXct(responses$Eingereicht_am), 
        "%d.%m.%Y %H:%M"
      )
      
      # Translate roles
      responses$Rolle <- ifelse(
        responses$Rolle == "leading_peer", 
        "Leading Peer", 
        "Co-Peer"
      )
      
      # Add section column
      responses$Bereich <- substr(responses$Frage_ID, 1, 1)
      responses$Bereich <- factor(
        responses$Bereich,
        levels = c("F", "M", "P", "E", "Q"),
        labels = c("Führung", "Mitarbeitende", "Patienten", "Einsender", "Qualität")
      )
      
      # Reorder columns
      responses <- responses[, c("Reviewer", "Rolle", "Bereich", "Frage_ID", 
                                 "Bewertung", "Kommentar", "Eingereicht_am")]
    }
    
    responses
  })
  
  # Render data table
  output$fremdbewertung_table <- DT::renderDataTable({
    
    data <- fremdbewertung_data()
    
    DT::datatable(
      data,
      options = list(
        pageLength = 25,
        order = list(list(6, 'desc')),  # Sort by date descending
        scrollX = TRUE,
        columnDefs = list(
          list(width = '120px', targets = 0),  # Reviewer
          list(width = '100px', targets = 1),  # Rolle
          list(width = '100px', targets = 2),  # Bereich
          list(width = '80px', targets = 3),   # Frage_ID
          list(width = '80px', targets = 4),   # Bewertung
          list(width = '300px', targets = 5),  # Kommentar
          list(width = '130px', targets = 6)   # Eingereicht_am
        )
      ),
      rownames = FALSE,
      filter = "top",
      class = 'cell-border stripe compact',
      escape = FALSE
    ) %>%
      DT::formatStyle(
        'Bewertung',
        backgroundColor = DT::styleInterval(
          c(2, 3, 4),
          c('#ffcccc', '#ffffcc', '#ccffcc', '#99ff99')
        )
      )
  })
  
  # Download CSV
  output$download_fremdbewertung_csv <- downloadHandler(
    filename = function() {
      paste0("Fremdbewertung_", input$admin_fremd_project, "_", Sys.Date(), ".csv")
    },
    content = function(file) {
      data <- fremdbewertung_data()
      write.csv(data, file, row.names = FALSE, fileEncoding = "UTF-8")
    }
  )
  
  
  
  #----------------------------- POWER USER SERVER LOGIC------------------------
  
  # ========== POWER USER DASHBOARD ==========
  
  # Reactive output for user role
  output$user_role <- reactive({
    user_role()
  })
  outputOptions(output, "user_role", suspendWhenHidden = FALSE)
  
  # Power User Server Logic
  observeEvent(user_role(), {
    if (!is.null(user_role()) && user_role() == "power_user") {
      
      con <- get_db_con()
      
      # ✅ ADD REFRESH TRIGGER
      projects_refresh <- reactiveVal(0)
      codes_refresh <- reactiveVal(0)
      
      # ========== LOAD DATA ==========
      
      get_all_projects <- reactive({
        projects_refresh()  # ✅ Trigger refresh
        
        projects <- DBI::dbGetQuery(con, "
        SELECT 
          id,
          title,
          TO_CHAR(created_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as created_at,
          (SELECT COUNT(*) FROM users WHERE project_id = projects.id) as user_count
        FROM projects
        ORDER BY created_at DESC
      ")
        
        return(projects)
      })
      
      get_all_users <- reactive({
        req(input$poweruser_filter_project, input$poweruser_filter_role)
        
        query <- "
        SELECT 
          u.id,
          'User-' || u.id as user_id,
          u.username,
          u.role,
          p.title as project,
          TO_CHAR(u.registered_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as registered_at,
          CASE 
            WHEN r.user_id IS NULL THEN 'Nein' 
            ELSE 'Ja' 
          END as completed
        FROM users u
        LEFT JOIN projects p ON p.id = u.project_id
        LEFT JOIN (
          SELECT DISTINCT user_id 
          FROM responses 
          WHERE submission_id IS NOT NULL
        ) r ON r.user_id = u.id
        WHERE u.role NOT IN ('admin', 'power_user')
      "
        
        params <- list()
        
        if (input$poweruser_filter_project != "") {
          query <- paste0(query, " AND u.project_id = $1")
          params <- list(as.integer(input$poweruser_filter_project))
        }
        
        if (input$poweruser_filter_role != "") {
          if (length(params) > 0) {
            query <- paste0(query, " AND u.role = $2")
            params <- c(params, list(input$poweruser_filter_role))
          } else {
            query <- paste0(query, " AND u.role = $1")
            params <- list(input$poweruser_filter_role)
          }
        }
        
        query <- paste0(query, " ORDER BY u.registered_at DESC")
        
        if (length(params) > 0) {
          DBI::dbGetQuery(con, query, params = params)
        } else {
          DBI::dbGetQuery(con, query)
        }
      })
      
      get_invitation_codes <- reactive({
        codes_refresh()  # ✅ Trig
        
        DBI::dbGetQuery(con, "
    SELECT 
      ic.code,
      p.title as project,
      ic.role,
      ic.assessment_type,
      CASE 
        WHEN ic.used_at IS NOT NULL THEN 'Ja'
        ELSE 'Nein'
      END as used,
      TO_CHAR(ic.generated_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as created_at,
      TO_CHAR(ic.used_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as used_at
    FROM invitation_codes ic
    LEFT JOIN projects p ON p.id = ic.project_id
    ORDER BY ic.generated_at DESC
  ")
      })
      
      # ========== POPULATE DROPDOWNS ==========
      
      observe({
        projects <- get_all_projects()
        
        choices <- setNames(projects$id, projects$title)
        choices_with_all <- c("Alle" = "", choices)
        
        updateSelectInput(session, "poweruser_selbst_summary_project_selector", choices = choices)
        updateSelectInput(session, "poweruser_filter_project", choices = choices_with_all)
        updateSelectInput(session, "poweruser_invite_project", choices = choices)
        updateSelectInput(session, "poweruser_report_project", choices = choices)
        updateSelectInput(session, "poweruser_fremd_project", choices = choices)
      })
      
      # ========== FREMDBEWERTUNG OVERVIEW ==========
      
      output$poweruser_fremdbewertung_summary <- renderUI({
        req(input$poweruser_fremd_project)
        
        stats <- DBI::dbGetQuery(con, "
          SELECT
            COUNT(DISTINCT r.user_id) as total_reviewers,
            COUNT(*) as total_responses
          FROM responses r
          WHERE r.project_id = $1
            AND r.assessment_type = 'fremdbewertung'
        ", params = list(as.integer(input$poweruser_fremd_project)))
        
        fluidRow(
          column(
            6,
            div(
              class = "info-box bg-aqua",
              style = "padding: 15px; border-radius: 5px; color: white; background: #00c0ef;",
              div(style = "font-size: 14px; font-weight: 600;", "Anzahl Reviewer"),
              div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", stats$total_reviewers)
            )
          ),
          column(
            6,
            div(
              class = "info-box bg-yellow",
              style = "padding: 15px; border-radius: 5px; color: white; background: #f39c12;",
              div(style = "font-size: 14px; font-weight: 600;", "Gesamte Antworten"),
              div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", stats$total_responses)
            )
          )
        )
      })
      
      poweruser_fremdbewertung_data <- reactive({
        req(input$poweruser_fremd_project)
        
        input$poweruser_fremd_refresh
        
        query <- "
          SELECT 
            u.username as reviewer,
            r.question_id,
            r.response_value,
            r.assessment_type,
            TO_CHAR(r.submitted_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as submitted_at
          FROM responses r
          JOIN users u ON u.id = r.user_id
          WHERE r.project_id = $1
            AND r.assessment_type = 'fremdbewertung'
        "
        
        params <- list(as.integer(input$poweruser_fremd_project))
        
        if (!is.null(input$poweruser_fremd_filter_user) && input$poweruser_fremd_filter_user != "") {
          query <- paste(query, "AND u.username = $2")
          params <- c(params, list(input$poweruser_fremd_filter_user))
        }
        
        if (!is.null(input$poweruser_fremd_filter_section) && input$poweruser_fremd_filter_section != "") {
          if (length(params) == 1) {
            query <- paste(query, "AND r.question_id LIKE $2")
            params <- c(params, list(paste0(input$poweruser_fremd_filter_section, "%")))
          } else {
            query <- paste(query, "AND r.question_id LIKE $3")
            params <- c(params, list(paste0(input$poweruser_fremd_filter_section, "%")))
          }
        }
        
        query <- paste(query, "ORDER BY u.username, r.question_id")
        
        data <- DBI::dbGetQuery(con, query, params = params)
        
        reviewers <- DBI::dbGetQuery(con, "
          SELECT DISTINCT u.username as reviewer
          FROM responses r
          JOIN users u ON u.id = r.user_id
          WHERE r.project_id = $1
            AND r.assessment_type = 'fremdbewertung'
          ORDER BY u.username
        ", params = list(as.integer(input$poweruser_fremd_project)))
        
        reviewer_choices <- c("Alle" = "", setNames(reviewers$reviewer, reviewers$reviewer))
        updateSelectInput(session, "poweruser_fremd_filter_user", choices = reviewer_choices)
        
        data
      })
      
      output$poweruser_fremdbewertung_table <- DT::renderDataTable({
        DT::datatable(
          poweruser_fremdbewertung_data(),
          options = list(
            pageLength = 25,
            scrollX = TRUE
          ),
          rownames = FALSE,
          class = "cell-border stripe compact"
        )
      })
      
      output$poweruser_download_fremdbewertung_csv <- downloadHandler(
        filename = function() {
          paste0("Fremdbewertung_", input$poweruser_fremd_project, "_", Sys.Date(), ".csv")
        },
        content = function(file) {
          write.csv(poweruser_fremdbewertung_data(), file, row.names = FALSE, fileEncoding = "UTF-8")
        }
      )
      
      # ========== TABLES ==========
      
      output$poweruser_projects_table <- renderDT({
        projects <- get_all_projects()
        
        datatable(
          projects,
          colnames = c("ID", "Projekttitel", "Erstellt am", "Anzahl Benutzer"),
          options = list(
            pageLength = 25,
            order = list(list(2, 'desc'))
          ),
          rownames = FALSE
        )
      })
      
      observeEvent(input$poweruser_refresh_projects, {
        projects_refresh(projects_refresh() + 1)  # ✅ Trigger reload
        showNotification("Projekte aktualisiert", type = "message")
      })
      
      output$poweruser_users_table <- renderDT({
        users <- get_all_users()
        
        # Remove username column for privacy (like admin does)
        display_cols <- c("user_id", "role", "project", "completed", "registered_at")
        
        datatable(
          users[, display_cols],
          colnames = c("Benutzer-ID", "Rolle", "Projekt", "Abgeschlossen", "Registriert am"),
          options = list(
            pageLength = 25,
            order = list(list(4, 'desc'))
          ),
          rownames = FALSE
        )
      })
      
      output$poweruser_codes_table <- renderDT({
        codes <- get_invitation_codes()
        
        datatable(
          codes,
          colnames = c("Code", "Projekt", "Rolle", "Assessment-Typ", "Verwendet", "Erstellt am", "Verwendet am"), 
          options = list(
            pageLength = 25,
            order = list(list(5, 'desc'))
          ),
          rownames = FALSE
        )
      })
      
      observeEvent(input$poweruser_refresh_codes, {
        codes_refresh(codes_refresh() + 1)  # ✅ Trigger reload
        showNotification("Codes aktualisiert", type = "message")
      })
      
      # ========== CREATE PROJECT ==========
      
      observeEvent(input$poweruser_create_project_button, {
        
        if (is.null(input$poweruser_project_name) || trimws(input$poweruser_project_name) == "") {
          output$poweruser_project_creation_status <- renderUI({
            div(
              class = "alert alert-danger",
              style = "margin-top: 15px;",
              icon("exclamation-circle"),
              strong(" Fehler: "),
              "Bitte geben Sie einen Projektnamen ein."
            )
          })
          return()
        }
        
        project_title <- trimws(input$poweruser_project_name)
        
        # Show loading
        output$poweruser_project_creation_status <- renderUI({
          div(
            class = "alert alert-info",
            style = "margin-top: 15px;",
            icon("spinner", class = "fa-spin"),
            " Projekt wird erstellt..."
          )
        })
        
        tryCatch({
          new_project <- DBI::dbGetQuery(
            con,
            "INSERT INTO projects (title, einrichtung, description, zeitraum, created_at, owner_id, status)
           VALUES ($1, $2, $3, $4, NOW(), $5, 'active')
           RETURNING id, title",
            params = list(
              project_title,
              if (is.null(input$poweruser_einrichtung_create) || trimws(input$poweruser_einrichtung_create) == "") NA else trimws(input$poweruser_einrichtung_create),
              if (is.null(input$poweruser_project_description) || trimws(input$poweruser_project_description) == "") NA else trimws(input$poweruser_project_description),
              if (is.null(input$poweruser_zeitraum) || trimws(input$poweruser_zeitraum) == "") NA else trimws(input$poweruser_zeitraum),
              user_id()
            )
          )
          
          if (nrow(new_project) > 0) {
            new_id <- as.character(new_project$id[1])
            new_title <- new_project$title[1]
            
            # ✅ Trigger refresh to show new project
            projects_refresh(projects_refresh() + 1)
            
            output$poweruser_project_creation_status <- renderUI({
              div(
                class = "alert alert-success",
                style = "margin-top: 15px;",
                icon("check-circle"),
                strong(" Erfolg! "),
                sprintf("Projekt '%s' wurde erstellt.", new_title)
              )
            })
            
            showNotification(
              paste0("✓ Projekt '", new_title, "' erstellt!"),
              type = "message",
              duration = 5
            )
            
            # Clear form
            updateTextInput(session, "poweruser_project_name", value = "")
            updateTextInput(session, "poweruser_einrichtung_create", value = "")
            updateTextAreaInput(session, "poweruser_project_description", value = "")
            updateTextInput(session, "poweruser_zeitraum", value = "")
          }
          
        }, error = function(e) {
          output$poweruser_project_creation_status <- renderUI({
            div(
              class = "alert alert-danger",
              style = "margin-top: 15px;",
              icon("exclamation-triangle"),
              strong(" Fehler: "),
              e$message
            )
          })
        })
      })
      
      # ========== AUTO-SELECT ASSESSMENT TYPE BASED ON ROLE ==========
      
      observeEvent(input$poweruser_invite_role, {
        # Auto-select assessment type based on role
        if (input$poweruser_invite_role %in% c("laborleitung", "colleague")) {
          updateSelectInput(session, "poweruser_code_type", selected = "selbstbewertung")
        } else if (input$poweruser_invite_role %in% c("leading_peer", "co_peer")) {
          updateSelectInput(session, "poweruser_code_type", selected = "fremdbewertung")
        }
      })
      
      # ========== GENERATE CODES ==========
      
      observeEvent(input$poweruser_generate_codes, {
        req(input$poweruser_invite_project, input$poweruser_invite_role, input$poweruser_invite_count, input$poweruser_code_type)
        
        num_codes <- input$poweruser_invite_count
        code_type <- input$poweruser_code_type
        invite_role <- input$poweruser_invite_role
        project_id <- as.integer(input$poweruser_invite_project)
        
        if (num_codes <= 0) {
          output$poweruser_code_generation_status <- renderUI(
            div(
              style = "padding: 10px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px; margin-top: 15px;",
              icon("exclamation-triangle", style = "color: #721c24;"),
              tags$span(style = "margin-left: 8px; color: #721c24;", "Bitte geben Sie eine positive Anzahl ein.")
            )
          )
          return()
        }
        
        generated_codes_list <- c()
        
        tryCatch({
          for (i in seq_len(num_codes)) {
            code <- generate_random_code()
            
            DBI::dbExecute(
              con,
              "INSERT INTO invitation_codes (code, role, assessment_type, generated_at, project_id, generated_by, expires_at)
         VALUES ($1, $2, $3, NOW(), $4, $5, NOW() + INTERVAL '30 days')",
              params = list(code, invite_role, code_type, project_id, user_id())
            )
            
            generated_codes_list <- c(generated_codes_list, code)
          }
          
          # ✅ Get project name
          proj_name <- DBI::dbGetQuery(
            con,
            "SELECT title FROM projects WHERE id = $1",
            params = list(project_id)
          )$title[1]
          
          # ✅ Calculate expiry date (30 days from now)
          expiry_date <- format(Sys.Date() + 30, "%d.%m.%Y")
          
          # ✅ Show success message with expiry info
          output$poweruser_code_generation_status <- renderUI({
            div(
              style = "padding: 15px; background-color: #d4edda; border: 1px solid #c3e6cb; border-radius: 4px; margin-top: 15px;",
              div(
                style = "display: flex; align-items: center;",
                icon("check-circle", style = "color: #155724; font-size: 24px;"),
                div(
                  style = "margin-left: 15px; color: #155724;",
                  tags$strong(
                    style = "font-size: 16px;",
                    sprintf("✓ %d Einladungscode(s) erfolgreich generiert!", length(generated_codes_list))
                  ),
                  tags$div(
                    style = "margin-top: 8px; font-size: 14px;",
                    icon("clock"),
                    sprintf(" Gültig bis: %s (30 Tage)", expiry_date)
                  ),
                  tags$div(
                    style = "margin-top: 5px; font-size: 14px;",
                    icon("folder"),
                    sprintf(" Projekt: %s", proj_name)
                  )
                )
              )
            )
          })
          
          # ✅ Show codes in table with expiry
          output$poweruser_generated_codes_table <- renderDataTable({
            data.frame(
              "Einladungscode" = generated_codes_list,
              "Rolle" = invite_role,
              "Typ" = code_type,
              "Projekt" = proj_name,
              "Gültig bis" = expiry_date,
              stringsAsFactors = FALSE,
              check.names = FALSE
            )
          }, options = list(
            pageLength = 50,
            dom = 't',  # Just show table (no search/pagination for small list)
            columnDefs = list(
              list(width = '300px', targets = 0),  # Wide code column
              list(className = 'dt-center', targets = 1:4)  # Center other columns
            )
          ))
          
          # ✅ Trigger refresh of all codes table
          codes_refresh(codes_refresh() + 1)
          
          showNotification(
            sprintf("✓ %d Einladungscode(s) generiert!", length(generated_codes_list)),
            type = "message",
            duration = 5
          )
          
        }, error = function(e) {
          output$poweruser_code_generation_status <- renderUI(
            div(
              style = "padding: 10px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px; margin-top: 15px;",
              icon("exclamation-triangle", style = "color: #721c24;"),
              tags$span(style = "margin-left: 8px; color: #721c24;", paste("Fehler:", e$message))
            )
          )
        })
      })
      
      
      # ========== ALL CODES TABLE ==========
      
      output$poweruser_all_codes_table <- renderDT({
        codes_refresh()  # Trigger on refresh
        
        all_codes <- DBI::dbGetQuery(con, "
    SELECT 
      ic.code,
      p.title as project,
      ic.role,
      ic.assessment_type,
      TO_CHAR(ic.generated_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as created_at,
      CASE 
        WHEN ic.used_at IS NOT NULL THEN 'Ja'
        ELSE 'Nein'
      END as used,
      TO_CHAR(ic.expires_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') as expires_at
    FROM invitation_codes ic
    LEFT JOIN projects p ON p.id = ic.project_id
    ORDER BY ic.generated_at DESC
  ")
        
        datatable(
          all_codes,
          colnames = c("Code", "Projekt", "Rolle", "Typ", "Erstellt am", "Verwendet", "Gültig bis"),
          options = list(
            pageLength = 25,
            order = list(list(4, 'desc'))  # Sort by created_at
          ),
          rownames = FALSE
        )
      })
      # ========== DOWNLOAD REPORTS ==========
      
      output$poweruser_download_zusammenfassung <- downloadHandler(
        filename = function() {
          project_id <- input$poweruser_report_project
          project_title <- get_all_projects() %>%
            filter(id == project_id) %>%
            pull(title)
          
          paste0("Zusammenfassung_", gsub(" ", "_", project_title), "_", Sys.Date(), ".pdf")
        },
        content = function(file) {
          generate_zusammenfassung_pdf(file, input$poweruser_report_project)
        }
      )
      
      output$poweruser_download_gesamtbericht <- downloadHandler(
        filename = function() {
          project_id <- input$poweruser_report_project
          project_title <- get_all_projects() %>%
            filter(id == project_id) %>%
            pull(title)
          
          paste0("Gesamtbericht_", gsub(" ", "_", project_title), "_", Sys.Date(), ".pdf")
        },
        content = function(file) {
          generate_gesamtbericht_pdf(file, input$poweruser_report_project)
        }
      )
      
      output$poweruser_download_labinfo <- downloadHandler(
        filename = function() {
          project_id <- input$poweruser_report_project
          project_title <- get_all_projects() %>%
            filter(id == project_id) %>%
            pull(title)
          
          paste0("Laborinfo_", gsub(" ", "_", project_title), "_", Sys.Date(), ".pdf")
        },
        content = function(file) {
          generate_labinfo_pdf(file, input$poweruser_report_project)
        }
      )
      
      output$poweruser_download_comparison <- downloadHandler(
        filename = function() {
          project_id <- input$poweruser_report_project
          project_title <- tryCatch({
            get_all_projects() %>%
              dplyr::filter(id == as.integer(project_id)) %>%
              dplyr::pull(title)
          }, error = function(e) "Projekt")
          paste0("Vergleichstabelle_", gsub(" ", "_", project_title), "_", Sys.Date(), ".pdf")
        },
        content = function(file) {
          req(input$poweruser_report_project)
          project_id <- input$poweruser_report_project
          if (is.null(project_id) || project_id == "") {
            showNotification("Kein Projekt ausgewählt!", type = "error", duration = 5)
            return(NULL)
          }
          generate_comparison_pdf(file, project_id, user_role())
        }
      )
      
      # ========== PASSWORD CHANGE ==========
      
      observeEvent(input$poweruser_change_password, {
        req(input$poweruser_current_password, input$poweruser_new_password, input$poweruser_confirm_password)
        req(user_id())
        
        if (nchar(input$poweruser_new_password) < 8) {
          showNotification("Passwort muss mindestens 8 Zeichen lang sein.", type = "error")
          return()
        }
        
        if (input$poweruser_new_password != input$poweruser_confirm_password) {
          showNotification("Passwörter stimmen nicht überein.", type = "error")
          return()
        }
        
        user <- DBI::dbGetQuery(
          con,
          "SELECT password_hash FROM users WHERE id = $1",
          params = list(user_id())
        )
        
        if (nrow(user) == 0 || !bcrypt::checkpw(input$poweruser_current_password, user$password_hash[1])) {
          showNotification("Aktuelles Passwort ist falsch.", type = "error")
          return()
        }
        
        new_hash <- bcrypt::hashpw(input$poweruser_new_password)
        
        DBI::dbExecute(
          con,
          "UPDATE users SET password_hash = $1, must_reset = FALSE WHERE id = $2",
          params = list(new_hash, user_id())
        )
        
        updateTextInput(session, "poweruser_current_password", value = "")
        updateTextInput(session, "poweruser_new_password", value = "")
        updateTextInput(session, "poweruser_confirm_password", value = "")
        
        showNotification("Passwort erfolgreich geändert!", type = "message")
      })
      
      # ========== STATISTICS ==========
      
      output$poweruser_stat_projects <- renderText({
        as.character(nrow(get_all_projects()))
      })
      
      output$poweruser_stat_users <- renderText({
        as.character(DBI::dbGetQuery(con, "
        SELECT COUNT(*) as count 
        FROM users 
        WHERE role NOT IN ('admin', 'power_user')
      ")$count)
      })
      
      output$poweruser_stat_assessments <- renderText({
        as.character(DBI::dbGetQuery(con, "
        SELECT COUNT(DISTINCT user_id) as count 
        FROM responses 
        WHERE submission_id IS NOT NULL
      ")$count)
      })
      
      output$poweruser_stat_codes <- renderText({
        as.character(DBI::dbGetQuery(con, "
        SELECT COUNT(*) as count 
        FROM invitation_codes 
        WHERE used_at IS NULL
      ")$count)
      })
      
      output$poweruser_progress_table <- renderDT({
        progress <- DBI::dbGetQuery(con, "
    SELECT 
      p.title as project,
      COUNT(DISTINCT u.id) as total_users,
      COUNT(DISTINCT r.user_id) as completed_users,
      ROUND(
        100.0 * COUNT(DISTINCT r.user_id) / 
        NULLIF(COUNT(DISTINCT u.id), 0),
        1
      ) as completion_rate
    FROM projects p
    LEFT JOIN users u ON u.project_id = p.id
    LEFT JOIN (
      SELECT DISTINCT user_id, project_id::integer as project_id
      FROM responses 
      WHERE submission_id IS NOT NULL
    ) r ON r.user_id = u.id AND r.project_id = p.id
    WHERE u.role NOT IN ('admin', 'power_user')
    GROUP BY p.id, p.title
    ORDER BY p.title
  ")
        
        datatable(
          progress,
          colnames = c("Projekt", "Benutzer gesamt", "Abgeschlossen", "Fortschritt (%)"),
          options = list(pageLength = 25, dom = 't'),
          rownames = FALSE
        )
      })
    
    }  
  }, once = FALSE)  
  
  
