  # show project name at the top of the Laborinformationen
  
  output$labinfo_project_display <- renderUI({
    
    req(user_logged_in())
    
    role <- user_role()
    uid <- user_id()
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    if (role == "admin") {
      # Admin can select projects
      proj_name <- current_project_name()
      
      if (!is.null(proj_name) && nzchar(proj_name)) {
        div(
          style = "margin-bottom: 20px; padding: 15px; background-color: #e8f4f8; border-left: 4px solid #003B73; border-radius: 4px;",
          div(
            style = "font-weight: bold; color: #003B73; font-size: 16px;",
            icon("folder", style = "font-size: 20px;"),
            tags$span(style = "margin-left: 10px;", "Aktuelles Projekt: ", proj_name)
          )
        )
      }
      
    } else {
      # For all other roles, get project from users table
      proj_row <- DBI::dbGetQuery(
        con,
        "SELECT p.title 
       FROM projects p 
       JOIN users u ON p.id = u.project_id 
       WHERE u.id = $1",
        params = list(uid)
      )
      
      if (nrow(proj_row) > 0 && nzchar(proj_row$title[1])) {
        div(
          style = "margin-bottom: 20px; padding: 15px; background-color: #e8f4f8; border-left: 4px solid #003B73; border-radius: 4px;",
          div(
            style = "font-weight: bold; color: #003B73; font-size: 16px;",
            icon("folder", style = "font-size: 20px;"),
            tags$span(style = "margin-left: 10px;", "Ihr Projekt: ", proj_row$title[1])
          ),
          tags$hr(style = "border-color: #003B73; opacity: 0.3; margin: 10px 0;"),
          tags$small(
            style = "color: #666;",
            icon("info-circle"),
            " Füllen Sie unten die Informationen zur besuchten Einrichtung aus."
          )
        )
      } else {
        div(
          style = "margin-bottom: 20px; padding: 15px; background-color: #f8d7da; border-left: 4px solid #d9534f; border-radius: 4px;",
          icon("exclamation-triangle", style = "color: #d9534f;"),
          tags$span(
            style = "margin-left: 10px; color: #721c24; font-weight: bold;",
            "Kein Projekt zugewiesen. Bitte kontaktieren Sie den Administrator."
          )
        )
      }
    }
  })
  
  
  #----------------------load draft of answers------------------------------------
  draft_loaded_once <- reactiveVal(FALSE)
  
  observeEvent(user_logged_in(), {
    if (!isTRUE(user_logged_in())) return()
    draft_loaded_once(FALSE)   # reset on login
  }, ignoreInit = TRUE)
  
  
  
  # ============================================
  # MASTER TAB CHANGE HANDLER (ALL TAB LOGIC HERE)
  # ============================================
  
  observeEvent(input$sidebar_menu, {
    
    current_tab <- input$sidebar_menu
    previous_tab <- last_tab()
    
    message("\n========== TAB CHANGED ==========")
    message("New tab: ", current_tab)
    message("Previous tab: ", ifelse(is.null(previous_tab), "NULL", previous_tab))
    message("User logged in: ", user_logged_in())
    message("Draft loaded: ", draft_loaded())
    message("================================\n")
    
    # ============================================
    # 1. HANDLE LOGOUT
    # ============================================
    
    if (current_tab == "logout") {
      message("→ Logout triggered")
      do_logout()
      return()
    }
    
    # ============================================
    # 2. LEAVING FRAGEBOGEN TAB - RESET DRAFT FLAG
    # ============================================
    
    if (!is.null(previous_tab) && 
        previous_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire") &&
        !current_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire")) {
      
      message("→ Leaving fragebogen tab, resetting draft flag")
      draft_loaded(FALSE)
    }
    
    # ============================================
    # 3. ENTERING FRAGEBOGEN TAB - LOAD DRAFT
    # ============================================
    
    if (current_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire")) {
      
      message("→ Fragebogen tab activated")
      
      if (user_logged_in() && !draft_loaded()) {
        message("→ Starting draft load process...")
        
        shinyjs::delay(1000, {
          attempt_draft_load(retry_count = 0, max_retries = 5)
        })
      } else {
        message("→ Skipping draft load (already loaded or not logged in)")
      }
    }
    
    # ============================================
    # 3.5. LAB INFO TAB - AUTO-LOAD SAVED DATA
    # ============================================
    
    if (current_tab == "fill_labinfo") {
      
      message("→ Lab Info tab activated")
      
      if (!user_logged_in()) {
        message("→ User not logged in, skipping lab info load")
      } else {
        
        project_id <- current_project_id()
        
        if (is.null(project_id) || project_id == "") {
          message("→ No project ID, skipping lab info load")
        } else {
          
          message("→ Scheduling lab info load in 500ms...")
          
          # ✅ Add delay to let UI render
          shinyjs::delay(500, {
            
            message("→ Loading lab info for project ", project_id)
            
            tryCatch({
              
              con <- get_db_con()
              on.exit(DBI::dbDisconnect(con), add = TRUE)
              
              labinfo <- DBI::dbGetQuery(
                con,
                "SELECT * FROM lab_info WHERE project_id = $1",
                params = list(as.integer(project_id))
              )
              
              message("→ Database returned ", nrow(labinfo), " rows")
              
              if (nrow(labinfo) > 0) {
                
                message("→ Found saved data, loading fields...")
                
                # Helper functions
                safe_update <- function(input_id, value) {
                  if (!is.null(value) && !is.na(value) && nchar(as.character(value)) > 0) {
                    updateTextInput(session, input_id, value = as.character(value))
                    message("  ✓ ", input_id)
                  }
                }
                
                safe_update_textarea <- function(input_id, value) {
                  if (!is.null(value) && !is.na(value) && nchar(as.character(value)) > 0) {
                    updateTextAreaInput(session, input_id, value = as.character(value))
                    message("  ✓ ", input_id)
                  }
                }
                
                safe_update_numeric <- function(input_id, value) {
                  if (!is.null(value) && !is.na(value)) {
                    updateNumericInput(session, input_id, value = as.integer(value))
                    message("  ✓ ", input_id)
                  }
                }
                
                safe_update_radio <- function(input_id, value) {
                  if (!is.null(value) && !is.na(value) && nchar(as.character(value)) > 0) {
                    updateRadioButtons(session, input_id, selected = as.character(value))
                    message("  ✓ ", input_id)
                  }
                }
                
                safe_update_checkbox <- function(input_id, value) {
                  if (!is.null(value) && !is.na(value) && nchar(as.character(value)) > 0) {
                    vals <- strsplit(as.character(value), ", ")[[1]]
                    updateCheckboxGroupInput(session, input_id, selected = vals)
                    message("  ✓ ", input_id)
                  }
                }
                
                # Load all fields
                safe_update("name", labinfo$name[1])
                safe_update("Internetadresse", labinfo$internetadresse[1])
                safe_update("Trag", labinfo$trag[1])
                safe_update("Zug", labinfo$zug[1])
                safe_update("Ansprechpartner", labinfo$ansprechpartner[1])
                safe_update("Email", labinfo$email[1])
                safe_update("Telefonnummer", labinfo$telefonnummer[1])
                safe_update("Öffnungzeiten", labinfo$oeffnungzeiten[1])
                
                safe_update_checkbox("versorgung", labinfo$versorgung[1])
                safe_update("sonstiges_versorgung", labinfo$sonstiges_versorgung[1])
                safe_update_checkbox("laborbereiche", labinfo$laborbereiche[1])
                safe_update("sonstiges_laborbereiche", labinfo$sonstiges_laborbereiche[1])
                safe_update_checkbox("leistungsspektrum", labinfo$leistungsspektrum[1])
                safe_update("sonstiges_leistungsspektrum", labinfo$sonstiges_leistungsspektrum[1])
                safe_update("ausstattung", labinfo$ausstattung[1])
                safe_update("hauptlieferanten", labinfo$hauptlieferanten[1])
                safe_update_radio("question_binary_1", labinfo$question_binary_1[1])
                safe_update("farbcodesystem", labinfo$farbcodesystem[1])
                safe_update_radio("question_binary_2", labinfo$question_binary_2[1])
                safe_update("auftragsgenerierung", labinfo$auftragsgenerierung[1])
                safe_update("präanalytik", labinfo$praeanalytik[1])
                safe_update("befundübermittlung", labinfo$befunduebermittlung[1])
                safe_update("beratungsleistungen", labinfo$beratungsleistungen[1])
                safe_update_radio("question_binary_3", labinfo$question_binary_3[1])
                
                safe_update_numeric("Anzahl_total", labinfo$anzahl_total[1])
                safe_update_numeric("Anzahl_mit", labinfo$anzahl_mit[1])
                safe_update_numeric("davon_Fachaerzte", labinfo$davon_fachaerzte[1])
                safe_update_numeric("davon_weiterbildung", labinfo$davon_weiterbildung[1])
                safe_update_numeric("Anzahl_Planstellen", labinfo$anzahl_planstellen[1])
                safe_update_numeric("davon_unbesetzt", labinfo$davon_unbesetzt[1])
                safe_update_numeric("Anzahl_tech", labinfo$anzahl_tech[1])
                safe_update_numeric("Anzahl_TPlanstellen", labinfo$anzahl_tplanstellen[1])
                safe_update_numeric("davon_Tunbesetzt", labinfo$davon_tunbesetzt[1])
                safe_update_numeric("Anzahl_natur", labinfo$anzahl_natur[1])
                safe_update_numeric("Anzahl_NPlanstellen", labinfo$anzahl_nplanstellen[1])
                safe_update_numeric("davon_Nunbesetzt", labinfo$davon_nunbesetzt[1])
                safe_update_numeric("Anzahl_IT", labinfo$anzahl_it[1])
                safe_update_numeric("Anzahl_IPlanstellen", labinfo$anzahl_iplanstellen[1])
                safe_update_numeric("davon_Iunbesetzt", labinfo$davon_iunbesetzt[1])
                
                safe_update_textarea("Beschreibung", labinfo$beschreibung_it[1])
                safe_update_textarea("WeitereInfo", labinfo$weitereinfo_personal[1])
                
                safe_update("AnbieterInfo", labinfo$anbieterinfo[1])
                safe_update("AnbieterOrder", labinfo$anbieterorder[1])
                safe_update("AnbieterMiddleware", labinfo$anbietermiddleware[1])
                safe_update("WeitereIT", labinfo$weitereit[1])
                
                safe_update("laufendenJahres", labinfo$laufendenjahres[1])
                safe_update("Vorjahres", labinfo$vorjahres[1])
                safe_update("Kompetenzschwerpunkte", labinfo$kompetenzschwerpunkte[1])
                safe_update("Ergänzung", labinfo$ergaenzung[1])
                
                message("→ ✓✓✓ Lab info loaded successfully!")
                
                showNotification("Gespeicherte Labordaten geladen!", type = "message", duration = 2)
                
              } else {
                message("→ No saved lab info found")
              }
              
            }, error = function(e) {
              message("→ ERROR loading lab info: ", e$message)
            })
            
          })  # End delay
        }
      }
    }
    
    # ============================================
    # 4. ADMIN TABS - REFRESH DROPDOWNS
    # ============================================
    
    if (user_logged_in() && user_role() == "admin") {
      
      if (current_tab == "admin_invitations") {
        message("→ Admin invitations tab - refreshing projects")
        project_data_changed(project_data_changed() + 1)
      }
      
      if (current_tab == "admin_user_export") {
        message("→ User export tab - refreshing users")
        responses_data_changed(responses_data_changed() + 1)
      }
      
      if (current_tab == "labor_leiter_summary") {
        message("→ Summary tab - refreshing data")
        project_data_changed(project_data_changed() + 1)
        responses_data_changed(responses_data_changed() + 1)
      }
      
      if (current_tab == "dashboard") {
        message("→ Dashboard tab - refreshing all data")
        project_data_changed(project_data_changed() + 1)
        responses_data_changed(responses_data_changed() + 1)
      }
    }
    
    # ============================================
    # 5. UPDATE LAST TAB TRACKER
    # ============================================
    
    last_tab(current_tab)
    
  }, ignoreInit = TRUE)

  
  
  # ==========================================
  # RESET DRAFT FLAG WHEN LEAVING FRAGEBOGEN
  # ==========================================
  
  last_tab <- reactiveVal(NULL)
  
  observeEvent(input$sidebar_menu, {
    
    current_tab <- input$sidebar_menu
    previous_tab <- last_tab()
    
    message("Tab changed from '", previous_tab, "' to '", current_tab, "'")
    
    # If leaving fragebogen tab, reset draft flag
    if (!is.null(previous_tab) && 
        previous_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire") &&
        !current_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire")) {
      
      message("→ Leaving fragebogen tab, resetting draft flag")
      draft_loaded(FALSE)
    }
    
    # Update last tab
    last_tab(current_tab)
    
    # Load draft if entering fragebogen
    if (current_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire")) {
      
      if (user_logged_in() && !draft_loaded()) {
        message("→ Entering fragebogen tab, loading draft...")
        
        shinyjs::delay(1000, {
          attempt_draft_load(retry_count = 0, max_retries = 5)
        })
      }
    }
  })
  
  
  observe({
    req(input$antworten_project_selector)
    if (!is.null(input$antworten_project_selector) && input$antworten_project_selector != "") {
      shinyjs::enable("downloadZusammenfassung")
    } else {
      shinyjs::disable("downloadZusammenfassung")
    }
  })
  
  
  #--------------Helper: Get Question-Level Statistics for PDF-------------------
  
  get_question_level_statistics <- function(project_id, questions_list, section_name) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions_list, function(q) q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      r.response_value as rating,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)) as count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value != ''
      AND r.response_value != 'N/A'
    GROUP BY r.question_id, r.response_value
    ORDER BY r.question_id, r.response_value
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    # Create full data with question labels
    full_data <- data.frame(
      Section = section_name,
      question_id = qids,
      Frage = sapply(questions_list, function(q) q$label),
      stringsAsFactors = FALSE
    )
    
    # Format statistics as readable text
    if (nrow(result) > 0) {
      stats_by_question <- split(result, result$question_id)
      
      full_data$Statistik <- sapply(full_data$question_id, function(qid) {
        stats <- stats_by_question[[qid]]
        if (!is.null(stats) && nrow(stats) > 0) {
          parts <- sapply(1:nrow(stats), function(i) {
            # ✅ FIX: Use %.0f instead of %d
            sprintf("Bewertung %s: %.0f Personen", stats$rating[i], as.numeric(stats$count[i]))
          })
          paste(parts, collapse = ", ")
        } else {
          "—"
        }
      })
    } else {
      full_data$Statistik <- "—"
    }
    
    return(full_data[, c("Section", "question_id", "Frage", "Statistik")])
  }
  
  #--------------Helper: Get Berufsgruppe Averages for PDF----------------------
  
  get_berufsgruppe_averages <- function(project_id, questions_list, section_name) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions_list, function(q) q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben') as berufsgruppe,
      ROUND(
        SUM(CAST(r.response_value AS NUMERIC) * COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)) / 
        SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)),
        1
      ) as avg_rating,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)) as group_count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value != ''
      AND r.response_value != 'N/A'
      AND r.response_value ~ '^[0-9]+$'
    GROUP BY r.question_id, COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben')
    ORDER BY r.question_id, berufsgruppe
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    # Create full data
    full_data <- data.frame(
      Section = section_name,
      question_id = qids,
      Frage = sapply(questions_list, function(q) q$label),
      stringsAsFactors = FALSE
    )
    
    # Format group averages
    if (nrow(result) > 0) {
      groups_by_question <- split(result, result$question_id)
      
      full_data$Berufsgruppen <- sapply(full_data$question_id, function(qid) {
        groups <- groups_by_question[[qid]]
        if (!is.null(groups) && nrow(groups) > 0) {
          parts <- sapply(1:nrow(groups), function(i) {
            # ✅ FIX: Use %.0f instead of %d
            sprintf("%s: Ø %.1f (n=%.0f)", groups$berufsgruppe[i], as.numeric(groups$avg_rating[i]), as.numeric(groups$group_count[i]))
          })
          paste(parts, collapse = "; ")
        } else {
          "—"
        }
      })
    } else {
      full_data$Berufsgruppen <- "—"
    }
    
    return(full_data[, c("Section", "question_id", "Frage", "Berufsgruppen")])
  }
  
  
  #--------------Helper: Get Selbstbewertung Text Responses for PDF-----------
  
  get_selbstbewertung_text_responses <- function(project_id, questions_list, section_name) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions_list, function(q) q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      r.text_value,
      COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.text_value != ''
      AND r.text_value IS NOT NULL
    ORDER BY r.question_id, r.text_value
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    # Create full data with question labels
    full_data <- data.frame(
      Section = section_name,
      question_id = qids,
      Frage = sapply(questions_list, function(q) q$label),
      stringsAsFactors = FALSE
    )
    
    # Aggregate texts by question (with count)
    if (nrow(result) > 0) {
      texts_by_question <- split(result, result$question_id)
      
      full_data$Textantworten <- sapply(full_data$question_id, function(qid) {
        texts <- texts_by_question[[qid]]
        if (!is.null(texts) && nrow(texts) > 0) {
          # Aggregate identical texts
          text_agg <- aggregate(group_size ~ text_value, data = texts, FUN = sum)
          
          parts <- sapply(1:nrow(text_agg), function(i) {
            count <- as.numeric(text_agg$group_size[i])
            if (count > 1) {
              sprintf("• %s (×%.0f)", text_agg$text_value[i], count)
            } else {
              sprintf("• %s", text_agg$text_value[i])
            }
          })
          paste(parts, collapse = ";")
        } else {
          "—"
        }
      })
    } else {
      full_data$Textantworten <- "—"
    }
    
    return(full_data[, c("Section", "question_id", "Frage", "Textantworten")])
  }
  
  #-------------------------- SPIDER PLOTS - All Topics----------------------------
  
  
  get_weighted_spider_data_local <- function(project_id, topic_key, questionnaires, binary_qnums = integer()) {
    message(">>> get_weighted_spider_data_local called")
    message("    project_id: ", project_id)
    message("    topic_key: ", topic_key)
    
    question_list <- questionnaires[[topic_key]]
    
    if (is.null(question_list)) {
      message("    ERROR: No question list for topic: ", topic_key)
      return(NULL)
    }
    
    message("    Questions found: ", length(question_list))
    
    # Filter binary questions
    if (length(binary_qnums) > 0) {
      question_list <- Filter(function(q) !(q$number %in% binary_qnums), question_list)
      message("    After binary filter: ", length(question_list))
    }
    
    if (length(question_list) == 0) {
      message("    No questions after filtering")
      return(NULL)
    }
    
    question_ids <- sapply(question_list, function(q) q$id)
    message("    Question IDs: ", paste(question_ids, collapse = ", "))
    
    # Get responses
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    sql <- sprintf(
      "SELECT user_id, question_id, response_value::numeric, group_size
     FROM responses
     WHERE project_id = $1
       AND assessment_type = 'selbstbewertung'
       AND question_id IN (%s)
       AND response_value IS NOT NULL
       AND response_value != ''",
      paste0("'", question_ids, "'", collapse = ", ")
    )
    
    message("    Executing query...")
    responses <- DBI::dbGetQuery(con, sql, params = list(project_id))
    message("    Raw responses: ", nrow(responses))
    
    if (nrow(responses) == 0) {
      message("    No responses found")
      return(NULL)
    }
    
    # Expand by group size
    message("    Expanding by group_size...")
    expanded_list <- lapply(1:nrow(responses), function(i) {
      row <- responses[i, ]
      gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
      
      data.frame(
        user_id = rep(row$user_id, gs),
        question_id = rep(row$question_id, gs),
        response_value = rep(as.numeric(row$response_value), gs)
      )
    })
    
    expanded <- do.call(rbind, expanded_list)
    message("    Expanded to: ", nrow(expanded), " rows")
    
    # Calculate means
    means <- expanded %>%
      group_by(question_id) %>%
      summarise(mean_value = mean(response_value, na.rm = TRUE), .groups = "drop")
    
    message("    Means calculated for ", nrow(means), " questions")
    
    # Map to question order
    values <- sapply(question_list, function(q) {
      row <- means[means$question_id == q$id, ]
      if (nrow(row) > 0) row$mean_value else 0
    })
    
    labels <- sapply(question_list, function(q) as.character(q$number))
    
    message("    Values: ", paste(round(values, 2), collapse = ", "))
    message("    Labels: ", paste(labels, collapse = ", "))
    message(">>> get_weighted_spider_data_local END")
    
    return(list(values = values, labels = labels))
  }
  
