  #--------------LEADING PEER DASHBOARD - CONTENT GENERATION------------------
  
  # Helper to calculate WEIGHTED stats

  calc_weighted_stats <- function(df, questions_list, project_id) {
    
    message("\n→ calc_weighted_stats called")
    message("  df rows: ", nrow(df))
    message("  questions: ", length(questions_list))
    message("  project_id: ", project_id)
    
    # ✅ Validate inputs
    if (is.null(df) || nrow(df) == 0) {
      message("  ❌ Empty dataframe, returning empty stats")
      return(list())
    }
    
    if (is.null(project_id) || project_id == "" || is.na(project_id)) {
      message("  ❌ Invalid project_id, returning empty stats")
      return(list())
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    stats <- list()
    
    for (q in questions_list) {
      qid <- q$id
      
      # ✅ Wrap query in tryCatch
      values_df <- tryCatch({
        
        query <- "
        SELECT 
          r.response_value,
          CAST(qd.answers::json->>'group_size' AS INTEGER) as group_size
        FROM responses r
        JOIN users u ON u.id = r.user_id
        LEFT JOIN questionnaire_drafts qd 
          ON u.id::text = qd.user_id::text 
          AND qd.project_id::text = r.project_id::text
          AND qd.questionnaire_id = 'peer_review'
        WHERE r.project_id::text = $1::text
          AND r.assessment_type = 'selbstbewertung'
          AND r.question_id = $2
          AND r.response_value != '' 
          AND r.response_value != 'N/A'
      "
        
        DBI::dbGetQuery(con, query, params = list(as.character(project_id), qid))
        
      }, error = function(e) {
        message("    ❌ Error for question ", qid, ": ", e$message)
        return(data.frame())
      })
      
      if (nrow(values_df) > 0) {
        
        # Convert to numeric
        values_df$response_numeric <- suppressWarnings(as.numeric(values_df$response_value))
        values_df <- values_df[!is.na(values_df$response_numeric), ]
        
        # Default group_size to 1 if missing
        values_df$group_size[is.na(values_df$group_size)] <- 1
        
        if (nrow(values_df) > 0) {
          # Calculate weighted mean
          weighted_sum <- sum(values_df$response_numeric * values_df$group_size, na.rm = TRUE)
          total_people <- sum(values_df$group_size, na.rm = TRUE)
          
          if (total_people > 0) {
            weighted_mean <- weighted_sum / total_people
            
            stats[[qid]] <- list(
              mean = weighted_mean,
              n = total_people,
              n_users = nrow(values_df)
            )
          }
        }
      }
    }
    
    message("  ✓ Stats calculated for ", length(stats), " questions")
    
    return(stats)
  }
  
  
  #--------------Binary Questions Bar Plot (Ja/Nein)----------------------------
  
  create_binary_bar_plot <- function(project_id, binary_qids, question_labels) {
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids_quoted <- paste0("'", binary_qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben') as berufsgruppe,
      r.response_value,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1))::integer as count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value IN ('Ja', 'Nein')
    GROUP BY r.question_id, berufsgruppe, r.response_value
    ORDER BY r.question_id, berufsgruppe, r.response_value
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    if (nrow(result) == 0) {
      return(
        plotly::plot_ly() %>%
          plotly::layout(
            title = "Keine Daten für dichotome Fragen vorhanden",
            xaxis = list(title = ""),
            yaxis = list(title = "")
          )
      )
    }
    
    # Map question IDs to labels
    result$question_label <- sapply(result$question_id, function(qid) {
      idx <- which(names(question_labels) == qid)
      if (length(idx) > 0) {
        paste0(qid, ": ", question_labels[[qid]])
      } else {
        qid
      }
    })
    
    # Create grouped bar chart
    library(plotly)
    
    # Separate Ja and Nein data
    ja_data <- result[result$response_value == "Ja", ]
    nein_data <- result[result$response_value == "Nein", ]
    
    # Create plot
    p <- plot_ly()
    
    # Add Ja bars
    if (nrow(ja_data) > 0) {
      p <- p %>% add_trace(
        data = ja_data,
        x = ~question_label,
        y = ~count,
        color = ~berufsgruppe,
        type = 'bar',
        name = ~berufsgruppe,
        legendgroup = ~berufsgruppe,
        text = ~paste0("Ja: ", count),
        hovertemplate = paste0(
          "<b>%{x}</b><br>",
          "%{data.name}<br>",
          "Ja: %{y}<br>",
          "<extra></extra>"
        ),
        marker = list(
          pattern = list(shape = "")  # Solid for Ja
        )
      )
    }
    
    # Add Nein bars
    if (nrow(nein_data) > 0) {
      p <- p %>% add_trace(
        data = nein_data,
        x = ~question_label,
        y = ~-count,  # Negative for stacked effect
        color = ~berufsgruppe,
        type = 'bar',
        name = ~berufsgruppe,
        legendgroup = ~berufsgruppe,
        showlegend = FALSE,
        text = ~paste0("Nein: ", count),
        hovertemplate = paste0(
          "<b>%{x}</b><br>",
          "%{data.name}<br>",
          "Nein: %{text}<br>",
          "<extra></extra>"
        ),
        marker = list(
          pattern = list(shape = "/")  # Hatched for Nein
        )
      )
    }
    
    p <- p %>% layout(
      title = "Dichotome Fragen - Ja/Nein Verteilung nach Berufsgruppe",
      xaxis = list(
        title = "Fragen",
        tickangle = -45
      ),
      yaxis = list(
        title = "Anzahl Personen",
        zeroline = TRUE
      ),
      barmode = 'relative',
      legend = list(
        title = list(text = "Berufsgruppe")
      ),
      hovermode = "closest"
    )
    
    return(p)
  }
  
  
  #--------------Binary Questions Bar Plot (Side-by-Side)----------------------------
  
  create_binary_bar_plot_sidebyside <- function(project_id, binary_qids, question_labels) {
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids_quoted <- paste0("'", binary_qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben') as berufsgruppe,
      r.response_value,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1))::integer as count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value IN ('Ja', 'Nein')
    GROUP BY r.question_id, berufsgruppe, r.response_value
    ORDER BY r.question_id, berufsgruppe, r.response_value
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    if (nrow(result) == 0) {
      return(
        plotly::plot_ly() %>%
          plotly::layout(title = "Keine Daten vorhanden")
      )
    }
    
    # Add question labels
    result$question_label <- sapply(result$question_id, function(qid) {
      idx <- which(names(question_labels) == qid)
      if (length(idx) > 0) {
        paste0(qid, ": ", substr(question_labels[[qid]], 1, 30), "...")
      } else {
        qid
      }
    })
    
    # Create combined label
    result$x_label <- paste0(result$question_label, " - ", result$response_value)
    
    # Color palette for Berufsgruppen
    colors <- c(
      "Ärzte" = "#1976D2",
      "MTL" = "#FF9800",
      "nicht anwendbar" = "#4CAF50"
    )
    
    library(plotly)
    
    p <- plot_ly(
      data = result,
      x = ~x_label,
      y = ~count,
      color = ~berufsgruppe,
      colors = colors,
      type = 'bar',
      text = ~count,
      textposition = 'outside',
      hovertemplate = paste0(
        "<b>%{x}</b><br>",
        "Berufsgruppe: %{data.name}<br>",
        "Anzahl: %{y}<br>",
        "<extra></extra>"
      )
    ) %>%
      layout(
        title = "Dichotome Fragen (M10, M20, M24) - Ja/Nein Verteilung",
        xaxis = list(
          title = "",
          tickangle = -45
        ),
        yaxis = list(
          title = "Anzahl Personen"
        ),
        barmode = 'group',
        legend = list(
          title = list(text = "Berufsgruppe")
        ),
        margin = list(b = 150)  # Extra space for rotated labels
      )
    
    return(p)
  }
  
  #--------------Create Binary Questions Table (Simple Counts Only)----------------------------
  
  create_binary_table_simple <- function(project_id, binary_questions) {
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    binary_qids <- sapply(binary_questions, function(q) q$id)
    qids_quoted <- paste0("'", binary_qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben') as berufsgruppe,
      r.response_value,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1))::integer as count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value IN ('Ja', 'Nein')
    GROUP BY r.question_id, berufsgruppe, r.response_value
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    if (nrow(result) == 0) {
      return(tags$p("Keine Daten vorhanden."))
    }
    
    berufsgruppen <- unique(result$berufsgruppe)
    all_rows <- list()
    
    for (q in binary_questions) {
      qid <- q$id
      q_label <- q$label
      q_data <- result[result$question_id == qid, ]
      
      if (nrow(q_data) == 0) next
      
      # Question header
      all_rows[[length(all_rows) + 1]] <- tags$tr(
        tags$td(
          colspan = 4,
          style = "background: #003B73; color: white; font-weight: 600; padding: 10px;",
          paste0(qid, ": ", q_label)
        )
      )
      
      # Rows per Berufsgruppe
      for (bg in berufsgruppen) {
        bg_data <- q_data[q_data$berufsgruppe == bg, ]
        
        ja_count <- sum(bg_data$count[bg_data$response_value == "Ja"], na.rm = TRUE)
        nein_count <- sum(bg_data$count[bg_data$response_value == "Nein"], na.rm = TRUE)
        total <- ja_count + nein_count
        
        all_rows[[length(all_rows) + 1]] <- tags$tr(
          tags$td(style = "padding-left: 30px; color: #555;", bg),
          tags$td(
            style = "text-align: center; color: #27AE60; font-weight: 500;",
            ja_count
          ),
          tags$td(
            style = "text-align: center; color: #E74C3C; font-weight: 500;",
            nein_count
          ),
          tags$td(
            style = "text-align: center; font-weight: 600;",
            total
          )
        )
      }
      
      # Total row
      total_ja <- sum(q_data$count[q_data$response_value == "Ja"], na.rm = TRUE)
      total_nein <- sum(q_data$count[q_data$response_value == "Nein"], na.rm = TRUE)
      total_all <- total_ja + total_nein
      
      all_rows[[length(all_rows) + 1]] <- tags$tr(
        class = "binary-total-row",
        tags$td(
          style = "padding-left: 30px; font-weight: 600; background: #f8f9fa;",
          "Gesamt"
        ),
        tags$td(
          style = "text-align: center; font-weight: 600; background: #f8f9fa; color: #27AE60;",
          total_ja
        ),
        tags$td(
          style = "text-align: center; font-weight: 600; background: #f8f9fa; color: #E74C3C;",
          total_nein
        ),
        tags$td(
          style = "text-align: center; font-weight: 600; background: #f8f9fa;",
          total_all
        )
      )
      
      # Spacer row
      all_rows[[length(all_rows) + 1]] <- tags$tr(
        tags$td(colspan = 4, style = "height: 10px; background: white;")
      )
    }
    
    tags$div(
      class = "berufsgruppe-stats",
      tags$h4("Dichotome Fragen"),
      tags$div(
        style = "overflow-x: auto;",
        tags$table(
          class = "stats-detail-table",
          style = "width: 100%; border-collapse: collapse;",
          tags$thead(
            tags$tr(
              tags$th(style = "text-align: left; width: 40%;", "Berufsgruppe"),
              tags$th(style = "text-align: center; width: 20%; color: #27AE60;", "Ja"),
              tags$th(style = "text-align: center; width: 20%; color: #E74C3C;", "Nein"),
              tags$th(style = "text-align: center; width: 20%;", "Gesamt")
            )
          ),
          tags$tbody(all_rows)
        )
      )
    )
  }
  
  create_binary_table_compact <- function(project_id, binary_questions) {
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    binary_qids <- sapply(binary_questions, function(q) q$id)
    
    if (length(binary_qids) == 0) {
      return(tags$p("Keine dichotomen Fragen vorhanden."))
    }
    
    qids_quoted <- paste0("'", binary_qids, "'", collapse = ", ")
    
    query <- sprintf("
    SELECT 
      r.question_id,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben') as berufsgruppe,
      r.response_value,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1))::integer as count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd 
      ON u.id::text = qd.user_id::text 
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value IN ('Ja', 'Nein')
    GROUP BY r.question_id, berufsgruppe, r.response_value
  ", as.character(project_id), qids_quoted)
    
    result <- DBI::dbGetQuery(con, query)
    
    if (nrow(result) == 0) {
      return(tags$p("Keine Daten vorhanden."))
    }
    
    berufsgruppen <- unique(result$berufsgruppe)
    
    # ✅ FIXED: Build header with question numbers
    question_headers <- lapply(binary_questions, function(q) {
      # Shorten label if too long
      short_label <- if (nchar(q$label) > 45) {
        paste0(substr(q$label, 1, 45), "...")
      } else {
        q$label
      }
      
      tags$th(
        colspan = 3,
        style = "text-align: center; border-left: 2px solid #ccc; padding: 8px; font-size: 11px; cursor: help;",
        title = paste0(q$number, ". ", q$label),  # Full text on hover
        paste0(q$number, ". ", short_label)  # ✅ Use q$number
      )
    })
    
    # Sub-header for Ja/Nein/Gesamt
    sub_headers <- lapply(1:length(binary_questions), function(i) {
      list(
        tags$th(style = "text-align: center; color: #27AE60; font-size: 10px; border-left: 2px solid #ccc;", "Ja"),
        tags$th(style = "text-align: center; color: #E74C3C; font-size: 10px;", "Nein"),
        tags$th(style = "text-align: center; font-size: 10px;", "Σ")
      )
    })
    
    header_row <- tags$tr(
      tags$th(rowspan = 2, style = "text-align: left;", "Berufsgruppe"),
      question_headers
    )
    
    subheader_row <- tags$tr(
      unlist(sub_headers, recursive = FALSE)
    )
    
    # Data rows
    data_rows <- lapply(berufsgruppen, function(bg) {
      
      row_cells <- list(tags$td(style = "font-weight: 500;", bg))
      
      for (q in binary_questions) {
        qid <- q$id
        q_data <- result[result$question_id == qid & result$berufsgruppe == bg, ]
        
        ja_count <- sum(q_data$count[q_data$response_value == "Ja"], na.rm = TRUE)
        nein_count <- sum(q_data$count[q_data$response_value == "Nein"], na.rm = TRUE)
        total <- ja_count + nein_count
        
        row_cells[[length(row_cells) + 1]] <- tags$td(
          style = "text-align: center; color: #27AE60; border-left: 2px solid #f0f0f0;",
          ja_count
        )
        row_cells[[length(row_cells) + 1]] <- tags$td(
          style = "text-align: center; color: #E74C3C;",
          nein_count
        )
        row_cells[[length(row_cells) + 1]] <- tags$td(
          style = "text-align: center; font-weight: 500;",
          total
        )
      }
      
      tags$tr(row_cells)
    })
    
    # Total row
    total_cells <- list(tags$td(style = "font-weight: 600; background: #f8f9fa;", "Gesamt"))
    
    for (q in binary_questions) {
      qid <- q$id
      q_data <- result[result$question_id == qid, ]
      
      total_ja <- sum(q_data$count[q_data$response_value == "Ja"], na.rm = TRUE)
      total_nein <- sum(q_data$count[q_data$response_value == "Nein"], na.rm = TRUE)
      total_all <- total_ja + total_nein
      
      total_cells[[length(total_cells) + 1]] <- tags$td(
        style = "text-align: center; font-weight: 600; background: #f8f9fa; color: #27AE60; border-left: 2px solid #e0e0e0;",
        total_ja
      )
      total_cells[[length(total_cells) + 1]] <- tags$td(
        style = "text-align: center; font-weight: 600; background: #f8f9fa; color: #E74C3C;",
        total_nein
      )
      total_cells[[length(total_cells) + 1]] <- tags$td(
        style = "text-align: center; font-weight: 600; background: #f8f9fa;",
        total_all
      )
    }
    
    total_row <- tags$tr(class = "binary-total-row", total_cells)
    
    # Build table
    tags$div(
      class = "berufsgruppe-stats",
      tags$h4("Dichotome Fragen - Qualitative Ergebnisse (Ja/Nein)"),
      tags$div(
        style = "overflow-x: auto;",
        tags$table(
          class = "stats-detail-table",
          style = "width: 100%; border-collapse: collapse; font-size: 12px;",
          tags$thead(
            header_row,
            subheader_row
          ),
          tags$tbody(
            data_rows,
            total_row
          )
        )
      )
    )
  }
  #-------------------Create Berufsgruppe Statistics Table--------------------
  
  #--- Create Complete Berufsgruppe Statistics Table (Per-Question + Average)
  
  create_berufsgruppe_stats_table_complete <- function(project_id, questions_list) {
    # Define binary question numbers for Mitarbeiter
    binary_qnums <- c(10, 20, 24)
    
    # Filter out binary questions from questions_list for statistics
    questions_filtered <- Filter(function(q) !(q$number %in% binary_qnums), questions_list)
    
    # Get the weighted data (only for non-binary questions)
    data <- get_berufsgruppe_radar_data_weighted(project_id, questions_filtered, integer())
    
    if (is.null(data) || nrow(data) == 0) {
      return(NULL)
    }
    
    # Get breakdown for participant counts
    berufsgruppe_breakdown <- get_berufsgruppe_breakdown(project_id)
    
    # Separate Berufsgruppe column
    berufsgruppen <- data$berufsgruppe
    numeric_data <- data[, -1, drop = FALSE]
    
    # Calculate topic averages
    topic_averages <- rowMeans(numeric_data, na.rm = TRUE)
    
    # Extract question numbers (only non-binary)
    question_numbers <- sapply(questions_filtered, function(q) as.character(q$number))
    
    # Create table header
    header_row <- tags$tr(
      tags$th(rowspan = 2, "Berufsgruppe"),
      tags$th(rowspan = 2, "n"),
      tags$th(colspan = length(question_numbers), style = "text-align: center; border-bottom: 1px solid #00508f;", 
              "Durchschnitt pro Frage"),
      tags$th(rowspan = 2, HTML("Ø Thema<br/>(x&#772;<sub>w</sub>)"))
    )
    
    # Question number sub-header
    question_header_row <- tags$tr(
      lapply(question_numbers, function(qnum) {
        tags$th(style = "text-align: center; font-size: 11px; padding: 4px 6px;", qnum)
      })
    )
    
    # Create data rows
    data_rows <- lapply(1:length(berufsgruppen), function(i) {
      bg <- berufsgruppen[i]
      
      # Get n_people from breakdown
      n_people <- if (nrow(berufsgruppe_breakdown) > 0) {
        idx <- which(berufsgruppe_breakdown$berufsgruppe == bg)
        if (length(idx) > 0) berufsgruppe_breakdown$n_people[idx] else 0
      } else {
        0
      }
      
      tags$tr(
        tags$td(class = "stats-label", bg),
        tags$td(class = "stats-n", style = "text-align: center; color: #1976D2; font-weight: 500;", n_people),
        lapply(1:ncol(numeric_data), function(j) {
          val <- numeric_data[i, j]
          tags$td(
            class = "stats-question-value",
            style = "text-align: center; font-size: 12px; color: #555;",
            if (!is.na(val)) sprintf("%.2f", val) else "—"
          )
        }),
        tags$td(
          class = "stats-topic-avg",
          style = "text-align: center; color: #1976D2; font-weight: 600; font-size: 13px; background: #f0f7ff;",
          sprintf("%.2f", topic_averages[i])
        )
      )
    })
    
    # Overall totals row
    total_people <- sum(berufsgruppe_breakdown$n_people, na.rm = TRUE)
    overall_topic_avg <- mean(topic_averages, na.rm = TRUE)
    
    # Calculate overall average per question
    overall_question_avgs <- colMeans(numeric_data, na.rm = TRUE)
    
    total_row <- tags$tr(
      class = "stats-total",
      tags$td(tags$strong("Gesamt")),
      tags$td(style = "text-align: center; font-weight: 600;", tags$strong(total_people)),
      lapply(overall_question_avgs, function(val) {
        tags$td(
          style = "text-align: center; font-size: 12px; font-weight: 600;",
          if (!is.na(val)) sprintf("%.2f", val) else "—"
        )
      }),
      tags$td(
        style = "text-align: center; font-weight: 600; background: #e3f2fd;",
        tags$strong(sprintf("%.2f", overall_topic_avg))
      )
    )
    
    # Create quantitative statistics table (non-binary)
    stats_table <- tags$div(
      class = "berufsgruppe-stats",
      tags$h4("Statistik nach Berufsgruppe - Quantitative Ergebnisse"),
      tags$div(
        style = "overflow-x: auto;",
        tags$table(
          class = "stats-detail-table",
          tags$thead(
            header_row,
            question_header_row
          ),
          tags$tbody(
            data_rows,
            total_row
          )
        )
      )
    )
    
    # ✅ Get binary questions list
    binary_questions_list <- Filter(function(q) q$number %in% binary_qnums, questions_list)
    
    # ✅ Create binary questions table (simple counts only)
    binary_table <- create_binary_table_compact(project_id, binary_questions_list)
    
    # ✅ Create bar plot for binary questions
    binary_plot <- if (length(binary_questions_list) > 0) {
      tags$div(
        class = "binary-plot-container",
        tags$h4("Visualisierung - Dichotome Fragen"),
        plotlyOutput("binary_questions_plot", height = "500px")
      )
    } else {
      NULL
    }
    
    # ✅ Combine all elements
    tags$div(
      stats_table,
      binary_table
    )
  }

    
