        enable_btn <- TRUE
      } else if (input$alleine_oder_gruppe == "gruppe" &&
                 !is.null(input$gruppen_groesse) &&
                 input$gruppen_groesse != "") {
        enable_btn <- TRUE
      }
    }
    if (enable_btn) {
      shinyjs::enable("go_to_fuehrung")
    } else {
      shinyjs::disable("go_to_fuehrung")
    }
  })
