  # Helper to get all responses in wide format for admin table
  get_all_responses_wide <- function(con) {
    DBI::dbGetQuery(
      con,
      "
    SELECT r.user_id, r.question_id, r.response_value
    FROM responses r
    ORDER BY r.user_id
  "
    ) %>%
      tidyr::pivot_wider(id_cols = user_id,
                         names_from = question_id,
                         values_from = response_value)
  }
  
  # Admin responses table
  output$admin_responses_table <- DT::renderDataTable({
    req(user_role() == "admin")
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    wide <- get_all_responses_wide(con)
    DT::datatable(
      wide,
      options = list(pageLength = 25, scrollX = TRUE),
      rownames = FALSE,
      filter = "top"
    )
  })
  
  #-----------------User View: Only Their Own Responses-------------------------
  
  # Helper function: safely get input values (unchanged)
  get_input_safe <- function(id) {
    val <- input[[id]]
    if (is.null(val) || length(val) == 0)
      return(NA_character_)
    if (is.logical(val) &&
        length(val) == 1 && !is.na(val))
      return(as.character(val))
    if (is.character(val) && length(val) == 1)
      return(val)
    if (is.numeric(val) &&
        length(val) == 1)
      return(as.character(val))
    return(NA_character_)
  }
  
  # Helper to get all responses (wide format) for a specific user
  get_user_responses_wide <- function(con, user_id) {
    DBI::dbGetQuery(
      con,
      sprintf(
        "
    SELECT r.question_id, r.response_value, r.text_value
    FROM responses r
    WHERE r.user_id = '%s'
    ORDER BY r.question_id
  ",
        user_id
      )
    ) %>%
      tidyr::pivot_wider(
        id_cols = question_id,
        names_from = question_id,
        values_from = c(response_value, text_value)
      )
  }
  
  # Helper to get all responses (long format) for a specific user
  get_user_responses_long <- function(con, user_id) {
    DBI::dbGetQuery(
      con,
      sprintf(
        "
    SELECT r.question_id, r.response_value, r.text_value
    FROM responses r
    WHERE r.user_id = '%s'
    ORDER BY r.question_id
  ",
        user_id
      )
    )
  }
  
  output$user_responses_table <- DT::renderDataTable({
    req(user_role() != "admin")  # Only for non-admin users
    user_id <- current_user()    # Replace this with however you get the current user
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    user_long <- DBI::dbGetQuery(
      con,
      sprintf(
        "
    SELECT r.question_id, r.response_value, r.text_value
    FROM responses r
    WHERE r.user_id = '%s'
    ORDER BY r.question_id
  ",
        user_id
      )
    )
    
    # Map question_id to question label for display
    question_labels <- c(
      sapply(fuehrung_questions, function(q)
        setNames(q$label, q$id)),
      sapply(mit_questions, function(q)
        setNames(q$label, q$id)),
      sapply(pat_questions, function(q)
        setNames(q$label, q$id)),
      sapply(ein_questions, function(q)
        setNames(q$label, q$id)),
      sapply(qual_questions, function(q)
        setNames(q$label, q$id))
    )
    user_long$Frage <- question_labels[user_long$question_id]
    
    DT::datatable(
      user_long[, c("Frage", "response_value", "text_value")],
      colnames = c("Frage", "Antwort", "Begründung"),
      options = list(pageLength = 25, scrollX = TRUE),
      rownames = FALSE
    )
  })
  
  
    #--------------Lab Info Submit Status (Enhanced)----------------------------
    
  output$labinfo_submit_status <- renderUI({
    
    req(user_logged_in())
    
    project_id <- current_project_id()
    
    if (is.null(project_id) || project_id == "") {
      return(NULL)
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      
      labinfo <- DBI::dbGetQuery(
        con,
        "SELECT created_at FROM lab_info WHERE project_id = $1",
        params = list(as.integer(project_id))
      )
      
      if (nrow(labinfo) > 0) {
        # ✅ Use proper timezone conversion
        last_saved <- as.POSIXct(labinfo$created_at[1], tz = "UTC")
        
        # Convert to local time
        local_time <- format(last_saved, "%d.%m.%Y %H:%M", tz = Sys.timezone())
        
        div(
          style = "color:#28a745;margin-top:12px;font-size:13px;",
          icon("check-circle"),
          sprintf(" Zuletzt gespeichert: %s", local_time)
        )
      } else {
        div(
          style = "color:#6c757d;margin-top:12px;font-size:13px;font-style:italic;",
          icon("info-circle"),
          " Noch nicht gespeichert"
        )
      }
      
    }, error = function(e) {
      NULL
    })
  })
    
    # ✅ Main submit button observer (simplified - just calls save function)
    observeEvent(input$submit_labinfo, {
      
      pid <- current_project_id()
      
      if (is.null(pid) || pid == "") {
        showNotification("Bitte wählen Sie ein Projekt!", type = "error")
        return()
      }
      
      # Call the save function
      result <- save_lab_info_data()
      
      if (result) {
        
        # Also save einrichtung to projects table
        einrichtung_val <- if (!is.null(input$name) && nchar(input$name) > 0) {
          as.character(input$name)
        } else {
          NA_character_
        }
        
        if (!is.null(einrichtung_val) && !is.na(einrichtung_val) && nchar(einrichtung_val) > 0) {
          con_temp <- get_db_con()
          on.exit(DBI::dbDisconnect(con_temp), add = TRUE)
          
          tryCatch({
            DBI::dbExecute(
              con_temp,
              "UPDATE projects SET einrichtung = $1 WHERE id = $2",
              params = list(einrichtung_val, as.integer(pid))
            )
            message("✓ Einrichtung saved to projects: ", einrichtung_val)
          }, error = function(e) {
            message("⚠ Error saving einrichtung: ", e$message)
          })
        }
        
        showNotification(
          "Labordaten erfolgreich gespeichert!",
          type = "message",
          duration = 3
        )
      }
    })
    
    # ✅ Save buttons on each tab
    observeEvent(input$btn_save_grundlagen, {
      save_lab_info_data()
    })
    
    observeEvent(input$btn_save_personal, {
      save_lab_info_data()
    })
    
    observeEvent(input$btn_save_edv, {
      save_lab_info_data()
    })
    
    observeEvent(input$btn_save_input, {
      save_lab_info_data()
    })
  
