  # Helper to get the tag from the invitation code
  get_tag_from_invitation <- function() {
    tag <- redeemed_code_info()$assessment_type
    if (is.null(tag) || tag == "")
      tag <- "selbstbewertung" # fallback
    tag
  }
  
  get_project_id_from_invitation_code <- function(invitation_code) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    res <- DBI::dbGetQuery(
      con,
      "SELECT project_id FROM invitation_codes WHERE code = $1",
      params = list(invitation_code)
    )
    if (nrow(res) > 0 && !is.na(res$project_id[1])) {
      return(res$project_id[1])
    } else {
      return(NA_integer_)
    }
  }
  
  #-------------------------------------------------------------------------------
  
  # ---- Helper: Get assessment_type from invitation code ----
  get_assessment_type_from_invitation_code <- function(code) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    res <- DBI::dbGetQuery(con,
                           "SELECT assessment_type FROM invitation_codes WHERE code = $1",
                           params = list(code))
    if (nrow(res) == 1)
      return(res$assessment_type[[1]])
    return(NA_character_)
  }
  
  
  get_submission_tag <- function() {
    if (user_role() %in% c("laborleitung", "admin")) {
      proj_id <- current_project_id()
      if (is.null(proj_id) || length(proj_id) != 1 || is.na(proj_id) || proj_id == "") {
        "default"
      } else {
        paste0("project_", proj_id)
      }
      
    } else if (user_role() == "colleague") {
      proj_id <- current_project_id()
      if (is.null(proj_id) || length(proj_id) != 1 || is.na(proj_id) || proj_id == "") {
        "default"
      } else {
        paste0("colleague_", user_id(), "_project_", proj_id)
      }
      
    } else if (user_role() %in% c("leading_peer", "co_peer")) {
      # ✅ Use invitation code if available, otherwise create unique tag
      code <- session$userData$invitation_code
      if (!is.null(code) && code != "" && !is.na(code)) {
        as.character(code)
      } else {
        proj_id <- current_project_id()
        paste0(user_role(), "_", user_id(), "_project_", proj_id)
      }
      
    } else {
      "default"
    }
  }
  
  showCenteredSuccess <- function(msg, duration = 5000) {
    session$sendCustomMessage("centeredSuccess", list(message = msg, duration = duration))
  }
  
  
  #-----------------------------submit response-----------------------------------
  
  observeEvent(input$submit_questionnaire, {

    
    req(user_logged_in())
    
    if (is_demo_mode()) {
      message("Demo mode: submit ignored")
      output$questionnaire_submit_status <- renderUI({
        div(style="color:#856404;font-weight:600;",
            icon("info-circle"),
            " Demo-Modus: Absenden ist deaktiviert.")
      })
      return()
    }
    
    message("\n========== SUBMIT QUESTIONNAIRE ==========")
    
    # Determine assessment type
    assessment_type <- if (user_assessment_type %in% c("laborleitung", "colleague")) {
      "selbstbewertung"
    } else if (user_assessment_type %in% c("leading_peer", "co_peer")) {
      "fremdbewertung"
    } else {
      "selbstbewertung"
    }
    
    message("User ID: ", current_user_id)
    message("Project ID: ", project_id)
    message("Assessment Type: ", assessment_type)
    
    if (is.null(project_id) || project_id == "" || is.na(project_id)) {
      showNotification("Kein Projekt ausgewählt!", type = "error")
      return()
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    # Check if already submitted
    check_submitted <- DBI::dbGetQuery(
      con,
      "SELECT status FROM questionnaire_drafts
     WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3",
      params = list(as.character(current_user_id), as.character(project_id), questionnaire_id)
    )
    
    if (nrow(check_submitted) > 0 && check_submitted$status[1] == "submitted") {
      showNotification(
        "Dieser Fragebogen wurde bereits abgeschickt!",
        type = "error",
        duration = 5
      )
      return()
    }
    
    # ============================================
    # COLLECT ALL ANSWERS
    # ============================================
    
    all_answers <- list()
    
    # Berufsgruppe
    if (!is.null(input$Berufsgruppe) && input$Berufsgruppe != "") {
      all_answers[["Berufsgruppe"]] <- input$Berufsgruppe
    }
    
    # Group settings
    if (!is.null(input$alleine_oder_gruppe) && input$alleine_oder_gruppe != "") {
      all_answers[["alleine_oder_gruppe"]] <- input$alleine_oder_gruppe
    }
    
    group_size <- 1L
    if (!is.null(input$gruppen_groesse) && input$gruppen_groesse != "") {
      all_answers[["group_size"]] <- input$gruppen_groesse
      all_answers[["gruppen_groesse"]] <- input$gruppen_groesse  # ✅ Also save as gruppen_groesse
      group_size <- as.integer(input$gruppen_groesse)
    }
    
    # ✅ NEW: Default for laborleitung (who never see the group question)
    if (user_role() == "laborleitung") {
      all_answers[["alleine_oder_gruppe"]] <- "alleine"
      all_answers[["group_size"]] <- 1
      all_answers[["gruppen_groesse"]] <- 1
      group_size <- 1L
      message("→ Laborleitung detected, setting default group_size = 1")
    }
    
    # ============================================
    # COLLECT QUESTION RESPONSES
    # ============================================
    
    responses_to_insert <- list()
    
    all_question_lists <- list(
      list(questions = fuehrung_questions, tag = "fuehrung"),
      list(questions = mit_questions, tag = "mitarbeitende"),
      list(questions = pat_questions, tag = "patienten"),
      list(questions = ein_questions, tag = "einsender"),
      list(questions = qual_questions, tag = "qualitaet")
    )
    
    for (qlist in all_question_lists) {
      questions <- qlist$questions
      tag <- qlist$tag
      
      for (q in questions) {
        qid <- q$id
        score_id <- paste0("Freitext", qid)
        text_id <- paste0("Freitext_text", qid)
        
        response_value <- NULL
        text_value <- NULL
        
        if (!is.null(input[[score_id]]) && input[[score_id]] != "") {
          response_value <- input[[score_id]]
          all_answers[[score_id]] <- response_value
        }
        
        if (!is.null(input[[text_id]]) && input[[text_id]] != "") {
          text_value <- input[[text_id]]
          all_answers[[text_id]] <- text_value
        }
        
        # Store for insertion into responses table
        if (!is.null(response_value) || !is.null(text_value)) {
          responses_to_insert[[length(responses_to_insert) + 1]] <- list(
            question_id = qid,
            response_value = response_value,
            text_value = text_value,
            tag = tag
          )
        }
      }
    }
    
    if (length(all_answers) == 0) {
      showNotification("Keine Daten zum Absenden!", type = "warning")
      return()
    }
    
    answers_json <- jsonlite::toJSON(all_answers, auto_unbox = TRUE)
    submission_id <- uuid::UUIDgenerate()
    
    message("Submission ID: ", submission_id)
    message("Responses to insert: ", length(responses_to_insert))
    
    tryCatch({
      
      # ============================================
      # 1. UPDATE/INSERT QUESTIONNAIRE DRAFT
      # ============================================
      
      existing <- DBI::dbGetQuery(
        con,
        "SELECT id FROM questionnaire_drafts 
       WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3",
        params = list(as.character(current_user_id), as.character(project_id), questionnaire_id)
      )
      
      if (nrow(existing) > 0) {
        DBI::dbExecute(
          con,
          "UPDATE questionnaire_drafts 
         SET answers = $1, last_saved = NOW(), status = 'submitted'
         WHERE id = $2",
          params = list(answers_json, existing$id[1])
        )
        message("✓ Draft updated - ID: ", existing$id[1])
      } else {
        DBI::dbExecute(
          con,
          "INSERT INTO questionnaire_drafts (user_id, project_id, questionnaire_id, answers, status, last_saved) 
         VALUES ($1, $2, $3, $4, 'submitted', NOW())",
          params = list(as.character(current_user_id), as.character(project_id), questionnaire_id, answers_json)
        )
        message("✓ Draft inserted - new record")
      }
      
      # ============================================
      # 2. INSERT INTO RESPONSES TABLE
      # ============================================
      
      message("\n→ Inserting ", length(responses_to_insert), " responses into responses table...")
      
      for (resp in responses_to_insert) {
        
        # ✅ Handle NULL values properly
        resp_val <- if (is.null(resp$response_value) || resp$response_value == "") {
          NA_character_
        } else {
          as.character(resp$response_value)
        }
        
        text_val <- if (is.null(resp$text_value) || resp$text_value == "") {
          NA_character_
        } else {
          as.character(resp$text_value)
        }
        
        DBI::dbExecute(
          con,
          "INSERT INTO responses (
          user_id,
          question_id,
          response_value,
          text_value,
          tag,
          created_at,
          assessment_type,
          submission_id,
          project_id,
          group_size
        ) VALUES ($1, $2, $3, $4, $5, NOW(), $6, $7, $8, $9)",
          params = list(
            as.integer(current_user_id),
            resp$question_id,
            resp_val,
            text_val,
            resp$tag,
            assessment_type,
            submission_id,
            as.character(project_id),
            group_size
          )
        )
      }
      
      message("✓ All ", length(responses_to_insert), " responses inserted into responses table")
      
      # Trigger refresh
      responses_data_changed(responses_data_changed() + 1)
      
      showNotification(
        sprintf("✓ Fragebogen erfolgreich abgeschickt! (%d Antworten)", length(responses_to_insert)),
        type = "message",
        duration = 5
      )
      
      # Disable inputs
      shinyjs::delay(500, {
        disable_all_questionnaire_inputs()
      })
      
      # Show success UI
      output$questionnaire_submit_status <- renderUI(
        div(
          style = "padding: 20px; background-color: #dff0d8; border: 1px solid #d6e9c6; border-radius: 4px; margin: 20px 0; text-align: center;",
          div(
            style = "color: #3c763d; font-weight: bold; font-size: 18px;",
            icon("check-circle", style = "font-size: 32px; color: #5cb85c;"),
            tags$br(), tags$br(),
            "Fragebogen erfolgreich abgeschickt!"
          ),
          tags$hr(style = "border-color: #d6e9c6;"),
          div(
            style = "color: #3c763d;",
            sprintf("Vielen Dank! %d Antworten wurden gespeichert.", length(responses_to_insert))
          )
        )
      )
      
    }, error = function(e) {
      message("ERROR: ", e$message)
      print(e)
      showNotification(paste("Fehler beim Absenden:", e$message), type = "error", duration = 10)
    })
    
    message("==========================================\n")
  }, ignoreInit = TRUE)
  
  
  
  # ---- Helper: get question label from a question list and question_id ----
  get_question_label <- function(question_list, question_id) {
    idx <- which(sapply(question_list, function(q)
      q$id) == question_id)
    if (length(idx) == 1)
      question_list[[idx]]$label
    else
      NA_character_
  }
  
  # ---- Helper to get responses for any questionnaire ----
  get_responses <- function(question_list, tag_value) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    question_ids <- sapply(question_list, function(q)
      q$id)
    sql <- sprintf(
      "SELECT user_id, question_id, response_value, text_value, tag, created_at
     FROM responses
     WHERE question_id IN (%s) AND tag = $1
     ORDER BY user_id, question_id",
      paste0("'", question_ids, "'", collapse = ", ")
    )
    res <- DBI::dbGetQuery(con, sql, params = list(tag_value))
    if (nrow(res) == 0)
      return(res)
    res$question_label <- sapply(res$question_id, function(qid)
      get_question_label(question_list, qid))
    res[, c(
      "user_id",
      "question_id",
      "question_label",
      "response_value",
      "text_value",
      "tag",
      "created_at"
    )]
  }
  
