  # 1. UI for the report project selector
  output$report_project_selector_ui <- renderUI({
    role <- user_role()
    uid <- user_id()
    if (is.null(role) || length(role) == 0) {
      return(NULL)
    }
    choices <- get_project_choices(role, uid)
    if (length(choices) == 0) {
