  #--------------Download Lab Info as PDF----------------------------
  
  output$download_labinfo_pdf <- downloadHandler(
    filename = function() {
      project_name <- current_project_name()
      if (is.null(project_name) || project_name == "") {
        project_name <- "Labor"
      }
      project_name <- gsub("[^A-Za-z0-9_-]", "_", project_name)
      paste0("Laborinformation_", project_name, "_", format(Sys.Date(), "%Y%m%d"), ".pdf")
    },
    
    content = function(file) {
      
      message("\n=== Lab Info PDF Generation ===")
      
      project_id <- current_project_id()
      
      if (is.null(project_id) || project_id == "") {
        showNotification("Kein Projekt ausgewählt.", type = "error", duration = 5)
        writeLines("ERROR: Kein Projekt ausgewählt.", file)
        return(NULL)
      }
      
      message("Project ID: ", project_id)
      
      template_file <- "labinfo_report.Rmd"
      
      if (!file.exists(template_file)) {
        showNotification("Template nicht gefunden.", type = "error", duration = 10)
        writeLines("Template nicht verfügbar.", file)
        return(NULL)
      }
      
      showNotification(
        "PDF wird erstellt... Bitte warten.",
        type = "message",
        duration = NULL,
        id = "pdf_labinfo_progress"
      )
      
      tryCatch({
        
        message("Step 1: Save current data")
        save_result <- save_lab_info_data()
        
        if (!save_result) {
          message("Warning: Could not save data before generating PDF")
        }
        
        message("Step 2: Setup temp directory")
        template_path <- normalizePath(template_file, mustWork = TRUE)
        tmpdir <- tempdir()
        owd <- setwd(tmpdir)
        on.exit({
          setwd(owd)
          removeNotification("pdf_labinfo_progress")
        }, add = TRUE)
        
        message("  Working in: ", tmpdir)
        
        message("Step 3: Copy template")
        file.copy(template_path, file.path(tmpdir, template_file), overwrite = TRUE)
        
        message("Step 4: Get data from database")
        con <- get_db_con()
        on.exit(DBI::dbDisconnect(con), add = TRUE)
        
        # Get project title
        project_query <- DBI::dbGetQuery(
          con,
          "SELECT title FROM projects WHERE id = $1",
          params = list(as.integer(project_id))
        )
        
        project_title <- if (nrow(project_query) > 0 && !is.na(project_query$title[1])) {
          project_query$title[1]
        } else {
          "Labor"
        }
        
        message("  Project title: ", project_title)
        
        # Get lab info
        labinfo <- DBI::dbGetQuery(
          con,
          "SELECT * FROM lab_info WHERE project_id = $1",
          params = list(as.integer(project_id))
        )
        
        if (nrow(labinfo) == 0) {
          message("  WARNING: No lab info found, using empty data")
          labinfo <- data.frame(
            project_id = project_id,
            name = "",
            internetadresse = "",
            stringsAsFactors = FALSE
          )
        }
        
        message("  Lab info rows: ", nrow(labinfo))
        
        message("Step 5: Save CSV")
        write.csv(labinfo, file.path(tmpdir, "labinfo.csv"), 
                  row.names = FALSE, fileEncoding = "UTF-8")
        
        message("Step 6: Render PDF")
        
        output_file <- rmarkdown::render(
          input = file.path(tmpdir, template_file),
          output_format = "pdf_document",  
          output_file = "labinfo_report.pdf",
          output_dir = tmpdir,
          params = list(
            project_title = project_title,
            project_id = project_id
          ),
          envir = new.env(),
          quiet = FALSE
        )
        
        message("  ✓ PDF rendered: ", output_file)
        message("  PDF size: ", file.size(output_file), " bytes")
        
        message("Step 7: Copy to destination")
        file.copy(output_file, file, overwrite = TRUE)
        
        removeNotification("pdf_labinfo_progress")
        showNotification(
          "PDF erfolgreich erstellt!",
          type = "message",
          duration = 5
        )
        
        message("=== SUCCESS ===\n")
        
      }, error = function(e) {
        message("\n=== ERROR ===")
        message("Error message: ", e$message)
        message("Call stack:")
        print(sys.calls())
        
        removeNotification("pdf_labinfo_progress")
        showNotification(
          paste("Fehler beim Erstellen des PDFs:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    },
    
    contentType = "application/pdf"
  )
  
  
  
  #------------------- Download Handler (Selbstbewertung Bericht)-----------------
  
  output$downloadPersonalReport_reports <- downloadHandler(
    filename = function() paste0("selbstbewertung_", format(Sys.Date(), "%Y%m%d"), ".pdf"),
    content  = function(file) {
      
      message("=== Download started ===")
      
      # Get project info
      project_id <- current_project_id()
      
      # ✅ Get project title from database
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      project_query <- DBI::dbGetQuery(
        con,
        "SELECT title FROM projects WHERE id = $1",
        params = list(project_id)
      )
      
      project_title <- if (nrow(project_query) > 0 && !is.na(project_query$title[1])) {
        project_query$title[1]
      } else {
        "Unbekanntes Projekt"
      }
      
      message("Project ID: ", project_id)
      message("Project Title: ", project_title)
      
      
      
      # ✅ Get project ID
      project_id_val <- isolate(current_project_id())
      
      # ✅ Fetch project title from DATABASE with better error handling
      project_title_val <- tryCatch({
        if (!is.null(project_id_val) && !is.na(project_id_val) && project_id_val != "") {
          
          message("  Fetching project title for ID: ", project_id_val)
          
          con <- get_db_connection()
          on.exit(DBI::dbDisconnect(con), add = TRUE)
          
          result <- DBI::dbGetQuery(con,
                                    "SELECT title FROM projects WHERE id = $1",
                                    params = list(as.integer(project_id_val))  # ✅ Ensure integer
          )
          
          message("  Query result rows: ", nrow(result))
          
          if (nrow(result) > 0) {
            title <- result$title[1]
            message("  Found title: '", title, "'")
            
            if (!is.null(title) && !is.na(title) && nzchar(title)) {
              return(title)
            }
          }
          
          message("  No title found, using default")
          return("Projekt")
          
        } else {
          message("  Invalid project_id: ", project_id_val)
          return("Projekt")
        }
      }, error = function(e) {
        message("  ERROR fetching project title: ", e$message)
        return("Projekt")
      })
      
      message("  Final Project ID: ", project_id_val)
      message("  Final Project Title: ", project_title_val)
      
      # Use .Rmd file
      template_file <- "selbstbewertung_report.Rmd"
      
      if (!file.exists(template_file)) {
        showNotification("Template nicht gefunden.", type = "error", duration = 10)
        writeLines("Template nicht verfügbar.", file)
        return(NULL)
      }
      
      tryCatch({
        
        message("Step 1: Getting template path")
        template_path <- normalizePath(template_file, mustWork = TRUE)
        
        message("Step 2: Changing to temp directory")
        tmpdir <- tempdir()
        owd <- setwd(tmpdir)
        on.exit(setwd(owd), add = TRUE)
        
        # ✅ CLEANUP OLD PLOTS
        message("  Cleaning up old plots...")
        old_plots <- list.files(tmpdir, pattern = "^plot_.*\\.png$", full.names = TRUE)
        if (length(old_plots) > 0) {
          file.remove(old_plots)
          message("  Removed ", length(old_plots), " old plot files")
        }
        
        message("Step 3: Copying template to temp dir")
        file.copy(template_path, file.path(tmpdir, template_file), overwrite = TRUE)
        
        message("Step 4: Gathering user responses")
        user_responses <- tryCatch({
          gather_answers()
        }, error = function(e) {
          message("ERROR in gather_answers: ", e$message)
          data.frame(...)
        })
        
        # ✅ ADD THIS DEBUG CODE
        message("\n=== DEBUG: First 5 Frage values ===")
        if (nrow(user_responses) > 0 && "Frage" %in% names(user_responses)) {
          for (i in 1:min(5, nrow(user_responses))) {
            message(sprintf("[%d] '%s'", i, user_responses$Frage[i]))
          }
        }
        message("===================================\n")
        
        # ✅ ADD THIS DEBUG CODE
        message("=== DEBUG: Check for duplicates ===")
        if (nrow(user_responses) > 0 && "Frage" %in% names(user_responses)) {
          sample_fragen <- head(user_responses$Frage, 5)
          for (i in seq_along(sample_fragen)) {
            message(sprintf("  Row %d: '%s'", i, sample_fragen[i]))
          }
        }
        message("===================================")
        
        # Debug output
        message("Gathered ", nrow(user_responses), " responses")
        if (nrow(user_responses) > 0) {
          message("Columns: ", paste(names(user_responses), collapse = ", "))
          message("Sections: ", paste(unique(user_responses$Section), collapse = ", "))
        } else {
          message("WARNING: No responses gathered!")
        }
        
        # Save user responses to CSV in temp dir
        message("Step 5: Saving user responses to CSV")
        
        
        message("Step 6: Creating FMSB radar plots in temp dir")
        mit_binary_global_qnums <- c(10, 20, 24)
        
        # ✅ Updated plot configs for FMSB
        plot_configs <- list(
          plot_fuehrung = list(
            data = make_radar_df_from_inputs_fmsb(input, fuehrung_questions),
            title = "Führung",
            colour = "#003B73"
          ),
          plot_mit = list(
            data = make_radar_df_from_inputs_fmsb(input, mit_questions, binary_qnums = mit_binary_global_qnums),
            title = "Mitarbeitende",
            colour = "#136377"
          ),
          plot_pat = list(
            data = make_radar_df_from_inputs_fmsb(input, pat_questions),
            title = "Patienten & Angehörige",
            colour = "#b23a48"
          ),
          plot_ein = list(
            data = make_radar_df_from_inputs_fmsb(input, ein_questions),
            title = "Einsender & Kooperationspartner",
            colour = "#4b61d1"
          ),
          plot_qual = list(
            data = make_radar_df_from_inputs_fmsb(input, qual_questions),
            title = "Qualitätsindikatoren & Validierung",
            colour = "#c58f00"
          )
        )
        
        plot_files <- c(
          "plot_fuehrung.png",
          "plot_mit.png",
          "plot_pat.png",
          "plot_ein.png",
          "plot_qual.png"
        )
        
        for (i in seq_along(plot_configs)) {
          config <- plot_configs[[i]]
          plot_file <- file.path(tmpdir, plot_files[i])
          
          # ✅ DELETE OLD PLOT FIRST
          if (file.exists(plot_file)) {
            file.remove(plot_file)
            message(paste("  Removed old plot:", plot_file))
          }
          
          message(paste("  Creating ggplot2 radar plot:", config$title))
          
          tryCatch({
            make_ggplot_radar_png(
              radar_df = config$data,
              title = config$title,
              colour = config$colour,
              filename = plot_file,
              width = 800,
              height = 800
            )
            
            if (file.exists(plot_file)) {
              message(paste("    ✓ Plot saved, size:", file.size(plot_file), "bytes"))
            } else {
              message(paste("    ✗ WARNING: Plot not created!"))
            }
            
          }, error = function(e) {
            message(paste("    ERROR:", e$message))
            png(plot_file, width = 800, height = 600)
            plot.new()
            text(0.5, 0.5, paste("Fehler:\n", config$title), cex = 1.5)
            dev.off()
          })
        }
        
        # Get user's Berufsgruppe and alleine_oder_gruppe for the report
        berufsgruppe <- if (!is.null(input$Berufsgruppe) && input$Berufsgruppe != "") {
          as.character(input$Berufsgruppe)
        } else {
          "Nicht angegeben"
        }
        
        alleine_oder_gruppe <- if (!is.null(input$alleine_oder_gruppe) && input$alleine_oder_gruppe != "") {
          as.character(input$alleine_oder_gruppe)
        } else {
          "Nicht angegeben"
        }
        
        # ✅ Get group size
        gruppen_groesse <- if (!is.null(input$alleine_oder_gruppe) && 
                               input$alleine_oder_gruppe == "gruppe" && 
                               !is.null(input$gruppen_groesse)) {
          as.character(input$gruppen_groesse)
        } else {
          "1"  # Default to 1 if filling alone
        }
        
        
        message("Step 7: Rendering PDF")
        message("  Berufsgruppe: ", berufsgruppe)
        message("  Alleine oder Gruppe: ", alleine_oder_gruppe)
        
        output_file <- rmarkdown::render(
          input = file.path(tmpdir, template_file),
          output_format = "pdf_document",
          output_file = "report.pdf",
          output_dir = tmpdir,
          params = list(
            berufsgruppe = berufsgruppe,
            alleine_oder_gruppe = alleine_oder_gruppe,
            gruppen_groesse = gruppen_groesse,
            responses_data = user_responses,
            project_id = project_id,
            project_title = project_title 
          ),
          envir = new.env(),
          quiet = FALSE
        )
        
        
        message("Step 8: Moving PDF to destination")
        file.copy(output_file, file, overwrite = TRUE)
        
        message("=== Download completed successfully ===")
        
        showNotification(
          "Bericht erfolgreich erstellt!",
          type = "message",
          duration = 5
        )
        
      }, error = function(e) {
        message("=== ERROR ===")
        message(paste("  Message:", e$message))
        message(paste("  Traceback:", paste(sys.calls(), collapse = "\n")))
        
        showNotification(
          paste("Fehler beim Erstellen des Berichts:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
  #---------------------------------download handler------------------------------
  #--------------------Zusammenfassung Selbstbewertung + labinfo------------------
  
  output$downloadZusammenfassung <- downloadHandler(
    filename = function() {
      paste0("Zusammenfassung_", format(Sys.Date(), "%Y%m%d"), ".pdf")
    },
    
    content = function(file) {
      
      message("\n###############################################")
      message("### ZUSAMMENFASSUNG PDF GENERATION ###")
      message("###############################################\n")
      
      # Get project ID
      project_id <- isolate(current_project_id())
      
      # Validate
      if (is.null(project_id) || project_id == "" || is.na(project_id)) {
        showNotification(
          "Bitte wählen Sie ein Projekt aus der Dropdown-Liste aus.",
          type = "error",
          duration = 10
        )
        writeLines("FEHLER: Kein Projekt ausgewählt.", file)
        return(NULL)
      }
      
      message("✓ Project ID: ", project_id)
      
      # Check for template
      template_file <- "zusammenfassung_report.Rmd"
      
      if (!file.exists(template_file)) {
        message("ERROR: Template not found: ", template_file)
        message("Working directory: ", getwd())
        message("Files: ", paste(list.files(pattern = "\\.Rmd$"), collapse = ", "))
        
        showNotification(
          paste0("Template nicht gefunden: ", template_file),
          type = "error",
          duration = 10
        )
        writeLines("FEHLER: Template nicht gefunden.", file)
        return(NULL)
      }
      
      message("✓ Template found")
      
      # Show progress
      showNotification(
        "PDF wird erstellt... Bitte warten.",
        type = "message",
        duration = NULL,
        id = "pdf_progress"
      )
      
      tryCatch({
        
        # Setup temp directory
        message("\nStep 1: Setup temp directory")
        tmpdir <- tempdir()
        original_wd <- getwd()
        setwd(tmpdir)
        on.exit({
          setwd(original_wd)
        }, add = TRUE)
        
        message("  Working dir: ", getwd())
        
        # Copy template
        message("\nStep 2: Copy template")
        template_path <- file.path(original_wd, template_file)
        file.copy(template_path, file.path(tmpdir, template_file), overwrite = TRUE)
        message("  ✓ Template copied")
        
        # Database connection
        message("\nStep 3: Database connection")
        con <- get_db_con()
        on.exit(DBI::dbDisconnect(con), add = TRUE)
        
        # Get project info
        project_query <- DBI::dbGetQuery(
          con,
          "SELECT title FROM projects WHERE id = $1",
          params = list(project_id)
        )
        project_title <- if (nrow(project_query) > 0) project_query$title[1] else "Projekt"
        message("  ✓ Project: ", project_title)
        
        # ===== LAB INFO =====
        message("\nStep 4: Lab info")
        labinfo_raw <- DBI::dbGetQuery(
          con,
          "SELECT * FROM lab_info WHERE project_id = $1",
          params = list(project_id)
        )
        
        if (nrow(labinfo_raw) == 0) {
          message("  ⚠ No lab info - placeholder")
          labinfo <- data.frame(
            lab_name = "Nicht verfügbar",
            street = "", plz = "", city = "", country = "",
            phone = "", email = "", website = "",
            lab_director = "", deputy = "",
            num_employees = "", num_doctors = "", num_mtl = "",
            accreditation = "", certification = "",
            stringsAsFactors = FALSE
          )
        } else {
          # Helper for safe extraction
          safe_char <- function(x) if (is.null(x) || is.na(x)) "" else as.character(x)
          
          labinfo <- data.frame(
            lab_name = safe_char(labinfo_raw$name[1]),
            street = safe_char(labinfo_raw$trag[1]),
            plz = "",
            city = "",
            country = "",
            phone = safe_char(labinfo_raw$telefonnummer[1]),
            email = safe_char(labinfo_raw$email[1]),
            website = safe_char(labinfo_raw$internetadresse[1]),
            lab_director = safe_char(labinfo_raw$ansprechpartner[1]),
            deputy = "",
            num_employees = safe_char(labinfo_raw$anzahl_total[1]),
            num_doctors = safe_char(labinfo_raw$anzahl_mit[1]),
            num_mtl = safe_char(labinfo_raw$anzahl_tech[1]),
            accreditation = "",
            certification = "",
            stringsAsFactors = FALSE
          )
        }
        
        write.csv(labinfo, "labinfo.csv", row.names = FALSE, fileEncoding = "UTF-8")
        message("  ✓ labinfo.csv")
        
        # ===== RESPONSES =====
        message("\nStep 5: Responses")
        
        get_topic_responses <- function(prefix, questions, topic_name) {
          df <- DBI::dbGetQuery(con, sprintf(
            "SELECT u.username, r.question_id, r.response_value, r.text_value
     FROM responses r
     JOIN users u ON u.id = r.user_id
     WHERE r.assessment_type = 'selbstbewertung'
       AND r.project_id = $1 AND r.question_id LIKE '%s%%'
     ORDER BY r.question_id, u.username", prefix
          ), params = list(project_id))
          
          message("  ", topic_name, ": ", nrow(df), " rows")
          
          if (nrow(df) > 0) {
            df$question <- sapply(df$question_id, function(qid) {
              q <- Find(function(x) x$id == qid, questions)
              if (!is.null(q)) q$label else qid
            })
            df <- df[, c("question_id", "username", "question", "response_value", "text_value")]  # ✅ Keep question_id
            colnames(df) <- c("question_id", "Nutzer", "Frage", "Bewertung", "Begründung")
          } else {
            df <- data.frame(
              question_id = character(0),
              Nutzer = character(0), 
              Frage = character(0),
              Bewertung = character(0), 
              Begründung = character(0),
              stringsAsFactors = FALSE
            )
          }
          df
        }
        
        write.csv(get_topic_responses("F", fuehrung_questions, "Führung"), 
                  "fuehrung_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("M", mit_questions, "Mitarbeitende"), 
                  "mitarbeitende_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("P", pat_questions, "Patienten"), 
                  "pat_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("E", ein_questions, "Einsender"), 
                  "ein_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("Q", qual_questions, "Qualität"), 
                  "qual_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        message("  ✓ All response CSVs")
        
        # ===== ENHANCED STATISTICS (with group_size weighting) =====
        message("\nStep 6: Enhanced Statistics with Berufsgruppe Breakdown")
        
        get_enhanced_stats <- function(topic_prefix) {
          
              # Get responses with group_size and berufsgruppe
              stats_query <- sprintf("
        SELECT 
          r.question_id,
          r.response_value::numeric as rv,
          COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
          COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
        FROM responses r
        JOIN users u ON u.id = r.user_id
        LEFT JOIN questionnaire_drafts qd 
          ON u.id::text = qd.user_id::text 
          AND qd.project_id::text = r.project_id::text
          AND qd.questionnaire_id = 'peer_review'
        WHERE r.project_id = $1
          AND r.assessment_type = 'selbstbewertung'
          AND r.question_id LIKE $2
          AND r.response_value IS NOT NULL
          AND r.response_value != ''
          AND r.response_value != 'N/A'
          AND r.response_value NOT IN ('Ja', 'Nein')
      ")
              
          stats_data <- DBI::dbGetQuery(con, stats_query, 
                                        params = list(project_id, paste0(topic_prefix, "%")))
          
          if (nrow(stats_data) == 0) {
            return(data.frame(
              Frage = character(0),
              n_gesamt = numeric(0),
              Mittelwert = numeric(0),
              Min = numeric(0),
              Max = numeric(0),
              Berufsgruppen = character(0)
            ))
          }
          
          # Expand by group_size
          expanded_list <- lapply(1:nrow(stats_data), function(i) {
            row <- stats_data[i, ]
            gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
            data.frame(
              question_id = rep(row$question_id, gs),
              rv = rep(row$rv, gs),
              berufsgruppe = rep(row$berufsgruppe, gs),
              stringsAsFactors = FALSE
            )
          })
          
          expanded <- do.call(rbind, expanded_list)
          
          # Get unique questions
          unique_questions <- sort(unique(expanded$question_id))
          
          # Calculate statistics per question
          result <- lapply(unique_questions, function(qid) {
            q_data <- expanded[expanded$question_id == qid, ]
            
            # Overall stats
            n_total <- nrow(q_data)
            mean_val <- mean(q_data$rv, na.rm = TRUE)
            min_val <- min(q_data$rv, na.rm = TRUE)
            max_val <- max(q_data$rv, na.rm = TRUE)
            
            # Berufsgruppe breakdown
            bg_stats <- aggregate(rv ~ berufsgruppe, data = q_data, FUN = function(x) {
              sprintf("Ø %.1f (n=%d)", mean(x), length(x))
            })
            
            bg_text <- paste(
              paste0(bg_stats$berufsgruppe, ": ", bg_stats$rv),
              collapse = "; "
            )
            
            data.frame(
              Frage = qid,
              n_gesamt = n_total,
              Mittelwert = round(mean_val, 2),
              Min = min_val,
              Max = max_val,
              Berufsgruppen = bg_text,
              stringsAsFactors = FALSE
            )
          })
          
          do.call(rbind, result)
        }
        
        # Generate all stats
        message("  Generating enhanced statistics...")
        
        fuehrung_stats_result <- get_enhanced_stats("F")
        write.csv(fuehrung_stats_result, "fuehrung_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        mitarbeitende_stats_result <- get_enhanced_stats("M")
        write.csv(mitarbeitende_stats_result, "mitarbeitende_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        pat_stats_result <- get_enhanced_stats("P")
        write.csv(pat_stats_result, "pat_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        ein_stats_result <- get_enhanced_stats("E")
        write.csv(ein_stats_result, "ein_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        qual_stats_result <- get_enhanced_stats("Q")
        write.csv(qual_stats_result, "qual_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        # Summary
        total_questions <- nrow(fuehrung_stats_result) + nrow(mitarbeitende_stats_result) + 
          nrow(pat_stats_result) + nrow(ein_stats_result) + nrow(qual_stats_result)
        
        message("  ✓ Enhanced stats created for ", total_questions, " questions across 5 topics")
        
        # ===== PLOTS =====
        message("\nStep 7: Plots (Single Average + Overlay by Berufsgruppe)")
        
        mit_binary_global_qnums <- c(10, 20, 24)
        
        # ✅ FUNCTION 1: Create single average plot (existing)
        create_single_plot <- function(name, questions, title, colour, binary_qnums = integer(0)) {
          plot_file <- paste0("plot_", name, ".png")
          
          tryCatch({
            message("  Creating single plot: ", title)
            
            questions_filtered <- if (length(binary_qnums) > 0) {
              Filter(function(q) !(q$number %in% binary_qnums), questions)
            } else {
              questions
            }
            
            question_ids <- sapply(questions_filtered, function(q) q$id)
            
            if (length(question_ids) == 0) {
              message("    ⚠ No questions")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Fragen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Get weighted responses
            responses <- DBI::dbGetQuery(con, sprintf(
              "SELECT 
        r.question_id, 
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd 
        ON u.id::text = qd.user_id::text 
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1 
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s) 
        AND r.response_value IS NOT NULL 
        AND r.response_value != ''
        AND r.response_value != 'N/A'
        AND r.response_value NOT IN ('Ja', 'Nein')"
        ,
              paste0("'", question_ids, "'", collapse = ", ")
            ), params = list(project_id))
            
            if (nrow(responses) == 0) {
              message("    ⚠ No data")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Daten", cex = 1.5)
              dev.off()
              return()
            }
            
            # Expand by group_size
            expanded_list <- lapply(1:nrow(responses), function(i) {
              row <- responses[i, ]
              gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
              data.frame(
                question_id = rep(row$question_id, gs),
                rv = rep(row$rv, gs)
              )
            })
            expanded <- do.call(rbind, expanded_list)
            
            # Calculate means
            means <- aggregate(rv ~ question_id, data = expanded, FUN = mean)
            
            values <- sapply(questions_filtered, function(q) {
              row <- means[means$question_id == q$id, ]
              if (nrow(row) > 0) row$rv else 0
            })
            
            labels <- sapply(questions_filtered, function(q) as.character(q$number))
            
            # Build radar data frame
            radar_df <- data.frame(matrix(nrow = 3, ncol = length(values)))
            radar_df[1, ] <- 5
            radar_df[2, ] <- 0
            radar_df[3, ] <- values
            colnames(radar_df) <- labels
            
            # Use ggplot2 radar
            make_ggplot_radar_png(radar_df, title, colour, plot_file, 800, 800)
            message("  ✓ ", title)
            
          }, error = function(e) {
            message("  ✗ ", title, " ERROR: ", e$message)
            png(plot_file, width = 800, height = 800)
            plot.new()
            text(0.5, 0.5, "Fehler", cex = 1.5)
            dev.off()
          })
        }
        
        # ✅ FUNCTION 2: Create overlay plot (by Berufsgruppe)
        create_overlay_plot <- function(name, questions, title, binary_qnums = integer(0)) {
          plot_file <- paste0("plot_overlay_", name, ".png")
          
          tryCatch({
            message("  Creating overlay plot: ", title)
            
            questions_filtered <- if (length(binary_qnums) > 0) {
              Filter(function(q) !(q$number %in% binary_qnums), questions)
            } else {
              questions
            }
            
            question_ids <- sapply(questions_filtered, function(q) q$id)
            
            if (length(question_ids) == 0) {
              message("    ⚠ No questions")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Fragen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Get responses with Berufsgruppe
            responses <- DBI::dbGetQuery(con, sprintf(
              "SELECT 
        r.question_id, 
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd 
        ON u.id::text = qd.user_id::text 
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1 
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s) 
        AND r.response_value IS NOT NULL 
        AND r.response_value != ''
        AND r.response_value != 'N/A'
        AND r.response_value NOT IN ('Ja', 'Nein')
              
              ",
              paste0("'", question_ids, "'", collapse = ", ")
            ), params = list(project_id))
            
            if (nrow(responses) == 0) {
              message("    ⚠ No data")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Daten", cex = 1.5)
              dev.off()
              return()
            }
            
            # Expand by group_size
            expanded_list <- lapply(1:nrow(responses), function(i) {
              row <- responses[i, ]
              gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
              data.frame(
                question_id = rep(row$question_id, gs),
                rv = rep(row$rv, gs),
                berufsgruppe = rep(row$berufsgruppe, gs),
                stringsAsFactors = FALSE
              )
            })
            expanded <- do.call(rbind, expanded_list)
            
            # Calculate means per question per berufsgruppe
            means <- aggregate(rv ~ question_id + berufsgruppe, data = expanded, FUN = mean)
            
            # Get unique berufsgruppen
            berufsgruppen <- unique(means$berufsgruppe)
            
            if (length(berufsgruppen) == 0) {
              message("    ⚠ No berufsgruppen")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Berufsgruppen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Colors
            bg_colors <- c(
              "MTL" = "#1f77b4",
              "Wissenschaftler(-in)" = "#ff7f0e",
              "Ärzte" = "#2ca02c",
              "IT" = "#d62728",
              "nicht anwendbar" = "#9467bd",
              "Nicht angegeben" = "#8c564b"
            )
            
            # Create ggplot2 overlay
            library(ggplot2)
            
            labels <- sapply(questions_filtered, function(q) as.character(q$number))
            n <- length(labels)
            angles <- seq(0, 2*pi, length.out = n + 1)[1:n]
            
            to_cartesian <- function(r, angle) {
              list(x = r * sin(angle), y = r * cos(angle))
            }
            
            # Create polygons for each berufsgruppe
            all_polygons <- lapply(berufsgruppen, function(bg) {
              bg_data <- means[means$berufsgruppe == bg, ]
              
              values <- sapply(questions_filtered, function(q) {
                row <- bg_data[bg_data$question_id == q$id, ]
                if (nrow(row) > 0) row$rv else 0
              })
              
              polygon_coords <- lapply(1:n, function(i) {
                coords <- to_cartesian(values[i], angles[i])
                data.frame(x = coords$x, y = coords$y)
              })
              polygon_df <- do.call(rbind, polygon_coords)
              polygon_df <- rbind(polygon_df, polygon_df[1, ])
              polygon_df$berufsgruppe <- bg
              
              return(polygon_df)
            })
            
            all_polygons_df <- do.call(rbind, all_polygons)
            
            # Grid circles
            grid_circles <- lapply(0:5, function(r) {
              angle_seq <- seq(0, 2*pi, length.out = 100)
              coords <- lapply(angle_seq, function(a) to_cartesian(r, a))
              data.frame(
                x = sapply(coords, function(c) c$x),
                y = sapply(coords, function(c) c$y),
                r = r
              )
            })
            grid_df <- do.call(rbind, grid_circles)
            
            # Axis lines
            axis_lines <- lapply(1:n, function(i) {
              coords <- to_cartesian(5.5, angles[i])
              data.frame(x = 0, y = 0, xend = coords$x, yend = coords$y)
            })
            axis_df <- do.call(rbind, axis_lines)
            
            # Labels
            label_coords <- lapply(1:n, function(i) {
              coords <- to_cartesian(6.2, angles[i])
              data.frame(x = coords$x, y = coords$y, label = labels[i])
            })
            label_df <- do.call(rbind, label_coords)
            
            # Create plot
            p <- ggplot() +
              geom_path(data = grid_df, aes(x = x, y = y, group = r), 
                        color = "grey85", linewidth = 0.5) +
              geom_text(data = data.frame(x = 0, y = 0:5, label = 0:5),
                        aes(x = x, y = y, label = label),
                        color = "grey50", size = 3, hjust = 1.5) +
              geom_segment(data = axis_df, 
                           aes(x = x, y = y, xend = xend, yend = yend),
                           color = "grey70", linewidth = 0.5) +
              geom_polygon(data = all_polygons_df, 
                           aes(x = x, y = y, fill = berufsgruppe, color = berufsgruppe, group = berufsgruppe),
                           alpha = 0.2, linewidth = 1.2) +
              geom_point(data = all_polygons_df[!duplicated(paste(all_polygons_df$berufsgruppe, all_polygons_df$x, all_polygons_df$y)), ],
                         aes(x = x, y = y, color = berufsgruppe),
                         size = 2.5) +
              geom_text(data = label_df, aes(x = x, y = y, label = label), 
                        size = 3.5, fontface = "bold") +
              scale_fill_manual(values = bg_colors, name = "Berufsgruppe") +
              scale_color_manual(values = bg_colors, name = "Berufsgruppe") +
              ggtitle(title) +
              coord_fixed() +
              xlim(c(-7, 7)) +
              ylim(c(-7, 7)) +
              theme_void() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold", margin = margin(b = 10)),
                legend.position = "bottom",
                legend.title = element_text(size = 12, face = "bold"),
                legend.text = element_text(size = 10)
              )
            
            ggsave(plot_file, p, width = 800/120, height = 800/120, dpi = 120)
            message("  ✓ ", title, " (Overlay)")
            
          }, error = function(e) {
            message("  ✗ ", title, " (Overlay) ERROR: ", e$message)
            png(plot_file, width = 800, height = 800)
            plot.new()
            text(0.5, 0.5, "Fehler", cex = 1.5)
            dev.off()
          })
        }
        
        # ✅ CREATE BOTH TYPES OF PLOTS
        message("  Single average plots:")
        create_single_plot("fuehrung", fuehrung_questions, "Führung", "#003B73")
        create_single_plot("mit", mit_questions, "Mitarbeitende", "#136377", mit_binary_global_qnums)
        create_single_plot("pat", pat_questions, "Patienten", "#b23a48")
        create_single_plot("ein", ein_questions, "Einsender", "#4b61d1")
        create_single_plot("qual", qual_questions, "Qualität", "#c58f00")
        
        message("  Overlay plots (by Berufsgruppe):")
        create_overlay_plot("fuehrung", fuehrung_questions, "Führung - nach Berufsgruppe")
        create_overlay_plot("mit", mit_questions, "Mitarbeitende - nach Berufsgruppe", mit_binary_global_qnums)
        create_overlay_plot("pat", pat_questions, "Patienten - nach Berufsgruppe")
        create_overlay_plot("ein", ein_questions, "Einsender - nach Berufsgruppe")
        create_overlay_plot("qual", qual_questions, "Qualität - nach Berufsgruppe")
        
        message("  ✓ All plots created")
        
        # ===== RENDER PDF =====
        message("\nStep 8: Render PDF")
        
        output_file <- rmarkdown::render(
          input = template_file,
          output_format = rmarkdown::pdf_document(
            toc = TRUE,
            toc_depth = 2,
            number_sections = FALSE,
            keep_tex = FALSE,
            latex_engine = "pdflatex"
          ),
          output_file = "report.pdf",
          output_dir = tmpdir,
          params = list(
            project_title = project_title,
            project_id = project_id
          ),
          envir = new.env(),
          quiet = FALSE,
          encoding = "UTF-8"
        )
        
        message("  ✓ PDF: ", file.size(output_file), " bytes")
        
        # Copy to destination
        message("\nStep 9: Copy PDF")
        file.copy(output_file, file, overwrite = TRUE)
        
        removeNotification("pdf_progress")
        showNotification(
          "PDF erfolgreich erstellt!",
          type = "message",
          duration = 5
        )
        
        message("\n### SUCCESS ###\n")
        
      }, error = function(e) {
        message("\n### ERROR ###")
        message("Message: ", e$message)
        message("\nCall stack:")
        print(sys.calls())
        
        removeNotification("pdf_progress")
        showNotification(
          paste("Fehler:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler beim Erstellen des Berichts:\n\n", e$message), file)
      })
    },
    
    contentType = "application/pdf"
  )
  

#---------------------------------download handler for power user------------------------------
#--------------------Zusammenfassung Selbstbewertung + labinfo------------------
  output$poweruser_downloadZusammenfassung <- downloadHandler(
    filename = function() {
      paste0("Zusammenfassung_", format(Sys.Date(), "%Y%m%d"), ".pdf")
    },
    
    content = function(file) {
      
      message("\n###############################################")
      message("### POWER USER ZUSAMMENFASSUNG PDF GENERATION ###")
      message("###############################################\n")
      
      # ✅ Use power user project selector
      project_id <- input$poweruser_report_project
      
      # Validate
      if (is.null(project_id) || project_id == "" || is.na(project_id)) {
        showNotification(
          "Bitte wählen Sie ein Projekt aus der Dropdown-Liste aus.",
          type = "error",
          duration = 10
        )
        writeLines("FEHLER: Kein Projekt ausgewählt.", file)
        return(NULL)
      }
      
      message("✓ Project ID: ", project_id)
      
      # Check for template
      template_file <- "zusammenfassung_report.Rmd"
      
      if (!file.exists(template_file)) {
        message("ERROR: Template not found: ", template_file)
        showNotification(
          paste0("Template nicht gefunden: ", template_file),
          type = "error",
          duration = 10
        )
        writeLines("FEHLER: Template nicht gefunden.", file)
        return(NULL)
      }
      
      message("✓ Template found")
      
      # Show progress
      showNotification(
        "PDF wird erstellt... Bitte warten.",
        type = "message",
        duration = NULL,
        id = "pdf_progress"
      )
      
      tryCatch({
        
        # Setup temp directory
