            sonstiges_laborbereiche = "",
            leistungsspektrum = "",
            sonstiges_leistungsspektrum = "",
            ausstattung = "",
            hauptlieferanten = "",
            question_binary_1 = "",
            farbcodesystem = "",
            question_binary_2 = "",
