            weitereinfo = safe_char(labinfo_raw$weitereinfo[1]),
            
            # IT Systems
            anbieterinfo = safe_char(labinfo_raw$anbieterinfo[1]),
            anbieterorder = safe_char(labinfo_raw$anbieterorder[1]),
            anbietermiddleware = safe_char(labinfo_raw$anbietermiddleware[1]),
            weitereit = safe_char(labinfo_raw$weitereit[1]),
            
            # KPIs
            laufendenjahres = safe_char(labinfo_raw$laufendenjahres[1]),
            vorjahres = safe_char(labinfo_raw$vorjahres[1]),
            kompetenzschwerpunkte = safe_char(labinfo_raw$kompetenzschwerpunkte[1]),
            
