        write.csv(labinfo, "labinfo.csv", row.names = FALSE, fileEncoding = "UTF-8")
        message("  ✓ labinfo.csv with complete data")
        
        get_topic_responses <- function(prefix, questions, topic_name) {
          df <- DBI::dbGetQuery(con, sprintf(
            "SELECT u.username, r.question_id, r.response_value, r.text_value
     FROM responses r
     JOIN users u ON u.id = r.user_id
     WHERE r.assessment_type = 'selbstbewertung'
       AND r.project_id = $1 AND r.question_id LIKE '%s%%'
     ORDER BY r.question_id, u.username", prefix
          ), params = list(project_id))
          
          message("  ", topic_name, ": ", nrow(df), " rows")
          
          if (nrow(df) > 0) {
            df$question <- sapply(df$question_id, function(qid) {
              q <- Find(function(x) x$id == qid, questions)
              if (!is.null(q)) q$label else qid
            })
            df <- df[, c("question_id", "username", "question", "response_value", "text_value")]  # ✅ Keep question_id
            colnames(df) <- c("question_id", "Nutzer", "Frage", "Bewertung", "Begründung")
          } else {
            df <- data.frame(
              question_id = character(0),
              Nutzer = character(0), 
              Frage = character(0),
              Bewertung = character(0), 
              Begründung = character(0),
              stringsAsFactors = FALSE
            )
          }
          df
        }
        
        write.csv(get_topic_responses("F", fuehrung_questions, "Führung"), 
                  "fuehrung_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("M", mit_questions, "Mitarbeitende"), 
                  "mitarbeitende_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("P", pat_questions, "Patienten"), 
                  "pat_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("E", ein_questions, "Einsender"), 
                  "ein_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(get_topic_responses("Q", qual_questions, "Qualität"), 
                  "qual_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        message("  ✓ All response CSVs")
        
        # ===== ENHANCED STATISTICS (with group_size weighting) =====
        message("\nStep 6: Enhanced Statistics with Berufsgruppe Breakdown")
        
        get_enhanced_stats <- function(topic_prefix) {
          
          # Get responses with group_size and berufsgruppe
          stats_query <- sprintf("
        SELECT 
          r.question_id,
          r.response_value::numeric as rv,
          COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
          COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
        FROM responses r
        JOIN users u ON u.id = r.user_id
        LEFT JOIN questionnaire_drafts qd 
          ON u.id::text = qd.user_id::text 
          AND qd.project_id::text = r.project_id::text
          AND qd.questionnaire_id = 'peer_review'
        WHERE r.project_id = $1
          AND r.assessment_type = 'selbstbewertung'
          AND r.question_id LIKE $2
          AND r.response_value IS NOT NULL
          AND r.response_value != ''
          AND r.response_value != 'N/A'
          AND r.response_value NOT IN ('Ja', 'Nein')
      ")
          
          stats_data <- DBI::dbGetQuery(con, stats_query, 
                                        params = list(project_id, paste0(topic_prefix, "%")))
          
          if (nrow(stats_data) == 0) {
            return(data.frame(
              Frage = character(0),
              n_gesamt = numeric(0),
              Mittelwert = numeric(0),
              Min = numeric(0),
              Max = numeric(0),
              Berufsgruppen = character(0)
            ))
          }
          
          # Expand by group_size
          expanded_list <- lapply(1:nrow(stats_data), function(i) {
            row <- stats_data[i, ]
            gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
            data.frame(
              question_id = rep(row$question_id, gs),
              rv = rep(row$rv, gs),
              berufsgruppe = rep(row$berufsgruppe, gs),
              stringsAsFactors = FALSE
            )
          })
          
          expanded <- do.call(rbind, expanded_list)
          
          # Get unique questions
          unique_questions <- sort(unique(expanded$question_id))
          
          # Calculate statistics per question
          result <- lapply(unique_questions, function(qid) {
            q_data <- expanded[expanded$question_id == qid, ]
            
            # Overall stats
            n_total <- nrow(q_data)
            mean_val <- mean(q_data$rv, na.rm = TRUE)
            min_val <- min(q_data$rv, na.rm = TRUE)
            max_val <- max(q_data$rv, na.rm = TRUE)
            
            # Berufsgruppe breakdown
            bg_stats <- aggregate(rv ~ berufsgruppe, data = q_data, FUN = function(x) {
              sprintf("Ø %.1f (n=%d)", mean(x), length(x))
            })
            
            bg_text <- paste(
              paste0(bg_stats$berufsgruppe, ": ", bg_stats$rv),
              collapse = "; "
            )
            
            data.frame(
              Frage = qid,
              n_gesamt = n_total,
              Mittelwert = round(mean_val, 2),
              Min = min_val,
              Max = max_val,
              Berufsgruppen = bg_text,
              stringsAsFactors = FALSE
            )
          })
          
          do.call(rbind, result)
        }
        
        # Generate all stats
        message("  Generating enhanced statistics...")
        
        fuehrung_stats_result <- get_enhanced_stats("F")
        write.csv(fuehrung_stats_result, "fuehrung_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        mitarbeitende_stats_result <- get_enhanced_stats("M")
        write.csv(mitarbeitende_stats_result, "mitarbeitende_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        pat_stats_result <- get_enhanced_stats("P")
        write.csv(pat_stats_result, "pat_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        ein_stats_result <- get_enhanced_stats("E")
        write.csv(ein_stats_result, "ein_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        qual_stats_result <- get_enhanced_stats("Q")
        write.csv(qual_stats_result, "qual_stats.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        # Summary
        total_questions <- nrow(fuehrung_stats_result) + nrow(mitarbeitende_stats_result) + 
          nrow(pat_stats_result) + nrow(ein_stats_result) + nrow(qual_stats_result)
        
        message("  ✓ Enhanced stats created for ", total_questions, " questions across 5 topics")
        
        # ===== PLOTS =====
        message("\nStep 7: Plots (Single Average + Overlay by Berufsgruppe)")
        
        mit_binary_global_qnums <- c(10, 20, 24)
        
        # ✅ FUNCTION 1: Create single average plot (existing)
        create_single_plot <- function(name, questions, title, colour, binary_qnums = integer(0)) {
          plot_file <- paste0("plot_", name, ".png")
          
          tryCatch({
            message("  Creating single plot: ", title)
            
            questions_filtered <- if (length(binary_qnums) > 0) {
              Filter(function(q) !(q$number %in% binary_qnums), questions)
            } else {
              questions
            }
            
            question_ids <- sapply(questions_filtered, function(q) q$id)
            
            if (length(question_ids) == 0) {
              message("    ⚠ No questions")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Fragen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Get weighted responses
            responses <- DBI::dbGetQuery(con, sprintf(
              "SELECT 
        r.question_id, 
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd 
        ON u.id::text = qd.user_id::text 
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1 
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s) 
        AND r.response_value IS NOT NULL 
        AND r.response_value != ''
        AND r.response_value != 'N/A'
        AND r.response_value NOT IN ('Ja', 'Nein')"
              ,
              paste0("'", question_ids, "'", collapse = ", ")
            ), params = list(project_id))
            
            if (nrow(responses) == 0) {
              message("    ⚠ No data")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Daten", cex = 1.5)
              dev.off()
              return()
            }
            
            # Expand by group_size
            expanded_list <- lapply(1:nrow(responses), function(i) {
              row <- responses[i, ]
              gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
              data.frame(
                question_id = rep(row$question_id, gs),
                rv = rep(row$rv, gs)
              )
            })
            expanded <- do.call(rbind, expanded_list)
            
            # Calculate means
            means <- aggregate(rv ~ question_id, data = expanded, FUN = mean)
            
            values <- sapply(questions_filtered, function(q) {
              row <- means[means$question_id == q$id, ]
              if (nrow(row) > 0) row$rv else 0
            })
            
            labels <- sapply(questions_filtered, function(q) as.character(q$number))
            
            # Build radar data frame
            radar_df <- data.frame(matrix(nrow = 3, ncol = length(values)))
            radar_df[1, ] <- 5
            radar_df[2, ] <- 0
            radar_df[3, ] <- values
            colnames(radar_df) <- labels
            
            # Use ggplot2 radar
            make_ggplot_radar_png(radar_df, title, colour, plot_file, 800, 800)
            message("  ✓ ", title)
            
          }, error = function(e) {
            message("  ✗ ", title, " ERROR: ", e$message)
            png(plot_file, width = 800, height = 800)
            plot.new()
            text(0.5, 0.5, "Fehler", cex = 1.5)
            dev.off()
          })
        }
        
        # ✅ FUNCTION 2: Create overlay plot (by Berufsgruppe)
        create_overlay_plot <- function(name, questions, title, binary_qnums = integer(0)) {
          plot_file <- paste0("plot_overlay_", name, ".png")
          
          tryCatch({
            message("  Creating overlay plot: ", title)
            
            questions_filtered <- if (length(binary_qnums) > 0) {
              Filter(function(q) !(q$number %in% binary_qnums), questions)
            } else {
              questions
            }
            
            question_ids <- sapply(questions_filtered, function(q) q$id)
            
            if (length(question_ids) == 0) {
              message("    ⚠ No questions")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Fragen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Get responses with Berufsgruppe
            responses <- DBI::dbGetQuery(con, sprintf(
              "SELECT 
        r.question_id, 
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd 
        ON u.id::text = qd.user_id::text 
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1 
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s) 
        AND r.response_value IS NOT NULL 
        AND r.response_value != ''
        AND r.response_value != 'N/A'
        AND r.response_value NOT IN ('Ja', 'Nein')
              
              ",
              paste0("'", question_ids, "'", collapse = ", ")
            ), params = list(project_id))
            
            if (nrow(responses) == 0) {
              message("    ⚠ No data")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Daten", cex = 1.5)
              dev.off()
              return()
            }
            
            # Expand by group_size
            expanded_list <- lapply(1:nrow(responses), function(i) {
              row <- responses[i, ]
              gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
              data.frame(
                question_id = rep(row$question_id, gs),
                rv = rep(row$rv, gs),
                berufsgruppe = rep(row$berufsgruppe, gs),
                stringsAsFactors = FALSE
              )
            })
            expanded <- do.call(rbind, expanded_list)
            
            # Calculate means per question per berufsgruppe
            means <- aggregate(rv ~ question_id + berufsgruppe, data = expanded, FUN = mean)
            
            # Get unique berufsgruppen
            berufsgruppen <- unique(means$berufsgruppe)
            
            if (length(berufsgruppen) == 0) {
              message("    ⚠ No berufsgruppen")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Berufsgruppen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Colors
            bg_colors <- c(
              "MTL" = "#1f77b4",
              "Wissenschaftler(-in)" = "#ff7f0e",
              "Ärzte" = "#2ca02c",
              "IT" = "#d62728",
              "nicht anwendbar" = "#9467bd",
              "Nicht angegeben" = "#8c564b"
            )
            
            # Create ggplot2 overlay
            library(ggplot2)
            
            labels <- sapply(questions_filtered, function(q) as.character(q$number))
            n <- length(labels)
            angles <- seq(0, 2*pi, length.out = n + 1)[1:n]
            
            to_cartesian <- function(r, angle) {
              list(x = r * sin(angle), y = r * cos(angle))
            }
            
            # Create polygons for each berufsgruppe
            all_polygons <- lapply(berufsgruppen, function(bg) {
              bg_data <- means[means$berufsgruppe == bg, ]
              
              values <- sapply(questions_filtered, function(q) {
                row <- bg_data[bg_data$question_id == q$id, ]
                if (nrow(row) > 0) row$rv else 0
              })
              
              polygon_coords <- lapply(1:n, function(i) {
                coords <- to_cartesian(values[i], angles[i])
                data.frame(x = coords$x, y = coords$y)
              })
              polygon_df <- do.call(rbind, polygon_coords)
              polygon_df <- rbind(polygon_df, polygon_df[1, ])
              polygon_df$berufsgruppe <- bg
              
              return(polygon_df)
            })
            
            all_polygons_df <- do.call(rbind, all_polygons)
            
            # Grid circles
            grid_circles <- lapply(0:5, function(r) {
              angle_seq <- seq(0, 2*pi, length.out = 100)
              coords <- lapply(angle_seq, function(a) to_cartesian(r, a))
              data.frame(
                x = sapply(coords, function(c) c$x),
                y = sapply(coords, function(c) c$y),
                r = r
              )
            })
            grid_df <- do.call(rbind, grid_circles)
            
            # Axis lines
            axis_lines <- lapply(1:n, function(i) {
              coords <- to_cartesian(5.5, angles[i])
              data.frame(x = 0, y = 0, xend = coords$x, yend = coords$y)
            })
            axis_df <- do.call(rbind, axis_lines)
            
            # Labels
            label_coords <- lapply(1:n, function(i) {
              coords <- to_cartesian(6.2, angles[i])
              data.frame(x = coords$x, y = coords$y, label = labels[i])
            })
            label_df <- do.call(rbind, label_coords)
            
            # Create plot
            p <- ggplot() +
              geom_path(data = grid_df, aes(x = x, y = y, group = r), 
                        color = "grey85", linewidth = 0.5) +
              geom_text(data = data.frame(x = 0, y = 0:5, label = 0:5),
                        aes(x = x, y = y, label = label),
                        color = "grey50", size = 3, hjust = 1.5) +
              geom_segment(data = axis_df, 
                           aes(x = x, y = y, xend = xend, yend = yend),
                           color = "grey70", linewidth = 0.5) +
              geom_polygon(data = all_polygons_df, 
                           aes(x = x, y = y, fill = berufsgruppe, color = berufsgruppe, group = berufsgruppe),
                           alpha = 0.2, linewidth = 1.2) +
              geom_point(data = all_polygons_df[!duplicated(paste(all_polygons_df$berufsgruppe, all_polygons_df$x, all_polygons_df$y)), ],
                         aes(x = x, y = y, color = berufsgruppe),
                         size = 2.5) +
              geom_text(data = label_df, aes(x = x, y = y, label = label), 
                        size = 3.5, fontface = "bold") +
              scale_fill_manual(values = bg_colors, name = "Berufsgruppe") +
              scale_color_manual(values = bg_colors, name = "Berufsgruppe") +
              ggtitle(title) +
              coord_fixed() +
              xlim(c(-7, 7)) +
              ylim(c(-7, 7)) +
              theme_void() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold", margin = margin(b = 10)),
                legend.position = "bottom",
                legend.title = element_text(size = 12, face = "bold"),
                legend.text = element_text(size = 10)
              )
            
            ggsave(plot_file, p, width = 800/120, height = 800/120, dpi = 120)
            message("  ✓ ", title, " (Overlay)")
            
          }, error = function(e) {
            message("  ✗ ", title, " (Overlay) ERROR: ", e$message)
            png(plot_file, width = 800, height = 800)
            plot.new()
            text(0.5, 0.5, "Fehler", cex = 1.5)
            dev.off()
          })
        }
        
        # ✅ CREATE BOTH TYPES OF PLOTS
        message("  Single average plots:")
        create_single_plot("fuehrung", fuehrung_questions, "Führung", "#003B73")
        create_single_plot("mit", mit_questions, "Mitarbeitende", "#136377", mit_binary_global_qnums)
        create_single_plot("pat", pat_questions, "Patienten", "#b23a48")
        create_single_plot("ein", ein_questions, "Einsender", "#4b61d1")
        create_single_plot("qual", qual_questions, "Qualität", "#c58f00")
        
        message("  Overlay plots (by Berufsgruppe):")
        create_overlay_plot("fuehrung", fuehrung_questions, "Führung - nach Berufsgruppe")
        create_overlay_plot("mit", mit_questions, "Mitarbeitende - nach Berufsgruppe", mit_binary_global_qnums)
        create_overlay_plot("pat", pat_questions, "Patienten - nach Berufsgruppe")
        create_overlay_plot("ein", ein_questions, "Einsender - nach Berufsgruppe")
        create_overlay_plot("qual", qual_questions, "Qualität - nach Berufsgruppe")
        
        message("  ✓ All plots created")
        
        # ===== RENDER PDF =====
        message("\nStep 8: Render PDF")
        
        output_file <- rmarkdown::render(
          input = template_file,
          output_format = rmarkdown::pdf_document(
            toc = TRUE,
            toc_depth = 2,
            number_sections = FALSE,
            keep_tex = FALSE,
            latex_engine = "pdflatex"
          ),
          output_file = "report.pdf",
          output_dir = tmpdir,
          params = list(
            project_title = project_title,
            project_id = project_id
          ),
          envir = new.env(),
          quiet = FALSE,
          encoding = "UTF-8"
        )
        
        message("  ✓ PDF: ", file.size(output_file), " bytes")
        
        # Copy to destination
        message("\nStep 9: Copy PDF")
        file.copy(output_file, file, overwrite = TRUE)
        
        removeNotification("pdf_progress")
        showNotification(
          "PDF erfolgreich erstellt!",
          type = "message",
          duration = 5
        )
        
        message("\n### SUCCESS ###\n")
        
      }, error = function(e) {
        message("\n### ERROR ###")
        message("Message: ", e$message)
        message("\nCall stack:")
        print(sys.calls())
        
        removeNotification("pdf_progress")
        showNotification(
          paste("Fehler:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler beim Erstellen des Berichts:\n\n", e$message), file)
      })
    },
    
    contentType = "application/pdf"
  )
  
  #--------------Downloadhandler for leading peer---------------------------
  
  #============================================================================
  # HELPER FUNCTIONS FOR REPORTS
  #============================================================================
  
  # ✅ ADD: Load report field from database
  load_report_field <- function(field_name) {
    
    project_id <- current_project_id()
    
    if (is.null(project_id) || project_id == "") {
      return("")
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      
      # Check if report_data table exists
      table_exists <- DBI::dbExistsTable(con, "report_data")
      
      if (!table_exists) {
        message("  report_data table does not exist")
        return("")
      }
      
      # Get field value
      result <- DBI::dbGetQuery(con, "
      SELECT field_value 
      FROM report_data 
      WHERE project_id = $1 
        AND field_name = $2
      LIMIT 1
    ", params = list(as.character(project_id), field_name))
      
      if (nrow(result) > 0 && !is.na(result$field_value[1])) {
        return(as.character(result$field_value[1]))
      } else {
        return("")
      }
      
    }, error = function(e) {
      message("  Error loading field '", field_name, "': ", e$message)
      return("")
    })
  }

  #============================================================================
  # HELPER: Get Fremdbewertung for a specific user
  #============================================================================
  
  get_fremdbewertung_for_user <- function(project_id, user_id) {
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    message("  get_fremdbewertung_for_user called")
    message("    project_id: ", project_id)
    message("    user_id: ", user_id)
    
    # Query to get fremdbewertung responses for this user
    query <- "
    SELECT 
      r.question_id,
      r.response_value,
      r.text_value
    FROM responses r
    WHERE r.project_id = $1
      AND r.user_id = $2
      AND r.assessment_type = 'fremdbewertung'
    ORDER BY r.question_id
  "
    
    fremd_raw <- DBI::dbGetQuery(con, query, 
                                 params = list(as.character(project_id), 
                                               as.integer(user_id)))
    
    message("    Found ", nrow(fremd_raw), " fremdbewertung responses")
    
    if (nrow(fremd_raw) == 0) {
      return(data.frame(
        Section = character(0),
        question_id = character(0),
        Frage = character(0),
        Antwort = character(0),
        Begründung = character(0),
        stringsAsFactors = FALSE
      ))
    }
    
    # Map question IDs to sections and labels
    all_questions <- c(
      fuehrung_questions, 
      mit_questions, 
      pat_questions, 
      ein_questions, 
      qual_questions
    )
    
    # Create lookup
    q_lookup <- list()
    for (q in all_questions) {
      prefix <- substr(q$id, 1, 1)
      section <- switch(prefix,
                        "F" = "fuehrung",
                        "M" = "mitarbeitende",
                        "P" = "patienten",
                        "E" = "einsender",
                        "Q" = "qualitaet",
                        "unknown")
      
      q_lookup[[q$id]] <- list(
        section = section,
        label = q$label
      )
    }
    
    # Build result dataframe
    result <- lapply(1:nrow(fremd_raw), function(i) {
      row <- fremd_raw[i, ]
      qid <- row$question_id
      
      q_info <- q_lookup[[qid]]
      
      data.frame(
        Section = if (!is.null(q_info)) q_info$section else "unknown",
        question_id = qid,
        Frage = if (!is.null(q_info)) q_info$label else qid,
        Antwort = if (!is.na(row$response_value)) as.character(row$response_value) else "",
        Begründung = if (!is.na(row$text_value)) as.character(row$text_value) else "",
        stringsAsFactors = FALSE
      )
    })
    
    final_df <- do.call(rbind, result)
    
    message("    Returning ", nrow(final_df), " rows")
    
    return(final_df)
  }
  
  # Helper function
  get_fremdbewertung_section <- function(questions) {
    data.frame(
      Frage     = sapply(questions, function(q) q$label),
      Bewertung = sapply(questions, function(q) {
        val <- input[[paste0("FremdbewertungNum_", q$id)]]
        if (is.null(val) || length(val) == 0) "" else as.character(val)
      }),
      Kommentar = sapply(questions, function(q) {
        val <- input[[paste0("FremdbewertungText_", q$id)]]
        if (is.null(val) || length(val) == 0) "" else as.character(val)
      }),
      stringsAsFactors = FALSE
    )
  }
  
  #---------------------fremdbewertung download handler (leading peer)----------
  
  output$downloadFremdbewertung <- downloadHandler(
    filename = function() paste0("fremdbewertung_", format(Sys.Date(), "%Y%m%d"), ".pdf"),
    content  = function(file) {
      
      message("=== Fremdbewertung Download started ===")
      
      # Use .Rmd file
      template_file <- "fremdbewertung_report.Rmd"
      
      if (!file.exists(template_file)) {
        showNotification("Template nicht gefunden.", type = "error", duration = 10)
        writeLines("Template nicht verfügbar.", file)
        return(NULL)
      }
      
      tryCatch({
        
        message("Step 1: Getting template path")
        template_path <- normalizePath(template_file, mustWork = TRUE)
        
        message("Step 2: Changing to temp directory")
        tmpdir <- tempdir()
        owd <- setwd(tmpdir)
        on.exit(setwd(owd), add = TRUE)
        
        message("Step 3: Copying template to temp dir")
        file.copy(template_path, file.path(tmpdir, template_file), overwrite = TRUE)
        
        message("Step 4: Getting project ID and user ID")
        project_id <- current_project_id()
        user_id <- user_id()
        
        if (is.null(project_id) || is.null(user_id)) {
          showNotification("Kein Projekt oder Benutzer gefunden.", type = "error")
          return(NULL)
        }
        message("  Project ID: ", project_id)
        message("  User ID: ", user_id)
        
        message("Step 5: Getting Fremdbewertung from database")
        
        # Get ONLY this user's Fremdbewertung from database
        fremd_data <- get_fremdbewertung_for_user(project_id, user_id)
        
        message("  Found ", nrow(fremd_data), " responses")
        
        if (nrow(fremd_data) == 0) {
          showNotification(
            "Sie haben noch keine Fremdbewertung abgegeben.",
            type = "warning",
            duration = 5
          )
          writeLines("Keine Fremdbewertung vorhanden.", file)
          return(NULL)
        }
        
        message("Step 6: Saving Fremdbewertung to CSV")
        write.csv(fremd_data, file.path(tmpdir, "user_fremdbewertung.csv"), 
                  row.names = FALSE, fileEncoding = "UTF-8")
        
        message("  ✓ CSV saved")
        
        message("Step 7: Rendering PDF")
        
        # Render PDF using rmarkdown
        output_file <- rmarkdown::render(
          input = file.path(tmpdir, template_file),
          output_format = "pdf_document",
          output_file = "fremdbewertung_report.pdf",
          output_dir = tmpdir,
          envir = new.env(),
          quiet = FALSE
        )
        
        message("Step 8: Moving PDF to destination")
        file.copy(output_file, file, overwrite = TRUE)
        
        message("=== Fremdbewertung Download completed successfully ===")
        
        showNotification(
          "Fremdbewertung Bericht erfolgreich erstellt!",
          type = "message",
          duration = 5
        )
        
      }, error = function(e) {
        message("=== ERROR ===")
        message(paste("  Message:", e$message))
        
        showNotification(
          paste("Fehler beim Erstellen des Berichts:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
  
  
  #------- FREMDBEWERTUNG SUBMISSION OBSERVERS (For Leading Peer & Co-Peer)-------
  
  
  #-------------- FREMDBEWERTUNG SUBMISSION SYSTEM ---------------
  
  submit_fremdbewertung_topic <- function(topic_prefix, questions_list, topic_name, status_output) {
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    submission_id <- uuid::UUIDgenerate()
    
    message("\n=== SUBMIT FREMDBEWERTUNG: ", topic_name, " ===")
    message("User: ", current_user_id, " (", user_role(), ")")
    message("Project: ", project_id)
    
    if (is.null(project_id) || project_id == "" || is.na(project_id)) {
      showNotification("Fehler: Kein Projekt ausgewählt!", type = "error")
      return(invisible(FALSE))
    }
    
    tag_value <- get_submission_tag()
    
    # Collect responses for this topic
    responses_list <- list()
    
    for (q in questions_list) {
      qid <- q$id
      score_id <- paste0("FremdbewertungNum_", qid)
      text_id <- paste0("FremdbewertungText_", qid)
      
      score <- input[[score_id]]
      text <- input[[text_id]]
      
      if (!is.null(score) && score != "" && score != "N/A") {
        responses_list[[length(responses_list) + 1]] <- list(
          user_id = as.integer(current_user_id),  # ✅ FIX: INTEGER
          question_id = qid,
          response_value = as.character(score),
          text_value = if (!is.null(text) && text != "") as.character(text) else NA_character_,
          tag = tag_value,
          assessment_type = "fremdbewertung",
          submission_id = submission_id,
          project_id = as.character(project_id),
          group_size = 1L
        )
      }
    }
    
    if (length(responses_list) == 0) {
      showNotification("Keine Antworten zum Speichern gefunden.", type = "warning")
      output[[status_output]] <- renderUI(
        div(style = "color:orange;margin-top:12px;", "⚠ Keine Antworten gefunden.")
      )
      return(invisible(FALSE))
    }
    
    message("Collected ", length(responses_list), " responses for ", topic_name)
    
    # Save to database
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      sql <- "
      INSERT INTO responses (
        user_id, project_id, question_id, response_value, text_value, 
        tag, assessment_type, submission_id, group_size, created_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW())
    "
      
      inserted <- 0
      
      for (resp in responses_list) {
        DBI::dbExecute(con, sql, params = list(
          resp$user_id,          # INTEGER
          resp$project_id,
          resp$question_id,
          resp$response_value,
          resp$text_value,
          resp$tag,
          resp$assessment_type,
          resp$submission_id,
          resp$group_size
        ))
        inserted <- inserted + 1
      }
      
      message("✓ Saved ", inserted, " responses for ", topic_name)
      message("✓ Submission ID: ", submission_id)
      message("=== SUCCESS ===\n")
      
      showNotification(
        paste0(topic_name, " Fremdbewertung erfolgreich abgesendet! (", inserted, " Antworten)"),
        type = "message",
        duration = 5
      )
      
      output[[status_output]] <- renderUI(
        div(style = "color:green;margin-top:12px;font-weight:bold;",
            icon("check-circle"), " Erfolgreich abgesendet!")
      )
      
      return(invisible(TRUE))
      
    }, error = function(e) {
      message("ERROR: ", e$message)
      showNotification(
        paste("Fehler beim Speichern:", e$message),
        type = "error",
        duration = 10
      )
      
      output[[status_output]] <- renderUI(
        div(style = "color:red;margin-top:12px;", "✗ Fehler beim Speichern!")
      )
      
      return(invisible(FALSE))
    })
  }
  
  submit_all_fremdbewertung <- function() {
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    submission_id <- uuid::UUIDgenerate()
    questionnaire_id <- "peer_fremdbewertung"
    
    message("\n========== SUBMIT ALL FREMDBEWERTUNG ==========")
    message("User: ", current_user_id, " (", user_role(), ")")
    message("Project: ", project_id)
    message("Submission ID: ", submission_id)
    
    if (is.null(project_id) || project_id == "" || is.na(project_id)) {
      showNotification("Fehler: Kein Projekt ausgewählt!", type = "error", duration = 5)
      return(invisible(FALSE))
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    # Load draft
    draft <- DBI::dbGetQuery(
      con,
      "SELECT answers, status FROM questionnaire_drafts
     WHERE user_id::text = $1::text 
     AND project_id::text = $2::text 
     AND questionnaire_id = $3 
     ORDER BY last_saved DESC LIMIT 1",
      params = list(as.character(current_user_id), as.character(project_id), questionnaire_id)
    )
    
    if (nrow(draft) == 0) {
      message("❌ No draft found")
      showNotification("Kein Entwurf gefunden.", type = "warning", duration = 5)
      return(invisible(FALSE))
    }
    
    if (draft$status[1] == "submitted") {
      message("❌ Already submitted")
      showNotification("Diese Fremdbewertung wurde bereits abgeschickt!", type = "warning", duration = 5)
      return(invisible(FALSE))
    }
    
    # Parse draft
    saved_answers <- jsonlite::fromJSON(draft$answers[1])
    message("✓ Loaded draft with ", length(saved_answers), " fields")
    
    # Convert to responses
    responses_list <- list()
    
    all_questions <- c(
      fuehrung_questions,
      mit_questions,
      pat_questions,
      ein_questions,
      qual_questions
    )
    
    message("Processing ", length(all_questions), " questions...")
    
    processed <- 0
    skipped_na <- 0
    skipped_empty <- 0
    
    for (q in all_questions) {
      qid <- q$id
      score_key <- paste0("FremdbewertungNum_", qid)
      text_key <- paste0("FremdbewertungText_", qid)
      
      if (score_key %in% names(saved_answers)) {
        score <- saved_answers[[score_key]]
        text <- if (text_key %in% names(saved_answers)) saved_answers[[text_key]] else ""
        
        # Debug first few
        if (processed < 5) {
          message("  ", qid, ": score=", score, ", text=", if(!is.null(text) && nchar(text) > 0) "yes" else "no")
        }
        
        if (is.null(score) || score == "") {
          skipped_empty <- skipped_empty + 1
          next
        }
        
        if (score == "N/A") {
          skipped_na <- skipped_na + 1
          next
        }
        
        responses_list[[length(responses_list) + 1]] <- list(
          user_id = as.integer(current_user_id),  # ✅ FIX: Convert to INTEGER
          question_id = qid,
          response_value = as.character(score),
          text_value = if (!is.null(text) && text != "") as.character(text) else NA_character_,
          tag = NA_character_,
          assessment_type = "fremdbewertung",
          submission_id = submission_id,
          project_id = as.character(project_id),
          group_size = 1L
        )
        
        processed <- processed + 1
      }
    }
    
    message("✓ Processed: ", processed)
    message("  Skipped (empty): ", skipped_empty)
    message("  Skipped (N/A): ", skipped_na)
    message("  Total to insert: ", length(responses_list))
    
    if (length(responses_list) == 0) {
      message("❌ No responses to insert")
      showNotification("Keine Antworten zum Abschicken gefunden.", type = "warning", duration = 5)
      return(invisible(FALSE))
    }
    
    # Check for existing
    existing <- DBI::dbGetQuery(
      con,
      "SELECT COUNT(*) as count FROM responses 
     WHERE user_id = $1 
     AND project_id::text = $2::text 
     AND assessment_type = 'fremdbewertung'",
      params = list(as.integer(current_user_id), as.character(project_id))
    )
    
    if (existing$count > 0) {
      message("⚠ User already has ", existing$count, " responses")
      showModal(modalDialog(
        title = "Fremdbewertung bereits abgegeben",
        paste0("Sie haben bereits ", existing$count, " Antworten abgegeben. Überschreiben?"),
        footer = tagList(
          modalButton("Abbrechen"),
          actionButton("confirm_overwrite_fremd", "Ja, überschreiben", class = "btn-danger")
        )
      ))
      return(invisible(FALSE))
    }
    
    # Insert responses
    message("\n--- STARTING INSERT ---")
    
    tryCatch({
      
      sql <- "
      INSERT INTO responses (
        user_id, project_id, question_id, response_value, text_value,
        assessment_type, submission_id, tag, group_size, created_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW())
    "
      
      inserted <- 0
      
      for (i in 1:length(responses_list)) {
        resp <- responses_list[[i]]
        
        DBI::dbExecute(con, sql, params = list(
          resp$user_id,          # INTEGER
          resp$project_id,       # TEXT
          resp$question_id,      # TEXT
          resp$response_value,   # TEXT
          resp$text_value,       # TEXT
          resp$assessment_type,  # TEXT
          resp$submission_id,    # TEXT
          resp$tag,              # TEXT
          resp$group_size        # INTEGER
        ))
        
        inserted <- inserted + 1
        
        if (inserted <= 5 || inserted == length(responses_list)) {
          message("  ✓ Inserted ", resp$question_id, ": ", resp$response_value)
        }
      }
      
      message("--- INSERT COMPLETE ---")
      message("✓ Total inserted: ", inserted, " responses")
      
      # Mark draft as submitted
      DBI::dbExecute(
        con,
        "UPDATE questionnaire_drafts 
       SET status = 'submitted', last_saved = NOW()
       WHERE user_id::text = $1::text 
       AND project_id::text = $2::text 
       AND questionnaire_id = $3",
        params = list(as.character(current_user_id), as.character(project_id), questionnaire_id)
      )
      
      message("✓ Draft marked as submitted")
      message("========== SUCCESS ==========\n")
      
      showNotification(
        paste0("✅ Fremdbewertung erfolgreich abgesendet! (", inserted, " Antworten)"),
        type = "message",
        duration = 8
      )
      
      return(invisible(TRUE))
      
    }, error = function(e) {
      message("❌❌❌ ERROR during INSERT:")
      message(e$message)
      print(e)
      
      showNotification(
        paste("❌ Fehler:", e$message),
        type = "error",
        duration = 15
      )
      
      return(invisible(FALSE))
    })
  }
  
  # ✅ Overwrite confirmation handler
  observeEvent(input$confirm_overwrite_fremd, {
    removeModal()
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    
    message("\n=== OVERWRITING EXISTING FREMDBEWERTUNG ===")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    tryCatch({
      # Delete old responses
      deleted <- DBI::dbExecute(
        con,
        "DELETE FROM responses 
       WHERE user_id = $1 
       AND project_id::text = $2::text 
       AND assessment_type = 'fremdbewertung'",
        params = list(as.integer(current_user_id), as.character(project_id))
      )
      
      message("✓ Deleted ", deleted, " old responses")
      
      # Reset draft to allow resubmission
      DBI::dbExecute(
        con,
        "UPDATE questionnaire_drafts 
       SET status = 'draft'
       WHERE user_id::text = $1::text 
       AND project_id::text = $2::text 
       AND questionnaire_id = 'peer_fremdbewertung'",
        params = list(as.character(current_user_id), as.character(project_id))
      )
      
      # Now submit new responses
      submit_all_fremdbewertung()
      
    }, error = function(e) {
      message("❌ ERROR during overwrite: ", e$message)
      showNotification(
        paste("Fehler beim Überschreiben:", e$message),
        type = "error",
        duration = 10
      )
    })
  }, ignoreInit = TRUE)
  
  
  
  #-------------- OBSERVERS FOR EACH TOPIC ---------------
  
  # Individual topic submit buttons (optional - if you want per-topic submission)
  observeEvent(input$submit_peer_fremdbewertung_fuehrung, {
