#---------------------------Co-Peer - Fremdbewertung----------------------------

  # Co-Peer Own Fremdbewertung (ONLY Fremdbewertung, no Selbstbewertung)
  output$downloadCoPeerFremdbewertung <- downloadHandler(
    filename = function() {
      paste0("meine_fremdbewertung_", format(Sys.Date(), "%Y%m%d"), ".pdf")
    },
    
    content = function(file) {
      
      message("=== Co-Peer Fremdbewertung Download started ===")
      
      user_id <- user_id()  
      project_id <- current_project_id()
      
      if (is.null(user_id) || is.null(project_id)) {
        showNotification("Fehler: Kein Benutzer oder Projekt", type = "error")
        return(NULL)
      }
      
      template_file <- "fremdbewertung_report.Rmd"
      
      if (!file.exists(template_file)) {
        showNotification("Template nicht gefunden.", type = "error", duration = 10)
        writeLines("Template nicht verfügbar.", file)
        return(NULL)
      }
      
      tryCatch({
        
        message("Step 1: Setting up temp directory")
        tmpdir <- tempdir()
        owd <- setwd(tmpdir)
        on.exit(setwd(owd), add = TRUE)
        
        message("Step 2: Copying template")
        template_path <- normalizePath(template_file, mustWork = TRUE)
        file.copy(template_path, file.path(tmpdir, template_file), overwrite = TRUE)
        
        message("Step 3: Getting user's Fremdbewertung from database")
        
        # Get ONLY this co-peer's Fremdbewertung
        fremd_data <- get_fremdbewertung_for_user(project_id, user_id)
        
        message("  Found ", nrow(fremd_data), " responses")
        
        if (nrow(fremd_data) == 0) {
          showNotification(
            "Sie haben noch keine Fremdbewertung abgegeben.",
            type = "warning",
            duration = 5
          )
          writeLines("Keine Fremdbewertung vorhanden.", file)
          return(NULL)
        }
        
        message("Step 4: Saving Fremdbewertung to CSV")
        write.csv(fremd_data, file.path(tmpdir, "user_fremdbewertung.csv"), 
                  row.names = FALSE, fileEncoding = "UTF-8")
        
        message("Step 5: Rendering PDF")
        output_file <- rmarkdown::render(
          input = file.path(tmpdir, template_file),
          output_format = "pdf_document",
          output_file = "fremdbewertung_report.pdf",
          output_dir = tmpdir,
          envir = new.env(),
          quiet = FALSE
        )
        
        message("Step 6: Copying PDF to destination")
        file.copy(output_file, file, overwrite = TRUE)
        
        message("=== Co-Peer Fremdbewertung Download completed ===")
        
        showNotification(
          "Ihre Fremdbewertung wurde erfolgreich heruntergeladen!",
          type = "message",
          duration = 5
        )
        
      }, error = function(e) {
        message("ERROR: ", e$message)
        showNotification(
          paste("Fehler beim Erstellen der Fremdbewertung:", e$message),
          type = "error",
          duration = 10
        )
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
