  # ============================================
  # PDF DOWNLOAD - FIXED FOR YOUR SCHEMA
  # ============================================
  
  output$download_user_pdf <- downloadHandler(
    filename = function() {
      req(input$admin_export_user)
      uid <- input$admin_export_user
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con))
      username <- DBI::dbGetQuery(
        con,
        "SELECT username FROM users WHERE id = $1",
        params = list(as.integer(uid))
      )$username
      
      paste0("antworten_", username, "_", Sys.Date(), ".pdf")
    },
    
    content = function(file) {
      req(user_role() == "admin")
      req(input$admin_export_user)
      
      showNotification("PDF wird erstellt...", type = "message", duration = NULL, id = "pdf_progress")
      
      uid <- as.integer(input$admin_export_user)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # Get user info
      user_info <- DBI::dbGetQuery(
        con,
        "SELECT 
        u.id,
        u.username,
        u.role,
        u.assessment_type,
        p.title as project_name
      FROM users u
      LEFT JOIN projects p ON u.project_id = p.id
      WHERE u.id = $1",
        params = list(uid)
      )
      
      # Get responses
      responses <- DBI::dbGetQuery(
        con,
        "SELECT 
        question_id,
        response_value,
        text_value,
        assessment_type,
        created_at
      FROM responses 
      WHERE user_id = $1 
      ORDER BY question_id",
        params = list(uid)
      )
      
      # Get drafts
      drafts <- DBI::dbGetQuery(
        con,
        "SELECT 
        questionnaire_id,
        status,
        last_saved
      FROM questionnaire_drafts 
      WHERE user_id = $1 
      ORDER BY last_saved DESC",
        params = list(as.character(uid))
      )
      
      tryCatch({
        
        rmarkdown::render(
          input = "user_answers_export_template.Rmd",
          output_file = file,
          params = list(
            user_info = user_info,
            responses = responses,
            drafts = drafts
          ),
          envir = new.env(),
          quiet = TRUE
        )
        
        removeNotification("pdf_progress")
        showNotification("✓ PDF erstellt!", type = "message", duration = 3)
        
      }, error = function(e) {
        removeNotification("pdf_progress")
        showNotification(paste("Fehler:", e$message), type = "error", duration = 10)
        message("PDF ERROR: ", e$message)
      })
    }
  )
  
  
  #----colour scheme---------
  
  # ✅ Updated color definitions for all three plot types
  SPIDER_COLORS <- list(
    # Berufsgruppe breakdown colors (for Selbstbewertung plot)
    berufsgruppe = c("#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd", 
                     "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf"),
    
    # Fremdbewertung peer colors (distinct from berufsgruppe)
    peers = c(
      "Peer 1" = "#9C27B0",  # Purple
      "Peer 2" = "#FF5722",  # Deep Orange
      "Peer 3" = "#00BCD4",  # Cyan
      "Peer 4" = "#FFC107"   # Amber
    ),
    
    # Overlay colors (Selbst average + individual peers)
    overlay = c(
      "Selbstbewertung" = "#4CAF50",  # Green
      "Peer 1" = "#9C27B0",           # Purple (matches Fremdbewertung)
      "Peer 2" = "#FF5722",           # Deep Orange (matches Fremdbewertung)
      "Peer 3" = "#00BCD4",           # Cyan
      "Peer 4" = "#FFC107"            # Amber
    )
  )

  #---------------comparison table of the Selbst- vs. Fremdbewertung-------------
  
  # Download comparison table
  output$download_comparison_pdf <- downloadHandler(
    filename = function() {
      paste0("Vergleichstabelle_", Sys.Date(), ".pdf")
    },
    content = function(file) {
      
      req(user_logged_in())
      req(user_role() %in% c("admin", "leading_peer"))
      
      project_id <- current_project_id()
      
      if (is.null(project_id) || project_id == "") {
        showNotification("Kein Projekt ausgewählt!", type = "error", duration = 5)
        return(NULL)
      }
      
      generate_comparison_pdf(file, project_id, user_role())
    }
  )
  
  # ✅ MATCH: Selbstbewertung spider plot matching create_ggplot_overlay_radar style
  create_spider_plot_selbst <- function(project_id, section_name, topic_prefix, topic_label) {
    
    tryCatch({
      
      library(ggplot2)
      library(dplyr)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # Get Selbstbewertung with Berufsgruppe
      query <- "
      SELECT 
        r.question_id,
        COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      LEFT JOIN questionnaire_drafts qd 
        ON r.user_id::text = qd.user_id::text 
        AND r.project_id::text = qd.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
    "
      
      responses <- DBI::dbGetQuery(
        con, 
        query, 
        params = list(as.character(project_id), paste0(topic_prefix, "%"))
      )
      
      if (nrow(responses) == 0) {
        message("  No Selbstbewertung data for ", section_name)
        return(invisible(NULL))
      }
      
      # Expand by group_size
      expanded_list <- lapply(1:nrow(responses), function(i) {
        row <- responses[i, ]
        gs <- if (is.na(row$group_size) || row$group_size < 1) 1 else as.integer(row$group_size)
        
        data.frame(
          question_id = rep(row$question_id, gs),
          rv = rep(row$rv, gs),
          berufsgruppe = rep(row$berufsgruppe, gs),
          stringsAsFactors = FALSE
        )
      })
      
      expanded <- do.call(rbind, expanded_list)
      
      # Calculate means per question per berufsgruppe
      means <- aggregate(rv ~ question_id + berufsgruppe, data = expanded, FUN = mean)
      
      # Get unique berufsgruppen
      berufsgruppen <- unique(means$berufsgruppe)
      
      # ✅ EXACT color mapping from create_ggplot_overlay_radar
      bg_colors <- c(
        "MTL" = "#1f77b4",
        "Wissenschaftler(-in)" = "#ff7f0e",
        "Ärzte" = "#2ca02c",
        "IT" = "#d62728",
        "nicht anwendbar" = "#9467bd",
        "Nicht angegeben" = "#8c564b"
      )
      
      # Extract question numbers
      means$question_num <- as.integer(gsub("\\D", "", means$question_id))
      
      # Get question list for ordering
      all_qnums <- sort(unique(means$question_num))
      n <- length(all_qnums)
      angles <- seq(0, 2*pi, length.out = n + 1)[1:n]
      
      to_cartesian <- function(r, angle) {
        list(x = r * sin(angle), y = r * cos(angle))
      }
      
      # Create polygon data for each berufsgruppe
      all_polygons <- lapply(berufsgruppen, function(bg) {
        bg_data <- means[means$berufsgruppe == bg, ]
        
        # Match to all question numbers
        values <- sapply(all_qnums, function(qnum) {
          row <- bg_data[bg_data$question_num == qnum, ]
          if (nrow(row) > 0) row$rv[1] else 0
        })
        
        # Convert to cartesian
        polygon_coords <- lapply(1:n, function(i) {
          coords <- to_cartesian(values[i], angles[i])
          data.frame(x = coords$x, y = coords$y)
        })
        polygon_df <- do.call(rbind, polygon_coords)
        polygon_df <- rbind(polygon_df, polygon_df[1, ])
        polygon_df$berufsgruppe <- bg
        
        return(polygon_df)
      })
      
      all_polygons_df <- do.call(rbind, all_polygons)
      
      # Grid circles
      grid_circles <- lapply(0:5, function(r) {
        angle_seq <- seq(0, 2*pi, length.out = 100)
        coords <- lapply(angle_seq, function(a) to_cartesian(r, a))
        data.frame(
          x = sapply(coords, function(c) c$x),
          y = sapply(coords, function(c) c$y),
          r = r
        )
      })
      grid_df <- do.call(rbind, grid_circles)
      
      # Axis lines
      axis_lines <- lapply(1:n, function(i) {
        coords <- to_cartesian(5.5, angles[i])
        data.frame(x = 0, y = 0, xend = coords$x, yend = coords$y)
      })
      axis_df <- do.call(rbind, axis_lines)
      
      # Labels (question numbers only)
      labels <- as.character(all_qnums)
      label_coords <- lapply(1:n, function(i) {
        coords <- to_cartesian(6.2, angles[i])
        data.frame(x = coords$x, y = coords$y, label = labels[i])
      })
      label_df <- do.call(rbind, label_coords)
      
      # Create plot
      filename <- paste0("spider_selbst_", section_name, ".png")
      
      png(filename, width = 900, height = 950, res = 120)
      
      p <- ggplot() +
        # Grid circles
        geom_path(data = grid_df, aes(x = x, y = y, group = r), 
                  color = "grey85", linewidth = 0.5) +
        # Grid labels
        geom_text(data = data.frame(x = 0, y = 0:5, label = 0:5),
                  aes(x = x, y = y, label = label),
                  color = "grey50", size = 3, hjust = 1.5) +
        # Axis lines
        geom_segment(data = axis_df, 
                     aes(x = x, y = y, xend = xend, yend = yend),
                     color = "grey70", linewidth = 0.5) +
        # Polygons for each berufsgruppe
        geom_polygon(data = all_polygons_df, 
                     aes(x = x, y = y, fill = berufsgruppe, color = berufsgruppe, group = berufsgruppe),
                     alpha = 0.2, linewidth = 1.2) +
        # Axis labels
        geom_text(data = label_df, aes(x = x, y = y, label = label), 
                  size = 3.5, fontface = "bold") +
        # ✅ EXACT color scales
        scale_fill_manual(values = bg_colors, name = "Berufsgruppe") +
        scale_color_manual(values = bg_colors, name = "Berufsgruppe") +
        # Title
        ggtitle(paste("Selbstbewertung -", topic_label)) +
        coord_fixed() +
        xlim(c(-7, 7)) +
        ylim(c(-7.5, 7)) +
        theme_void() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold", margin = margin(b = 10)),
          legend.position = "bottom",
          legend.title = element_text(size = 12, face = "bold"),
          legend.text = element_text(size = 10),
          plot.margin = margin(10, 10, 40, 10)
        )
      
      print(p)
      
      dev.off()
      
      message("  ✓ Created spider_selbst_", section_name, ".png")
      
    }, error = function(e) {
      message("  ERROR creating Selbstbewertung spider plot: ", e$message)
    })
  }

  # ✅ UPDATED: Fremdbewertung spider plot with "Peer 1" and "Peer 2" labels
  # ✅ UPDATED: Fremdbewertung with new peer colors
  create_spider_plot_fremd <- function(project_id, section_name, topic_prefix, topic_label) {
    
    tryCatch({
      
      library(ggplot2)
      library(dplyr)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      query <- "
      SELECT 
        r.question_id,
        u.username as reviewer,
        AVG(r.response_value::numeric) as avg_rating
      FROM responses r
      JOIN users u ON u.id = r.user_id
      WHERE r.project_id = $1
        AND r.assessment_type = 'fremdbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id, u.username
      ORDER BY r.question_id, u.username
    "
      
      data <- DBI::dbGetQuery(
        con, 
        query, 
        params = list(as.character(project_id), paste0(topic_prefix, "%"))
      )
      
      if (nrow(data) == 0) {
        message("  No Fremdbewertung data for ", section_name)
        return(invisible(NULL))
      }
      
      data$question_num <- as.integer(gsub("\\D", "", data$question_id))
      
      reviewers <- sort(unique(data$reviewer))
      
      peer_labels <- setNames(
        paste0("Peer ", seq_along(reviewers)),
        reviewers
      )
      
      data$peer_label <- peer_labels[data$reviewer]
      
      # ✅ Use new peer colors
      peer_colors <- SPIDER_COLORS$peers
      
      all_qnums <- sort(unique(data$question_num))
      n_questions <- length(all_qnums)
      
      angles <- seq(0, 2*pi, length.out = n_questions + 1)[1:n_questions]
      
      to_cartesian <- function(r, angle) {
        list(x = r * sin(angle), y = r * cos(angle))
      }
      
      # Grid circles
      grid_circles <- lapply(0:5, function(r) {
        angle_seq <- seq(0, 2*pi, length.out = 100)
        coords <- lapply(angle_seq, function(a) to_cartesian(r, a))
        data.frame(
          x = sapply(coords, function(c) c$x),
          y = sapply(coords, function(c) c$y),
          r = r
        )
      })
      grid_df <- do.call(rbind, grid_circles)
      
      # Axes
      axis_lines <- lapply(1:n_questions, function(i) {
        coords <- to_cartesian(5.5, angles[i])
        data.frame(x = 0, y = 0, xend = coords$x, yend = coords$y)
      })
      axis_df <- do.call(rbind, axis_lines)
      
      # Labels
      labels <- as.character(all_qnums)
      label_coords <- lapply(1:n_questions, function(i) {
        coords <- to_cartesian(6.2, angles[i])
        data.frame(x = coords$x, y = coords$y, label = labels[i])
      })
      label_df <- do.call(rbind, label_coords)
      
      # Create polygons for EACH peer
      polygon_list <- list()
      
      unique_peers <- unique(data$peer_label)
      
      for (peer in unique_peers) {
        peer_data <- data[data$peer_label == peer, ]
        
        values <- sapply(all_qnums, function(qnum) {
          row <- peer_data[peer_data$question_num == qnum, ]
          if (nrow(row) > 0) row$avg_rating[1] else NA
        })
        
        if (all(is.na(values))) next
        
        polygon_coords <- lapply(1:n_questions, function(i) {
          if (!is.na(values[i])) {
            coords <- to_cartesian(values[i], angles[i])
            data.frame(x = coords$x, y = coords$y, peer = peer)
          } else {
            NULL
          }
        })
        
        polygon_coords <- Filter(Negate(is.null), polygon_coords)
        
        if (length(polygon_coords) > 0) {
          polygon_df <- do.call(rbind, polygon_coords)
          polygon_df <- rbind(polygon_df, polygon_df[1, ])
          polygon_list[[length(polygon_list) + 1]] <- polygon_df
        }
      }
      
      all_polygons <- do.call(rbind, polygon_list)
      
      filename <- paste0("spider_fremd_", section_name, ".png")
      
      png(filename, width = 900, height = 950, res = 120)
      
      p <- ggplot() +
        geom_path(data = grid_df, aes(x = x, y = y, group = r), 
                  color = "grey85", linewidth = 0.5) +
        geom_text(data = data.frame(x = 0, y = 0:5, label = 0:5),
                  aes(x = x, y = y, label = label),
                  color = "grey50", size = 3, hjust = 1.5) +
        geom_segment(data = axis_df, 
                     aes(x = x, y = y, xend = xend, yend = yend),
                     color = "grey70", linewidth = 0.5) +
        geom_polygon(data = all_polygons, 
                     aes(x = x, y = y, fill = peer, color = peer, group = peer),
                     alpha = 0.2, linewidth = 1.2) +
        geom_text(data = label_df, aes(x = x, y = y, label = label), 
                  size = 3.5, fontface = "bold") +
        scale_fill_manual(values = peer_colors) +
        scale_color_manual(values = peer_colors) +
        ggtitle(paste("Fremdbewertung -", topic_label)) +
        coord_fixed() +
        xlim(c(-7, 7)) +
        ylim(c(-7.5, 7)) +
        theme_void() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold", margin = margin(b = 10)),
          legend.position = "bottom",
          legend.direction = "horizontal",
          legend.title = element_blank(),
          legend.text = element_text(size = 10),
          plot.margin = margin(10, 10, 40, 10)
        )
      
      print(p)
      
      dev.off()
      
      message("  ✓ Created spider_fremd_", section_name, ".png")
      
    }, error = function(e) {
      message("  ERROR creating Fremdbewertung spider plot: ", e$message)
    })
  }
  
  
  # ✅ UPDATED: Overlay with Peer 1, Peer 2, and Selbstbewertung average
  # ✅ UPDATED: Overlay with matching colors
  create_spider_plot_overlay <- function(project_id, section_name, topic_prefix, topic_label) {
    
    tryCatch({
      
      library(ggplot2)
      library(dplyr)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # Get Selbstbewertung - overall average
      selbst_query <- "
      SELECT 
        r.question_id,
        AVG(r.response_value::numeric) as avg_rating
      FROM responses r
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id
      ORDER BY r.question_id
    "
      
      selbst_data <- DBI::dbGetQuery(
        con, 
        selbst_query, 
        params = list(as.character(project_id), paste0(topic_prefix, "%"))
      )
      
      # Get Fremdbewertung BY REVIEWER
      fremd_query <- "
      SELECT 
        r.question_id,
        u.username as reviewer,
        AVG(r.response_value::numeric) as avg_rating
      FROM responses r
      JOIN users u ON u.id = r.user_id
      WHERE r.project_id = $1
        AND r.assessment_type = 'fremdbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id, u.username
      ORDER BY r.question_id, u.username
    "
      
      fremd_data <- DBI::dbGetQuery(
        con, 
        fremd_query, 
        params = list(as.character(project_id), paste0(topic_prefix, "%"))
      )
      
      if (nrow(selbst_data) == 0 && nrow(fremd_data) == 0) {
        message("  No data for overlay plot for ", section_name)
        return(invisible(NULL))
      }
      
      selbst_data$question_num <- as.integer(gsub("\\D", "", selbst_data$question_id))
      fremd_data$question_num <- as.integer(gsub("\\D", "", fremd_data$question_id))
      
      reviewers <- sort(unique(fremd_data$reviewer))
      peer_labels <- setNames(
        paste0("Peer ", seq_along(reviewers)),
        reviewers
      )
      
      fremd_data$peer_label <- peer_labels[fremd_data$reviewer]
      
      all_qnums <- sort(unique(c(selbst_data$question_num, fremd_data$question_num)))
      n_questions <- length(all_qnums)
      
      angles <- seq(0, 2*pi, length.out = n_questions + 1)[1:n_questions]
      
      to_cartesian <- function(r, angle) {
        list(x = r * sin(angle), y = r * cos(angle))
      }
      
      # Grid circles
      grid_circles <- lapply(0:5, function(r) {
        angle_seq <- seq(0, 2*pi, length.out = 100)
        coords <- lapply(angle_seq, function(a) to_cartesian(r, a))
        data.frame(
          x = sapply(coords, function(c) c$x),
          y = sapply(coords, function(c) c$y),
          r = r
        )
      })
      grid_df <- do.call(rbind, grid_circles)
      
      # Axes
      axis_lines <- lapply(1:n_questions, function(i) {
        coords <- to_cartesian(5.5, angles[i])
        data.frame(x = 0, y = 0, xend = coords$x, yend = coords$y)
      })
      axis_df <- do.call(rbind, axis_lines)
      
      # Labels
      labels <- as.character(all_qnums)
      label_coords <- lapply(1:n_questions, function(i) {
        coords <- to_cartesian(6.2, angles[i])
        data.frame(x = coords$x, y = coords$y, label = labels[i])
      })
      label_df <- do.call(rbind, label_coords)
      
      # ✅ Use overlay colors
      colors <- SPIDER_COLORS$overlay
      
      # Create polygons
      all_polygons <- list()
      
      # Selbstbewertung polygon
      if (nrow(selbst_data) > 0) {
        values_selbst <- sapply(all_qnums, function(qnum) {
          row <- selbst_data[selbst_data$question_num == qnum, ]
          if (nrow(row) > 0) row$avg_rating[1] else NA
        })
        
        if (any(!is.na(values_selbst))) {
          polygon_coords <- lapply(1:n_questions, function(i) {
            if (!is.na(values_selbst[i])) {
              coords <- to_cartesian(values_selbst[i], angles[i])
              data.frame(x = coords$x, y = coords$y, type = "Selbstbewertung")
            } else {
              NULL
            }
          })
          polygon_coords <- Filter(Negate(is.null), polygon_coords)
          selbst_poly_df <- do.call(rbind, polygon_coords)
          selbst_poly_df <- rbind(selbst_poly_df, selbst_poly_df[1, ])
          all_polygons[[1]] <- selbst_poly_df
        }
      }
      
      # Individual peer polygons
      if (nrow(fremd_data) > 0) {
        unique_peers <- unique(fremd_data$peer_label)
        
        for (peer in unique_peers) {
          peer_data <- fremd_data[fremd_data$peer_label == peer, ]
          
          values_peer <- sapply(all_qnums, function(qnum) {
            row <- peer_data[peer_data$question_num == qnum, ]
            if (nrow(row) > 0) row$avg_rating[1] else NA
          })
          
          if (any(!is.na(values_peer))) {
            polygon_coords <- lapply(1:n_questions, function(i) {
              if (!is.na(values_peer[i])) {
                coords <- to_cartesian(values_peer[i], angles[i])
                data.frame(x = coords$x, y = coords$y, type = peer)
              } else {
                NULL
              }
            })
            polygon_coords <- Filter(Negate(is.null), polygon_coords)
            peer_poly_df <- do.call(rbind, polygon_coords)
            peer_poly_df <- rbind(peer_poly_df, peer_poly_df[1, ])
            all_polygons[[length(all_polygons) + 1]] <- peer_poly_df
          }
        }
      }
      
      all_polygons_df <- do.call(rbind, all_polygons)
      
      filename <- paste0("spider_overlay_", section_name, ".png")
      
      png(filename, width = 900, height = 950, res = 120)
      
      p <- ggplot() +
        geom_path(data = grid_df, aes(x = x, y = y, group = r), 
                  color = "grey85", linewidth = 0.5) +
        geom_text(data = data.frame(x = 0, y = 0:5, label = 0:5),
                  aes(x = x, y = y, label = label),
                  color = "grey50", size = 3, hjust = 1.5) +
        geom_segment(data = axis_df, 
                     aes(x = x, y = y, xend = xend, yend = yend),
                     color = "grey70", linewidth = 0.5) +
        geom_polygon(data = all_polygons_df, 
                     aes(x = x, y = y, fill = type, color = type, group = type),
                     alpha = 0.2, linewidth = 1.2) +
        geom_text(data = label_df, aes(x = x, y = y, label = label), 
                  size = 3.5, fontface = "bold") +
        scale_fill_manual(values = colors) +
        scale_color_manual(values = colors) +
        ggtitle(paste("Vergleich: Selbst- und Fremdbewertung -", topic_label)) +
        coord_fixed() +
        xlim(c(-7, 7)) +
        ylim(c(-7.5, 7)) +
        theme_void() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold", margin = margin(b = 10)),
          legend.position = "bottom",
          legend.direction = "horizontal",
          legend.title = element_blank(),
          legend.text = element_text(size = 10),
          plot.margin = margin(10, 10, 40, 10)
        )
      
      print(p)
      
      dev.off()
      
      message("  ✓ Created spider_overlay_", section_name, ".png")
      
    }, error = function(e) {
      message("  ERROR creating overlay spider plot: ", e$message)
    })
  }
  
  # Generate comparison PDF function
  generate_comparison_pdf <- function(file, project_id, user_role = "leading_peer") {
    
    message("=== Comparison Table Download started ===")
    message("  Project ID: ", project_id)
    
    template_file <- "vergleichstabelle_template.Rmd"
    
    if (!file.exists(template_file)) {
      showNotification("Template nicht gefunden.", type = "error", duration = 10)
      writeLines("Template nicht verfügbar.", file)
      return(NULL)
    }
    
    tryCatch({
      
      template_path <- normalizePath(template_file, mustWork = TRUE)
      tmpdir <- tempdir()
      owd <- setwd(tmpdir)
      on.exit(setwd(owd), add = TRUE)
      
      file.copy(template_path, file.path(tmpdir, template_file), overwrite = TRUE)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # Get project title
      project_title <- tryCatch({
        result <- DBI::dbGetQuery(con,
                                  "SELECT title FROM projects WHERE id = $1",
                                  params = list(as.integer(project_id)))
        
        if (nrow(result) > 0 && !is.null(result$title[1]) && nzchar(result$title[1])) {
          result$title[1]
        } else {
          "Projekt"
        }
      }, error = function(e) {
        "Projekt"
      })
      
      message("  Project Title: ", project_title)
      
      # Export question lists
      export_questions <- function(questions, filename) {
        df <- data.frame(
          id = sapply(questions, function(q) q$id),
          label = sapply(questions, function(q) q$label),
          stringsAsFactors = FALSE
        )
        write.csv(df, file.path(tmpdir, filename), row.names = FALSE, fileEncoding = "UTF-8")
      }
      
      export_questions(fuehrung_questions, "fuehrung_questions.csv")
      export_questions(mit_questions, "mitarbeitende_questions.csv")
      export_questions(pat_questions, "patienten_questions.csv")
      export_questions(ein_questions, "einsender_questions.csv")
      export_questions(qual_questions, "qualitaet_questions.csv")
      
      # Save project_id
      write.csv(
        data.frame(project_id = project_id),
        file.path(tmpdir, "project_info.csv"),
        row.names = FALSE
      )
      
      message("  ✓ Data exported")
      
      # ✅ Generate spider plots for Selbst and Fremd
      message("  Generating spider plots...")
      
      create_spider_plot_selbst(project_id, "fuehrung", "F", "Führung")
      create_spider_plot_fremd(project_id, "fuehrung", "F", "Führung")
      create_spider_plot_overlay(project_id, "fuehrung", "F", "Führung")
      
      create_spider_plot_selbst(project_id, "mitarbeitende", "M", "Mitarbeitende")
      create_spider_plot_fremd(project_id, "mitarbeitende", "M", "Mitarbeitende")
      create_spider_plot_overlay(project_id, "mitarbeitende", "M", "Mitarbeitende")
      
      create_spider_plot_selbst(project_id, "patienten", "P", "Patienten")
      create_spider_plot_fremd(project_id, "patienten", "P", "Patienten")
      create_spider_plot_overlay(project_id, "patienten", "P", "Patienten")
      
      create_spider_plot_selbst(project_id, "einsender", "E", "Einsender")
      create_spider_plot_fremd(project_id, "einsender", "E", "Einsender")
      create_spider_plot_overlay(project_id, "einsender", "E", "Einsender")
      
      create_spider_plot_selbst(project_id, "qualitaet", "Q", "Qualität")
      create_spider_plot_fremd(project_id, "qualitaet", "Q", "Qualität")
      create_spider_plot_overlay(project_id, "qualitaet", "Q", "Qualität")
      
      message("  ✓ Spider plots created")
      
      # Render PDF
      message("  Rendering PDF...")
      
      output_file <- rmarkdown::render(
        input = file.path(tmpdir, template_file),
        output_format = "pdf_document",
        output_file = "comparison.pdf",
        output_dir = tmpdir,
        params = list(
          project_title = project_title,
          project_id = project_id
        ),
        envir = new.env(),
        quiet = FALSE
      )
      
      message("  ✓ PDF rendered")
      
      if (file.exists(output_file)) {
        file.copy(output_file, file, overwrite = TRUE)
        message("  ✓ PDF copied")
      } else {
        stop("PDF was not created")
      }
      
      message("=== Comparison Table Download completed ===")
      
    }, error = function(e) {
      message("ERROR: ", e$message)
      showNotification(paste("Fehler:", e$message), type = "error", duration = 10)
      writeLines(paste("Fehler:", e$message), file)
    })
  }
  
   
  #------------------comprehensive summary download-------------------------------
  
  output$download_comprehensive_summary <- downloadHandler(
    filename = function() {
      project_name <- current_project_name()
      if (is.null(project_name) || project_name == "") project_name <- "Projekt"
      paste0("Gesamtbericht_", gsub("[^A-Za-z0-9_-]", "_", project_name), "_", format(Sys.Date(), "%Y%m%d"), ".pdf")
    },
    
    content = function(file) {
      
      message("=== Starting comprehensive summary PDF ===")
      
      project_id <- current_project_id()
      project_name <- current_project_name()
      
      req(project_id, project_name)
      
      showNotification("PDF wird erstellt... Bitte warten.", type = "message", duration = NULL, id = "pdf_progress")
      
      template_file <- "comprehensive_summary_report.Rmd"
      
      if (!file.exists(template_file)) {
        showNotification("Template nicht gefunden.", type = "error", duration = 10)
        removeNotification("pdf_progress")
        return(NULL)
      }
      
      tryCatch({
        
        # Set up temp directory
        tmpdir <- tempdir()
        owd <- setwd(tmpdir)
        on.exit(setwd(owd), add = TRUE)
        
        message("Step 1: Copying template")
        file.copy(normalizePath(template_file), file.path(tmpdir, template_file), overwrite = TRUE)
        
        # Get database connection
        con <- get_db_con()
        on.exit(DBI::dbDisconnect(con), add = TRUE)
        
        # Step 2: Get lab info
        message("Step 2: Getting lab info")
        labinfo <- DBI::dbGetQuery(
          con,
          "SELECT * FROM lab_info WHERE project_id = $1",
          params = list(project_id)
        )
        
        if (nrow(labinfo) > 0) {
          write.csv(labinfo, file.path(tmpdir, "labinfo.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        }
        
        # Step 3: Get responses for all topics
        message("Step 3: Getting responses")
        
        fuehrung_responses <- get_topic_responses_summary(project_id, "F", fuehrung_questions)
        mitarbeitende_responses <- get_topic_responses_summary(project_id, "M", mit_questions)
        pat_responses <- get_topic_responses_summary(project_id, "P", pat_questions)
        ein_responses <- get_topic_responses_summary(project_id, "E", ein_questions)
        qual_responses <- get_topic_responses_summary(project_id, "Q", qual_questions)
        
        write.csv(fuehrung_responses, file.path(tmpdir, "fuehrung_responses.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(mitarbeitende_responses, file.path(tmpdir, "mitarbeitende_responses.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(pat_responses, file.path(tmpdir, "pat_responses.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(ein_responses, file.path(tmpdir, "ein_responses.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(qual_responses, file.path(tmpdir, "qual_responses.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        
        # Step 4: Get statistics
        message("Step 4: Getting statistics")
        
        fuehrung_stats <- get_topic_weighted_stats(project_id, "fuehrung")
        mitarbeitende_stats <- get_topic_weighted_stats(project_id, "mitarbeitende")
        pat_stats <- get_topic_weighted_stats(project_id, "patienten")
        ein_stats <- get_topic_weighted_stats(project_id, "einsender")
        qual_stats <- get_topic_weighted_stats(project_id, "qualitaet")
        
        write.csv(fuehrung_stats, file.path(tmpdir, "fuehrung_stats.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(mitarbeitende_stats, file.path(tmpdir, "mitarbeitende_stats.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(pat_stats, file.path(tmpdir, "pat_stats.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(ein_stats, file.path(tmpdir, "ein_stats.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        write.csv(qual_stats, file.path(tmpdir, "qual_stats.csv"), row.names = FALSE, fileEncoding = "UTF-8")
        
        # Step 5: Create ggradar plots
        message("Step 5: Creating radar plots")
        
        mit_binary_global_qnums <- c(10, 20, 24)
        
        plot_configs <- list(
          list(name = "fuehrung", questions = fuehrung_questions, title = "Führung", 
               colour = "#003B73", binary_qnums = integer(0)),
          list(name = "mit", questions = mit_questions, title = "Mitarbeitende", 
               colour = "#136377", binary_qnums = mit_binary_global_qnums),
          list(name = "pat", questions = pat_questions, title = "Patienten", 
               colour = "#b23a48", binary_qnums = integer(0)),
          list(name = "ein", questions = ein_questions, title = "Einsender", 
               colour = "#4b61d1", binary_qnums = integer(0)),
          list(name = "qual", questions = qual_questions, title = "Qualität", 
               colour = "#c58f00", binary_qnums = integer(0))
        )
        
        for (config in plot_configs) {
          plot_file <- file.path(tmpdir, paste0("plot_", config$name, ".png"))
          message(paste("  Creating plot:", config$title))
          
          tryCatch({
            # Get average responses for radar plot
            question_ids <- sapply(
              if (length(config$binary_qnums) > 0) {
                Filter(function(q) !(q$number %in% config$binary_qnums), config$questions)
              } else {
                config$questions
              },
              function(q) q$id
            )
            
            responses <- DBI::dbGetQuery(
              con,
              sprintf(
                "SELECT question_id, AVG(response_value::numeric) as avg_value
               FROM responses
               WHERE project_id = $1
                 AND assessment_type = 'selbstbewertung'
                 AND question_id IN (%s)
                 AND response_value IS NOT NULL
                 AND response_value != ''
               GROUP BY question_id",
                paste0("'", question_ids, "'", collapse = ", ")
              ),
              params = list(project_id)
            )
            
            if (nrow(responses) > 0) {
              # Create radar data frame for ggradar
              values <- sapply(question_ids, function(qid) {
                row <- responses[responses$question_id == qid, ]
                if (nrow(row) > 0) row$avg_value else 0
              })
              
              radar_df <- data.frame(
                group = config$title,
                t(values)
              )
              colnames(radar_df) <- c("group", paste0("Q", seq_along(values)))
              
              # Add min/max rows
              max_row <- radar_df
              max_row$group <- "Max"
              max_row[, -1] <- 5
              
              min_row <- radar_df
              min_row$group <- "Min"
              min_row[, -1] <- 0
              
              radar_df_full <- rbind(max_row, min_row, radar_df)
              
              # Create plot using fmsb-style function
              make_fmsb_radar_png(
                radar_df = radar_df_full[3, -1],  # Just the data row
                title = config$title,
                colour = config$colour,
                filename = plot_file,
                width = 900,
                height = 700
              )
            } else {
              # Create placeholder
              png(plot_file, width = 800, height = 600)
              plot.new()
              text(0.5, 0.5, "Keine Daten verfügbar", cex = 1.5)
              dev.off()
            }
          }, error = function(e) {
            message(paste("    ERROR:", e$message))
            png(plot_file, width = 800, height = 600)
            plot.new()
            text(0.5, 0.5, paste("Fehler:\n", config$title), cex = 1.5)
            dev.off()
          })
        }
        
        # Step 6: Render PDF
        message("Step 6: Rendering PDF")
        
        output_file <- rmarkdown::render(
          input = file.path(tmpdir, template_file),
          output_format = "pdf_document",
          output_file = "report.pdf",
          output_dir = tmpdir,
          params = list(
            project_title = project_name,
            project_id = project_id
          ),
          envir = new.env(),
          quiet = FALSE
        )
        
        # Step 7: Copy to destination
        message("Step 7: Copying PDF")
        file.copy(output_file, file, overwrite = TRUE)
        
        removeNotification("pdf_progress")
        showNotification("PDF erfolgreich erstellt!", type = "message", duration = 5)
        
        message("=== PDF completed successfully ===")
        
      }, error = function(e) {
        message("=== ERROR ===")
        message(paste("Message:", e$message))
        
        removeNotification("pdf_progress")
        showNotification(
          paste("Fehler beim Erstellen des PDFs:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
  
  
  
}


shinyApp(ui = ui, server = server)


